        const roadCondCfg = CONFIG.CONDITION_LEVELS ? CONFIG.CONDITION_LEVELS[road.condition || 'new'] : null;
        const roadCondIcon = roadCondCfg ? roadCondCfg.icon : '✨';
        const roadCondName = roadCondCfg ? roadCondCfg.name : 'New';
