    function showEventDetail(eventIndex) {
        var events = openEventLog._cachedEvents;
        if (!events || eventIndex >= events.length) return;
        var event = events[eventIndex];

        var html = '<div class="event-detail-panel">';

        // Main message
        html += '<div class="event-detail-message" style="font-size:1.1rem;margin-bottom:12px;color:var(--gold-bright);">' + (event.message || event.description || 'Event') + '</div>';
        html += '<div class="event-detail-day" style="color:var(--text-dim);margin-bottom:12px;">Day ' + (event.day || '?') + '</div>';

        if (event.details) {
            // Error alert detail
            if (event.details.type === 'error_alert') {
                html += '<div style="margin-bottom:10px;">';
                html += '<div style="color:#c44e52;font-weight:bold;margin-bottom:4px;">🐛 Error Source: ' + (event.details.source || 'Unknown') + '</div>';
                html += '<pre style="color:var(--parchment);background:rgba(0,0,0,0.3);padding:8px;border-radius:4px;white-space:pre-wrap;word-break:break-all;font-size:0.8rem;max-height:300px;overflow-y:auto;">' + (event.details.fullError || 'No details') + '</pre>';
                html += '</div>';
            }

            // Royal Consultation — open consultation dialog
            if (event.details.type === 'royal_consultation' && event.details.kingdomId && event.details.decisionId) {
                html += '<div style="margin:12px 0;"><button class="btn-medieval" style="background:rgba(255,215,0,0.15);border-color:rgba(255,215,0,0.4);font-size:1rem;" onclick="UI.closeModal();UI.openKingConsultationDialog(\'' + event.details.kingdomId + '\',\'' + event.details.decisionId + '\')">👑 Respond to King\'s Proposal</button></div>';
            }

            // Cause
            if (event.details.cause) {
                html += '<div style="margin-bottom:10px;">';
                html += '<div style="color:var(--gold);font-weight:bold;margin-bottom:4px;">\uD83D\uDCD6 Why This Happened</div>';
                html += '<div style="color:var(--parchment);">' + event.details.cause + '</div>';
                html += '</div>';
            }

            // Effects
            if (event.details.effects && event.details.effects.length > 0) {
                html += '<div style="margin-bottom:10px;">';
                html += '<div style="color:var(--gold);font-weight:bold;margin-bottom:4px;">\u26A1 Effects</div>';
                html += '<ul style="margin:0;padding-left:20px;">';
                for (var ei = 0; ei < event.details.effects.length; ei++) {
                    html += '<li style="color:var(--parchment);margin-bottom:4px;">' + event.details.effects[ei] + '</li>';
                }
                html += '</ul></div>';
            }
        } else {
            html += '<div style="color:var(--text-dim);font-style:italic;">No additional details available for this event.</div>';
        }

        // ── Notification Filter Info & Mute Button ──
        var evtCategory = event.category || 'local_town';
        var evtMsg = event.message || event.description || '';
        var filterInfo = null;
        try { if (typeof Player !== 'undefined' && Player.getEventFilterInfo) filterInfo = Player.getEventFilterInfo(evtCategory, evtMsg); } catch(e) {}

        if (filterInfo) {
            var catLabel = evtCategory;
            var subLabel = null;
            var muteKey = evtCategory; // default: mute entire category
            var muteLabel = catLabel;

            // Look up human-readable labels from filterDefs
            var _fdLookup = _getFilterDefsLookup();
            if (_fdLookup[evtCategory]) catLabel = _fdLookup[evtCategory].label;
            if (filterInfo.subKey && _fdLookup[filterInfo.subKey]) {
                subLabel = _fdLookup[filterInfo.subKey].label;
                muteKey = filterInfo.subKey;
                muteLabel = subLabel;
            } else if (filterInfo.subKey) {
                // subKey exists but no label found — use the raw key as label
                var _parts = filterInfo.subKey.split('.');
                subLabel = _parts[_parts.length - 1].replace(/_/g, ' ');
                subLabel = subLabel.charAt(0).toUpperCase() + subLabel.slice(1);
                muteKey = filterInfo.subKey;
                muteLabel = subLabel;
            }

            html += '<div style="margin-top:12px;padding-top:10px;border-top:1px solid rgba(255,215,0,0.15);">';
            html += '<div style="color:var(--text-dim);font-size:0.85rem;margin-bottom:6px;">📂 ' + catLabel + (subLabel ? ' › ' + subLabel : '') + '</div>';

            // Check current filter state
            var filters = {};
            try { if (typeof Player !== 'undefined' && Player.getNotificationFilters) filters = Player.getNotificationFilters(); } catch(e) {}
            var isCurrentlyOff = filters[muteKey] === false;

            if (isCurrentlyOff) {
                html += '<button class="btn-action" style="font-size:0.85rem;padding:4px 12px;background:rgba(50,180,50,0.2);border-color:rgba(50,180,50,0.5);" onclick="Player.setNotifFilter(\'' + muteKey + '\', true);UI.showEventDetail(' + eventIndex + ');">🔔 Unmute ' + muteLabel + '</button>';
            } else {
                html += '<button class="btn-action" style="font-size:0.85rem;padding:4px 12px;background:rgba(180,50,50,0.2);border-color:rgba(180,50,50,0.5);" onclick="Player.setNotifFilter(\'' + muteKey + '\', false);UI.showEventDetail(' + eventIndex + ');">🔇 Mute ' + muteLabel + '</button>';
            }
            html += '</div>';
        }

        // Universal location button — check all possible townId sources
        var locTownId = (event.details && event.details.townId) || event.townId || null;
        // Try to infer town from message if no explicit townId
        if (!locTownId) {
            try {
                var towns = Engine.getTowns();
                if (towns) {
                    var msg = (event.message || event.description || '').toLowerCase();
                    for (var _ti = 0; _ti < towns.length; _ti++) {
                        if (towns[_ti].name && msg.indexOf(towns[_ti].name.toLowerCase()) !== -1) {
                            locTownId = towns[_ti].id;
                            break;
                        }
                    }
                }
            } catch (e) { /* ignore */ }
        }
        if (locTownId) {
            html += '<button class="btn-action" style="margin-top:8px;" onclick="UI.clickTown(\'' + locTownId + '\');">🗺️ View Location</button>';
        }

        html += '</div>';

        openModal('\uD83D\uDCCB Event Details', html, '<button class="btn-action" data-action="closeModal">Close</button>');
    }

    // ═══════════════════════════════════════════════════════════
    //  TOASTS / NOTIFICATIONS
    // ═══════════════════════════════════════════════════════════

    function toast(message, type, category, _skipEventLog) {
        type = type || 'info';
        category = category || 'my_actions';

        // Log to engine event log unless called from processEvents (prevents circular toast→log→process→toast loop)
        if (!_skipEventLog) {
            try {
                if (typeof Engine !== 'undefined' && Engine.getEvents && Engine.logEvent) {
                    var events = Engine.getEvents();
                    var day = Engine.getDay ? Engine.getDay() : 0;
                    var alreadyLogged = false;
                    // Check last 5 events for a duplicate within same day
                    for (var _di = events.length - 1; _di >= Math.max(0, events.length - 5); _di--) {
                        if (events[_di].day === day && events[_di].message === message) {
                            alreadyLogged = true;
                            break;
                        }
                    }
                    if (!alreadyLogged) {
                        Engine.logEvent(message, null, category);
                    }
                }
            } catch(e) { /* ignore logging errors */ }
        }

        // Check notification filter for popup suppression (toasts can be suppressed but log entry persists)
        if (typeof Player !== 'undefined' && Player.shouldShowNotification) {
            if (!Player.shouldShowNotification(category, null, message)) return;
        }

        // Master toast mute — suppress all popups except critical (death, jail, bankruptcy)
        if (_toastsMuted && category !== 'critical') return;

        const icons = { info: 'ℹ️', warning: '⚠️', danger: '🔴', success: '✅', achievement: '🏆' };
        const id = 'toast_' + (toastId++);

        // Store notification with index for detail lookup
        var notifIndex = notifications.length;
        notifications.push({ id, message, type, time: Date.now(), category: category });

        const toastEl = document.createElement('div');
        toastEl.className = `toast toast-${type}`;
        toastEl.id = id;
        toastEl.style.cursor = 'pointer';
        toastEl.innerHTML = `<span class="toast-icon">${icons[type] || ''}</span> ${message}`;
        toastEl.addEventListener('click', function() {
            dismissToast(id);
            // Open event log to show the most recent matching event
            openEventLog();
        });

        el.toastContainer.appendChild(toastEl);
        updateNotifCount();

        // Auto-dismiss after 5 seconds
        setTimeout(() => dismissToast(id), 5000);
    }

    function dismissToast(id) {
        const toastEl = document.getElementById(id);
        if (!toastEl) return;
        toastEl.classList.add('toast-out');
        setTimeout(() => {
            if (toastEl.parentNode) toastEl.parentNode.removeChild(toastEl);
        }, 300);
    }

    function updateNotifCount() {
        // Show count of unread events since last time log was opened
        var totalEvents = 0;
        try {
            var evts = Engine.getEvents();
            totalEvents = evts ? evts.length : 0;
        } catch (e) { totalEvents = 0; }
        var unread = Math.max(0, totalEvents - _lastSeenEventCount);
        if (el.notifCount) {
            if (unread > 0) {
                el.notifCount.textContent = unread > 99 ? '99+' : unread;
                el.notifCount.classList.remove('hidden');
            } else {
                el.notifCount.classList.add('hidden');
            }
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  TOOLTIP
    // ═══════════════════════════════════════════════════════════

    function showTooltip(x, y, text) {
        if (!el.tooltip) return;
        el.tooltip.textContent = text;
        el.tooltip.classList.remove('hidden');
        // Position near cursor, keep on screen
        const ttw = el.tooltip.offsetWidth;
        const tth = el.tooltip.offsetHeight;
        let tx = x + 12;
        let ty = y + 12;
        if (tx + ttw > window.innerWidth - 8) tx = x - ttw - 8;
        if (ty + tth > window.innerHeight - 8) ty = y - tth - 8;
        if (tx < 4) tx = 4;
        if (ty < 4) ty = 4;
        el.tooltip.style.left = tx + 'px';
        el.tooltip.style.top = ty + 'px';
    }

    function hideTooltip() {
        if (el.tooltip) el.tooltip.classList.add('hidden');
    }

    // ═══════════════════════════════════════════════════════════
    //  CONTEXT MENU
    // ═══════════════════════════════════════════════════════════

    function showContextMenu(x, y, items) {
        if (!el.contextMenu) return;
        const container = el.contextMenu.querySelector('.context-menu-items');
        if (!container) return;
        let html = '';
        for (const item of items) {
            if (item.separator) {
                html += '<div class="ctx-separator"></div>';
            } else {
                html += `<div class="ctx-item ${item.disabled ? 'disabled' : ''}" onclick="${item.disabled ? '' : item.action}">
                    ${item.icon || ''} ${item.label}
                </div>`;
            }
        }
        container.innerHTML = html;
        el.contextMenu.classList.remove('hidden');

        // Position
        let cx = x;
        let cy = y;
        if (cx + 180 > window.innerWidth) cx = x - 180;
        if (cy + 200 > window.innerHeight) cy = y - 200;
        el.contextMenu.style.left = cx + 'px';
        el.contextMenu.style.top = cy + 'px';
    }

    function hideContextMenu() {
        if (el.contextMenu) el.contextMenu.classList.add('hidden');
    }

    // ═══════════════════════════════════════════════════════════
    //  WAR ALLEGIANCE POPUP
    // ═══════════════════════════════════════════════════════════

    function showWarAllegiancePopup(warEvent) {
        if (!warEvent) return;
        const nameA = warEvent.nameA || 'Kingdom A';
        const nameB = warEvent.nameB || 'Kingdom B';
        const strengthA = warEvent.strengthA || 0;
        const strengthB = warEvent.strengthB || 0;
        const warId = warEvent.warId;

        // Get military breakdown
        let breakdownA = { infantry: 0, archers: 0, cavalry: 0 };
        let breakdownB = { infantry: 0, archers: 0, cavalry: 0 };
        try {
            if (Engine.getMilitaryBreakdown) {
                breakdownA = Engine.getMilitaryBreakdown(warEvent.kingdomA) || breakdownA;
                breakdownB = Engine.getMilitaryBreakdown(warEvent.kingdomB) || breakdownB;
            }
        } catch (e) { /* no-op */ }

        // Build strength bars
        const maxStr = Math.max(strengthA, strengthB, 1);
        const barA = Math.round((strengthA / maxStr) * 10);
        const barB = Math.round((strengthB / maxStr) * 10);
        const barStrA = '█'.repeat(barA) + '░'.repeat(10 - barA);
        const barStrB = '█'.repeat(barB) + '░'.repeat(10 - barB);

        // Determine player context
        let contextLine = '';
        const pCitizenA = Player.isPlayerCitizenOf ? Player.isPlayerCitizenOf(warEvent.kingdomA) : (Player.citizenshipKingdomId === warEvent.kingdomA);
        const pCitizenB = Player.isPlayerCitizenOf ? Player.isPlayerCitizenOf(warEvent.kingdomB) : (Player.citizenshipKingdomId === warEvent.kingdomB);
        if (pCitizenA || pCitizenB) {
            const citizenName = pCitizenA ? nameA : nameB;
            contextLine = `As a citizen of <strong>${citizenName}</strong> with military trade interests, you must decide:`;
        } else {
            contextLine = 'As a merchant with military trade interests, you must decide:';
        }

        const bodyHtml = `
            <div style="text-align:center;padding:10px;">
                <h2 style="color:#c44e52;margin:0 0 10px 0;">⚔️ WAR DECLARED! ⚔️</h2>
                <p style="font-size:1.1em;margin-bottom:15px;"><strong>${nameA}</strong> has declared war on <strong>${nameB}</strong>!</p>
                <div style="background:#1a1a2e;padding:12px;border-radius:6px;margin-bottom:15px;text-align:left;font-family:monospace;">
                    <div style="margin-bottom:8px;"><strong>Military Comparison:</strong></div>
                    <div style="margin-bottom:4px;">${nameA}: <span style="color:#4ecdc4;">${barStrA}</span> ~${strengthA} strength</div>
                    <div style="font-size:0.85em;color:#888;margin-bottom:8px;">  ${(breakdownA.infantry || breakdownA.archers || breakdownA.cavalry) ? 'Infantry: ' + (breakdownA.infantry || 0) + ' | Archers: ' + (breakdownA.archers || 0) + ' | Cavalry: ' + (breakdownA.cavalry || 0) : 'Soldiers: ' + (breakdownA.soldiers || breakdownA.total || 0) + ' | Garrison: ' + (breakdownA.garrison || 0)}</div>
                    <div style="margin-bottom:4px;">${nameB}: <span style="color:#ff6b6b;">${barStrB}</span> ~${strengthB} strength</div>
                    <div style="font-size:0.85em;color:#888;">  ${(breakdownB.infantry || breakdownB.archers || breakdownB.cavalry) ? 'Infantry: ' + (breakdownB.infantry || 0) + ' | Archers: ' + (breakdownB.archers || 0) + ' | Cavalry: ' + (breakdownB.cavalry || 0) : 'Soldiers: ' + (breakdownB.soldiers || breakdownB.total || 0) + ' | Garrison: ' + (breakdownB.garrison || 0)}</div>
                </div>
                <p style="margin-bottom:15px;">${contextLine}</p>
            </div>
        `;

        const footerHtml = `
            <button class="btn" onclick="UI.chooseWarAllegiance('${warId}','neutral')" style="margin:4px;position:relative;" title="Stay Neutral&#10;&#10;✅ Trade freely with BOTH sides&#10;✅ No reputation change&#10;✅ No war-end reward or punishment&#10;&#10;⚠️ Military sales to both sides are tracked&#10;⚠️ Lopsided sales (2:1+) trigger warnings&#10;⚠️ At 3:1 ratio: extra 10% tax from disadvantaged side&#10;⚠️ At 5:1 ratio: building seizure risk&#10;⚠️ At 10:1 ratio: total asset seizure + reputation destroyed">🕊️ Stay Neutral</button>
            <button class="btn" onclick="UI.chooseWarAllegiance('${warId}','${warEvent.kingdomA}')" style="margin:4px;" title="Side with ${nameA}&#10;&#10;IMMEDIATE:&#10;✅ +5 reputation with ${nameA}&#10;❌ -5 reputation with ${nameB}&#10;❌ -5 relationship with ${nameB} king + nobles&#10;❌ Rank in ${nameB} becomes 'Enemy' (peasant privileges)&#10;❌ Cannot hire workers in military buildings in ${nameB}&#10;❌ +50% encounters, +25% danger in ${nameB} territory&#10;&#10;IF ${nameA} WINS:&#10;✅ +5 to +20 rep (scaled by military sales + status)&#10;✅ +10 king relationship, +5 all noble relationships&#10;✅ War Hero achievement&#10;✅ Guaranteed petition (no signatures needed)&#10;✅ Up to 5000g reward&#10;&#10;IF ${nameA} LOSES:&#10;❌ Up to 5000g retribution&#10;❌ -10 to -20 rep with BOTH kingdoms&#10;❌ -10 relationship with BOTH kings&#10;❌ -5 relationship with ALL nobles&#10;❌ Buildings in ${nameB} seized&#10;❌ Possible jail time&#10;&#10;⚠️ Choice is PERMANENT — cannot change sides!">⚔️ Side with ${nameA}</button>
            <button class="btn" onclick="UI.chooseWarAllegiance('${warId}','${warEvent.kingdomB}')" style="margin:4px;" title="Side with ${nameB}&#10;&#10;IMMEDIATE:&#10;✅ +5 reputation with ${nameB}&#10;❌ -5 reputation with ${nameA}&#10;❌ -5 relationship with ${nameA} king + nobles&#10;❌ Rank in ${nameA} becomes 'Enemy' (peasant privileges)&#10;❌ Cannot hire workers in military buildings in ${nameA}&#10;❌ +50% encounters, +25% danger in ${nameA} territory&#10;&#10;IF ${nameB} WINS:&#10;✅ +5 to +20 rep (scaled by military sales + status)&#10;✅ +10 king relationship, +5 all noble relationships&#10;✅ War Hero achievement&#10;✅ Guaranteed petition (no signatures needed)&#10;✅ Up to 5000g reward&#10;&#10;IF ${nameB} LOSES:&#10;❌ Up to 5000g retribution&#10;❌ -10 to -20 rep with BOTH kingdoms&#10;❌ -10 relationship with BOTH kings&#10;❌ -5 relationship with ALL nobles&#10;❌ Buildings in ${nameA} seized&#10;❌ Possible jail time&#10;&#10;⚠️ Choice is PERMANENT — cannot change sides!">⚔️ Side with ${nameB}</button>
        `;

        // Pause game during popup
        if (typeof Game !== 'undefined' && Game.setSpeed) {
            Game._preWarSpeed = Game.getSpeed ? Game.getSpeed() : 1;
            Game.setSpeed(0);
        }

        openModal('⚔️ War Declaration', bodyHtml, footerHtml);
    }

    function chooseWarAllegiance(warId, side) {
        if (typeof Player !== 'undefined' && Player.setWarAllegiance) {
            Player.setWarAllegiance(warId, side);
        }
        closeModal();
        // Restore game speed
        if (typeof Game !== 'undefined' && Game.setSpeed && Game._preWarSpeed) {
            Game.setSpeed(Game._preWarSpeed);
            Game._preWarSpeed = null;
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  BANKRUPTCY DIALOG
    // ═══════════════════════════════════════════════════════════

    function showBankruptcyDialog(debtAmount, choices) {
        _bankruptcyLock = true;
        var bodyHtml = '<div style="padding:15px;text-align:center;">';
        bodyHtml += '<p style="color:#ff6b6b;font-size:18px;margin-bottom:10px;">💸 You are bankrupt!</p>';
        bodyHtml += '<p style="color:#ccc;font-size:14px;margin-bottom:5px;">You have been in debt for 7 consecutive days with no assets to seize.</p>';
        bodyHtml += '<p style="color:#ff9;font-size:14px;margin-bottom:20px;">Outstanding debt: <strong>' + debtAmount + 'g</strong></p>';
        bodyHtml += '<p style="color:#aaa;font-size:13px;margin-bottom:15px;">The kingdom demands you choose your fate:</p>';
        bodyHtml += '</div>';

        bodyHtml += '<div style="display:flex;flex-direction:column;gap:10px;padding:0 15px 15px;">';

        for (var i = 0; i < choices.length; i++) {
            var ch = choices[i];
            var borderColor = ch.available ? (ch.id === 'indenture' ? '#c4a' : ch.id === 'military' ? '#a44' : ch.id === 'guild_loan' ? '#a80' : '#5a5') : '#444';
            var bgColor = ch.available ? (ch.id === 'indenture' ? '#3a1a2a' : ch.id === 'military' ? '#3a1a1a' : ch.id === 'guild_loan' ? '#2a1a0a' : '#1a2a1a') : '#1a1a1a';
            var opacity = ch.available ? '1' : '0.5';
            var cursor = ch.available ? 'pointer' : 'not-allowed';

            // Guild loan opens a sub-dialog instead of directly choosing
            var clickHandler = '';
            if (ch.available) {
                if (ch.id === 'guild_loan') {
                    clickHandler = 'onclick="UI.showGuildLoanDialog()"';
                } else {
                    clickHandler = 'onclick="UI.handleBankruptcyChoice(\'' + ch.id + '\')"';
                }
            }

            bodyHtml += '<div ' + clickHandler + ' style="';
            bodyHtml += 'border:2px solid ' + borderColor + ';background:' + bgColor + ';padding:14px;border-radius:8px;';
            bodyHtml += 'cursor:' + cursor + ';opacity:' + opacity + ';transition:all 0.2s;text-align:left;"';
            if (ch.available) {
                bodyHtml += ' onmouseover="this.style.borderColor=\'#fff\';this.style.transform=\'scale(1.02)\'"';
                bodyHtml += ' onmouseout="this.style.borderColor=\'' + borderColor + '\';this.style.transform=\'scale(1)\'"';
            }
            bodyHtml += '>';

            bodyHtml += '<div style="font-size:15px;font-weight:bold;color:' + (ch.available ? '#fff' : '#666') + ';margin-bottom:6px;">' + ch.label + '</div>';
            bodyHtml += '<div style="font-size:12px;color:' + (ch.available ? '#ccc' : '#555') + ';margin-bottom:6px;">' + ch.description + '</div>';
            bodyHtml += '<div style="font-size:11px;color:' + (ch.available ? '#999' : '#444') + ';">' + ch.detail + '</div>';

            bodyHtml += '</div>';
        }

        bodyHtml += '</div>';

        // Save/Load/Main Menu buttons — always accessible during bankruptcy
        bodyHtml += '<div style="display:flex;gap:8px;justify-content:center;padding:10px 15px 15px;border-top:1px solid #333;margin-top:5px;">';
        bodyHtml += '<button onclick="if(typeof Game!==\'undefined\'&&Game.save)Game.save()" style="padding:6px 14px;background:#2a3a2a;color:#9d9;border:1px solid #5a5;border-radius:4px;cursor:pointer;font-size:12px;">💾 Save</button>';
        bodyHtml += '<button onclick="if(typeof Game!==\'undefined\'&&Game.load)Game.load()" style="padding:6px 14px;background:#2a2a3a;color:#99d;border:1px solid #55a;border-radius:4px;cursor:pointer;font-size:12px;">📂 Load</button>';
        bodyHtml += '<button onclick="UI.backToMainMenu()" style="padding:6px 14px;background:#3a2a1a;color:#da9;border:1px solid #a85;border-radius:4px;cursor:pointer;font-size:12px;">🏠 Main Menu</button>';
        bodyHtml += '</div>';

        openModal('💸 Bankruptcy', bodyHtml, '');

        // Hide close button — player MUST choose a bankruptcy option (like encounters)
        var closeBtn = document.getElementById('btnCloseModal');
        if (closeBtn) closeBtn.style.display = 'none';
    }

    function showGuildLoanDialog() {
        if (typeof Player === 'undefined' || !Player.getGuildLoanOffers) return;

        var offers = Player.getGuildLoanOffers();

        var bodyHtml = '<div style="padding:15px;text-align:center;">';
        bodyHtml += '<p style="color:#ffa500;font-size:18px;margin-bottom:10px;">🏛️ Guild Loan Offers</p>';
        bodyHtml += '<p style="color:#ccc;font-size:13px;margin-bottom:15px;">Select a guild to borrow from. Terms: 10% annual interest, 2 year repayment, auto-payments every 30 days.</p>';
        bodyHtml += '</div>';

        bodyHtml += '<div style="display:flex;flex-direction:column;gap:8px;padding:0 15px 10px;max-height:400px;overflow-y:auto;">';

        for (var i = 0; i < offers.length; i++) {
            var offer = offers[i];
            var avail = offer.available;
            var borderColor = avail ? '#a80' : '#444';
            var bgColor = avail ? '#2a1a0a' : '#1a1a1a';
            var opacity = avail ? '1' : '0.5';
            var cursor = avail ? 'pointer' : 'not-allowed';

            var clickHandler = '';
            if (avail) {
                clickHandler = 'onclick="UI.handleGuildLoanAccept(\'' + offer.guildId + '\')"';
            }

            bodyHtml += '<div ' + clickHandler + ' style="';
            bodyHtml += 'border:2px solid ' + borderColor + ';background:' + bgColor + ';padding:12px;border-radius:8px;';
            bodyHtml += 'cursor:' + cursor + ';opacity:' + opacity + ';transition:all 0.2s;text-align:left;"';
            if (avail) {
                bodyHtml += ' onmouseover="this.style.borderColor=\'#fff\';this.style.transform=\'scale(1.02)\'"';
                bodyHtml += ' onmouseout="this.style.borderColor=\'' + borderColor + '\';this.style.transform=\'scale(1)\'"';
            }
            bodyHtml += '>';

            bodyHtml += '<div style="font-size:14px;font-weight:bold;color:' + (avail ? '#fff' : '#666') + ';margin-bottom:4px;">';
            bodyHtml += (offer.guildIcon || '🏛️') + ' ' + (offer.guildName || offer.guildId);
            bodyHtml += '</div>';

            if (avail) {
                bodyHtml += '<div style="font-size:12px;color:#ccc;margin-bottom:4px;">';
                bodyHtml += 'Loan: <strong style="color:#ffd700;">' + offer.amount + 'g</strong>';
                bodyHtml += ' | Interest: ' + offer.totalInterest + 'g';
                bodyHtml += ' | Total repay: <strong>' + offer.totalRepay + 'g</strong>';
                bodyHtml += '</div>';
                bodyHtml += '<div style="font-size:11px;color:#999;">';
                bodyHtml += 'Monthly payment: ' + offer.monthlyPayment + 'g';
                bodyHtml += ' | ' + offer.numPayments + ' payments over ' + offer.termDays + ' days';
                bodyHtml += ' | Free ' + (offer.guildName || 'guild') + ' membership';
                bodyHtml += '</div>';
            } else {
                bodyHtml += '<div style="font-size:12px;color:#666;">' + (offer.reason || 'No loan available') + '</div>';
            }

            bodyHtml += '</div>';
        }

        bodyHtml += '</div>';

        var footerHtml = '<button class="btn-action" onclick="UI.showBankruptcyDialogFromLoan()" style="margin-right:8px;">← Back</button>';

        openModal('🏛️ Guild Loans', bodyHtml, footerHtml);
    }

    function showBankruptcyDialogFromLoan() {
        // Re-show the bankruptcy dialog (recalculate choices fresh)
        var debtAmount = 0;
        if (typeof Player !== 'undefined' && Player.state) {
            debtAmount = Math.abs(Player.state.gold);
        }
        var choices = [];
        if (typeof Player !== 'undefined' && Player.getBankruptcyChoices) {
            choices = Player.getBankruptcyChoices();
        }
        showBankruptcyDialog(debtAmount, choices);
    }

    function handleGuildLoanAccept(guildId) {
        if (typeof Player === 'undefined' || !Player.acceptGuildLoan) return;

        var result = Player.acceptGuildLoan(guildId);
        if (result.success) {
            _bankruptcyLock = false;
            var closeBtn = document.getElementById('btnCloseModal');
            if (closeBtn) closeBtn.style.display = '';
            closeModal();
            // Resume game
            if (typeof Game !== 'undefined' && Game.setSpeed) {
                Game.setSpeed(1);
            }
        } else {
            // Show error and stay on dialog
            if (typeof UI !== 'undefined' && UI.toast) {
                UI.toast('❌ ' + (result.message || 'Loan failed.'), 'danger');
            }
        }
    }

    function handleBankruptcyChoice(choice) {
        if (typeof Player !== 'undefined' && Player.handleBankruptcyChoice) {
            Player.handleBankruptcyChoice(choice);
        }
        // guild_loan is handled by showGuildLoanDialog, don't close/resume here
        if (choice === 'guild_loan') return;
        _bankruptcyLock = false;
        var closeBtn = document.getElementById('btnCloseModal');
        if (closeBtn) closeBtn.style.display = '';
        closeModal();
        // Resume game
        if (typeof Game !== 'undefined' && Game.setSpeed) {
            Game.setSpeed(1);
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  SPY FAVOR DIALOG
    // ═══════════════════════════════════════════════════════════
    function showSpyFavorDialog(kingdomId) {
        if (typeof Player === 'undefined' || !Player.getSpyFavorChoices) return;
        var choices = Player.getSpyFavorChoices(kingdomId);
        if (!choices || choices.length === 0) return;

        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(0);

        var bodyHtml = '<div style="margin-bottom:12px;font-size:14px;color:#c4a35a;">' +
            '👑 The King is so impressed by your spy work that he offers you a personal favor. Choose wisely — this is a rare opportunity!' +
            '</div>';

        for (var i = 0; i < choices.length; i++) {
            var ch = choices[i];
            bodyHtml += '<div onclick="UI.handleSpyFavor(\'' + ch.id + '\')" style="' +
                'background:#1a1a2e;border:1px solid #444;border-radius:8px;padding:10px 14px;margin:6px 0;cursor:pointer;transition:border-color 0.2s,background 0.2s;' +
                '" onmouseenter="this.style.borderColor=\'#c4a35a\';this.style.background=\'#222244\'" onmouseleave="this.style.borderColor=\'#444\';this.style.background=\'#1a1a2e\'">' +
                '<div style="font-weight:bold;font-size:14px;color:#e0d5c0;">' + ch.label + '</div>' +
                '<div style="font-size:12px;color:#999;margin-top:4px;">' + ch.description + '</div>' +
                '<div style="font-size:11px;color:#c4a35a;margin-top:3px;">' + ch.detail + '</div>' +
                '</div>';
        }

        openModal('👑 Royal Favor', bodyHtml, '');
    }

    function handleSpyFavor(favorId) {
        if (typeof Player !== 'undefined' && Player.handleSpyFavor) {
            var result = Player.handleSpyFavor(favorId);
            if (result && result.message && typeof toast === 'function') {
                toast(result.success ? '✅ ' + result.message : '❌ ' + result.message, result.success ? 'success' : 'danger');
            }
        }
        closeModal();
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(1);
    }

    // ═══════════════════════════════════════════════════════════
    //  TOURNAMENT CONTINUE/FORFEIT DIALOG
    // ═══════════════════════════════════════════════════════════
    function showTournamentContinueDialog(result) {
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(0);

        var bodyHtml = '<div style="text-align:center;margin-bottom:12px;">' +
            '<div style="font-size:24px;margin-bottom:8px;">🏟️ Round ' + (result.nextRound - 1) + ' Victory!</div>' +
            '<div style="color:#c4a35a;font-size:16px;margin-bottom:12px;">' + result.message.split('\n')[0] + '</div>' +
            '</div>';

        bodyHtml += '<div style="background:#1a1a2e;border:1px solid #444;border-radius:8px;padding:12px;margin:8px 0;text-align:center;">' +
            '<div style="font-size:14px;color:#e0d5c0;">⚔️ Round ' + result.nextRound + '</div>' +
            '<div style="font-size:13px;color:#999;margin-top:4px;">Prize: <span style="color:#c4a35a;">' + result.nextPrize + 'g</span> | Win chance: <span style="color:' + (result.nextWinChance >= 50 ? '#4ade80' : result.nextWinChance >= 25 ? '#fbbf24' : '#f87171') + ';">' + result.nextWinChance + '%</span></div>' +
            '</div>';

        bodyHtml += '<div style="display:flex;gap:10px;margin-top:14px;">' +
            '<button onclick="UI.handleTournamentContinue()" style="flex:1;padding:10px;background:#2d5a2d;color:#fff;border:1px solid #4ade80;border-radius:6px;cursor:pointer;font-size:14px;">⚔️ Fight Next Round</button>' +
            '<button onclick="UI.handleTournamentForfeit()" style="flex:1;padding:10px;background:#5a2d2d;color:#fff;border:1px solid #f87171;border-radius:6px;cursor:pointer;font-size:14px;">🏳️ Withdraw (Keep Winnings)</button>' +
            '</div>';

        openModal('🏟️ Tournament', bodyHtml, '');
    }

    function handleTournamentContinue() {
        closeModal();
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(1);
        if (typeof Player !== 'undefined' && Player.continueTournament) {
            var result = Player.continueTournament();
            if (result && result.tournamentContinue) {
                setTimeout(function() { showTournamentContinueDialog(result); }, 300);
            }
        }
    }

    function handleTournamentForfeit() {
        closeModal();
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(1);
        if (typeof Player !== 'undefined' && Player.forfeitTournament) {
            Player.forfeitTournament();
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  CUSTOMS INSPECTOR CONTRABAND DIALOG
    // ═══════════════════════════════════════════════════════════
    function showCustomsChoiceDialog(itemName, resourceId, kingdomId) {
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(0);
        var bodyHtml = '<div style="text-align:center;margin-bottom:12px;">' +
            '<div style="font-size:20px;margin-bottom:8px;">🔍 Contraband Found!</div>' +
            '<div style="color:#c4a35a;font-size:14px;">You discovered <strong>' + itemName + '</strong> while inspecting cargo.</div>' +
            '</div>';
        bodyHtml += '<div style="display:flex;gap:10px;margin-top:14px;">' +
            '<div onclick="UI.handleCustomsChoice(\'turn_in\')" style="flex:1;padding:12px;background:#1a2e1a;border:1px solid #4ade80;border-radius:8px;cursor:pointer;text-align:center;">' +
            '<div style="font-size:16px;">⚖️ Turn In</div>' +
            '<div style="font-size:12px;color:#999;margin-top:4px;">+10g bounty, +2 kingdom rep</div>' +
            '</div>' +
            '<div onclick="UI.handleCustomsChoice(\'keep\')" style="flex:1;padding:12px;background:#2e1a1a;border:1px solid #f87171;border-radius:8px;cursor:pointer;text-align:center;">' +
            '<div style="font-size:16px;">🤫 Pocket It</div>' +
            '<div style="font-size:12px;color:#999;margin-top:4px;">Keep 1x ' + itemName + ', +5 notoriety</div>' +
            '</div>' +
            '</div>';
        openModal('🔍 Customs Inspection', bodyHtml, '');
    }

    function handleCustomsChoice(choice) {
        closeModal();
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(1);
        if (typeof Player !== 'undefined' && Player.handleCustomsChoice) {
            Player.handleCustomsChoice(choice);
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  AUTO-TRAVEL JOB STATUS (shown in work dialog)
    // ═══════════════════════════════════════════════════════════
    function getAutoTravelStatusHtml() {
        if (typeof Player === 'undefined' || !Player.getAutoTravelStatus) return '';
        var status = Player.getAutoTravelStatus();
        if (!status) return '';

        var html = '<div style="border:2px solid #c4a35a;padding:10px;margin-bottom:12px;border-radius:6px;background:rgba(196,163,90,0.08);">';
        html += '<h3 style="margin:0 0 6px 0;">🗺️ ' + status.name + ' — Active Mission</h3>';
        html += '<div class="detail-row"><span class="label">Status</span><span class="value">';
        if (status.status === 'traveling') html += '🚶 Traveling to ' + status.currentDestination;
        else if (status.status === 'working') html += '⚒️ Working at ' + status.currentDestination;
        else if (status.status === 'advancing') html += '📋 Preparing next leg...';
        html += '</span></div>';
        html += '<div class="detail-row"><span class="label">Progress</span><span class="value">' + status.completedLegs + ' / ' + status.totalLegs + ' stops</span></div>';
        html += '<div class="detail-row"><span class="label">Current Task</span><span class="value" style="font-size:0.75rem;">' + status.currentDescription + '</span></div>';
        html += '<div class="detail-row"><span class="label">Earned So Far</span><span class="value">🪙 ' + formatGold(status.totalPaid || 0) + 'g</span></div>';
        html += '<div class="detail-row"><span class="label">Days Elapsed</span><span class="value">' + status.daysElapsed + '</span></div>';

        // Show letters for messenger
        if (status.letters && status.letters.length > 0) {
            html += '<div style="margin-top:6px;font-size:0.75rem;color:#999;">';
            for (var i = 0; i < status.letters.length; i++) {
                var l = status.letters[i];
                html += (l.delivered ? '✅' : '📮') + ' ' + l.recipientName + ' in ' + l.townName + (l.delivered ? ' (delivered)' : '') + '<br>';
            }
            html += '</div>';
        }

        html += '<button class="btn-medieval" onclick="UI.quitAutoTravelJob()" style="margin-top:8px;font-size:0.8rem;padding:6px 16px;background:rgba(200,60,50,0.3);border-color:rgba(200,60,50,0.55);">🛑 Quit Mission</button>';
        html += '</div>';
        html += '<p class="text-dim">You cannot take other jobs while on an auto-travel mission. The mission progresses automatically.</p>';
        return html;
    }

    function quitAutoTravelJob() {
        if (typeof Player !== 'undefined' && Player.quitAutoTravelJob) {
            var result = Player.quitAutoTravelJob();
            if (result && result.message) {
                toast(result.message, result.success ? 'info' : 'warning');
            }
        }
        closeModal();
    }

    // ═══════════════════════════════════════════════════════════
    //  WIN / LOSE SCREEN
    // ═══════════════════════════════════════════════════════════

    function showWinScreen(message) {
        const endTitle = document.getElementById('endTitle');
        const endMessage = document.getElementById('endMessage');
        if (endTitle) { endTitle.textContent = '🏆 Victory!'; endTitle.style.color = '#c4a35a'; }
        if (endMessage) endMessage.textContent = message || 'You have built a legendary trade empire!';
        showEndStats();
        el.endScreen.classList.remove('hidden');
        el.endScreen.style.display = 'flex';
    }

    // ── REGENCY SCREEN ──

    function showRegencyScreen() {
        if (!Player.regencyMode || !Player.regencyData) return;
        const rd = Player.regencyData;
        const threshold = (typeof REGENCY_THRESHOLDS !== 'undefined') ?
            REGENCY_THRESHOLDS.find(t => rd.regencyScore >= t.min && rd.regencyScore <= t.max) : null;

        let updatesHtml = '';
        const recentUpdates = (rd.monthlyUpdates || []).slice(-6);
        for (const upd of recentUpdates) {
            updatesHtml += `<div style="font-size:0.75rem;padding:3px 0;border-bottom:1px solid rgba(255,255,255,0.05);">${upd.message}</div>`;
        }
        if (!updatesHtml) updatesHtml = '<div class="text-dim">No updates yet.</div>';

        const yearsToGo = Math.max(0, CONFIG.COMING_OF_AGE - rd.heirAge);
        const heirSexIcon = rd.heirSex === 'F' ? '♀' : '♂';

        const spouseStatus = rd.spouseAlive ? '💚 Alive' : '⚰️ Deceased';
        const thresholdLabel = rd.thresholdLabel || 'Unknown';

        let revealedTraitsHtml = '';
        if (rd.revealedAtDeath) {
            const rTraits = rd.revealedAtDeath.traits || {};
            const rQuirks = rd.revealedAtDeath.quirks || [];
            if (Object.keys(rTraits).length > 0 || rQuirks.length > 0) {
                revealedTraitsHtml += '<div style="font-size:0.75rem;margin-top:6px;">';
                for (const [t, v] of Object.entries(rTraits)) {
                    const label = t.charAt(0).toUpperCase() + t.slice(1);
                    revealedTraitsHtml += `<span style="margin-right:8px;">${label}: ${typeof v === 'number' ? v : v}</span>`;
                }
                if (rQuirks.length > 0 && typeof SPOUSE_QUIRKS !== 'undefined') {
                    for (const qId of rQuirks) {
                        const qDef = SPOUSE_QUIRKS.find(q => q.id === qId);
                        if (qDef) revealedTraitsHtml += `<span style="margin-right:8px;">${qDef.icon} ${qDef.name}</span>`;
                    }
                }
                revealedTraitsHtml += '</div>';
            }
        }

        const html = `<div style="text-align:center;padding:12px;">
            <div style="font-size:1.4rem;font-weight:bold;margin-bottom:12px;">⚰️ REGENCY PERIOD</div>
            <div class="text-dim" style="margin-bottom:12px;">Your spouse manages the estate while your heir grows up.</div>

            <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;text-align:left;">
                <div style="border:1px solid rgba(196,163,90,0.2);border-radius:6px;padding:10px;">
                    <div style="font-weight:bold;margin-bottom:4px;">👩 Regent: ${rd.spouseName}</div>
                    <div style="font-size:0.8rem;">Status: ${spouseStatus}</div>
                    <div style="font-size:0.8rem;">Outcome: <span style="color:var(--gold);">${thresholdLabel}</span></div>
                    <div style="font-size:0.8rem;">Score: ${rd.regencyScore}/100</div>
                    ${revealedTraitsHtml}
                </div>
                <div style="border:1px solid rgba(196,163,90,0.2);border-radius:6px;padding:10px;">
                    <div style="font-weight:bold;margin-bottom:4px;">${heirSexIcon} Heir: ${rd.heirName}</div>
                    <div style="font-size:0.8rem;">Age: ${rd.heirAge} → ${CONFIG.COMING_OF_AGE} in ~${yearsToGo} years</div>
                    <div style="font-size:0.8rem;margin-top:8px;">💰 Estate: ${formatGold(rd.estateGold || 0)}</div>
                    <div style="font-size:0.8rem;">🏠 Buildings: ${rd.buildingsMaintained} maintained</div>
                </div>
            </div>

            <div style="border:1px solid rgba(196,163,90,0.1);border-radius:6px;padding:8px;margin-top:12px;text-align:left;">
                <div style="font-weight:bold;margin-bottom:4px;font-size:0.85rem;">📜 Recent Updates</div>
                ${updatesHtml}
            </div>

            <div style="margin-top:12px;font-size:0.8rem;color:#888;">
                Time continues to advance. Use speed controls to pass the years.
            </div>
        </div>`;

        openModal('⚰️ Regency', html);
    }

    function updateRegencyOverlay() {
        if (!Player.regencyMode || !Player.regencyData) return;
        // Show a persistent regency bar in the HUD
        let overlay = document.getElementById('regencyOverlay');
        if (!overlay) {
            overlay = document.createElement('div');
            overlay.id = 'regencyOverlay';
            overlay.style.cssText = 'position:fixed;top:40px;left:50%;transform:translateX(-50%);background:rgba(30,25,20,0.95);border:1px solid var(--gold);border-radius:8px;padding:8px 16px;z-index:1000;cursor:pointer;font-size:0.8rem;text-align:center;';
            overlay.onclick = function() { showRegencyScreen(); };
            document.body.appendChild(overlay);
        }
        const rd = Player.regencyData;
        overlay.innerHTML = `⚰️ <b>Regency</b> | ${escapeHtml(rd.spouseName)} raises ${escapeHtml(rd.heirName)} (Age ${rd.heirAge}/${CONFIG.COMING_OF_AGE}) | 💰 ${formatGold(rd.estateGold || 0)} | <span style="color:var(--gold);">${escapeHtml(rd.thresholdLabel)}</span>`;
        overlay.style.display = '';
    }

    function hideRegencyOverlay() {
        const overlay = document.getElementById('regencyOverlay');
        if (overlay) overlay.style.display = 'none';
    }

    function showLoseScreen(message) {
        // Pause game immediately
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(0);

        var deathCause = '';
        if (typeof Player !== 'undefined' && Player.state) {
            deathCause = Player.state.deathCause || '';
        }

        var endTitle = document.getElementById('endTitle');
        var endMessage = document.getElementById('endMessage');
        if (endTitle) { endTitle.textContent = '💀 Defeat'; endTitle.style.color = '#c44e52'; }

        // Build cause of death message
        var loseMsg = '';
        if (message === 'No Heir' || message === 'Assassinated') {
            if (deathCause) {
                loseMsg = 'Cause of death: ' + deathCause + '.';
            } else if (message === 'Assassinated') {
                loseMsg = 'You were assassinated. Your enemies finally caught up with you.';
            } else {
                loseMsg = 'Your legacy dies with you. Without an heir, your name fades from history.';
            }
        } else if (message) {
            loseMsg = message;
        } else {
            loseMsg = 'Your merchant ventures have come to a bitter end.';
        }
        if (endMessage) endMessage.innerHTML = '<span style="font-size:1.1rem;color:#e8c080;">' + loseMsg + '</span>';

        showEndStats();
        el.endScreen.classList.remove('hidden');
        el.endScreen.style.display = 'flex';
    }

    function showEndStats() {
        var stats = (typeof Player !== 'undefined' && Player.stats) ? Player.stats : {};
        var endStats = document.getElementById('endStats');
        if (!endStats) return;

        var daysPlayed = stats.daysPlayed || (Engine.getDay ? Engine.getDay() : 0);
        var years = Math.floor(daysPlayed / (CONFIG.DAYS_PER_SEASON || 90));
        var days = daysPlayed % (CONFIG.DAYS_PER_SEASON || 90);
        var timeStr = years > 0 ? years + ' year' + (years > 1 ? 's' : '') + ', ' + days + ' day' + (days !== 1 ? 's' : '') : daysPlayed + ' day' + (daysPlayed !== 1 ? 's' : '');

        // Get highest rank achieved
        var highestRank = 0;
        var highestRankName = 'Peasant';
        if (typeof Player !== 'undefined' && Player.state) {
            var sr = Player.state.socialRank || {};
            for (var kid in sr) {
                if (sr[kid] > highestRank) highestRank = sr[kid];
            }
            if (typeof CONFIG !== 'undefined' && CONFIG.SOCIAL_RANKS && CONFIG.SOCIAL_RANKS[highestRank]) {
                highestRankName = CONFIG.SOCIAL_RANKS[highestRank].name;
            }
        }

        // Achievement count
        var achCount = 0;
        var totalAch = 0;
        if (typeof Player !== 'undefined') {
            var pAch = Player.achievements || {};
            for (var ak in pAch) { if (pAch[ak] && pAch[ak].unlocked) achCount++; }
            if (typeof ACHIEVEMENTS !== 'undefined') {
                for (var _ta in ACHIEVEMENTS) totalAch++;
            }
        }

        endStats.innerHTML =
            '<span class="end-stat-label">Time Lived</span><span class="end-stat-value">' + timeStr + '</span>' +
            '<span class="end-stat-label">Gold Earned</span><span class="end-stat-value">' + formatGold(stats.totalGoldEarned || 0) + '</span>' +
            '<span class="end-stat-label">Trades Made</span><span class="end-stat-value">' + (stats.tradesCompleted || 0) + '</span>' +
            '<span class="end-stat-label">Buildings Owned</span><span class="end-stat-value">' + ((typeof Player !== 'undefined' && Player.buildings) ? Player.buildings.length : 0) + '</span>' +
            '<span class="end-stat-label">Highest Rank</span><span class="end-stat-value">' + highestRankName + '</span>' +
            '<span class="end-stat-label">Achievements</span><span class="end-stat-value">' + achCount + '/' + totalAch + '</span>' +
            '<div style="margin-top:14px;display:flex;flex-wrap:wrap;gap:8px;justify-content:center;">' +
                '<button class="btn-medieval" onclick="UI.openJournal()" style="font-size:0.82rem;padding:5px 14px;">📖 Journal</button>' +
                '<button class="btn-medieval" onclick="UI.openAchievementsDialog()" style="font-size:0.82rem;padding:5px 14px;">🏆 Achievements</button>' +
                '<button class="btn-medieval" onclick="UI.showBusinessLegacy()" style="font-size:0.82rem;padding:5px 14px;background:linear-gradient(135deg,rgba(180,140,60,0.4),rgba(120,90,30,0.5));border:1px solid rgba(200,170,80,0.5);">📊 Business Legacy</button>' +
            '</div>';

        var btnEndOk = document.getElementById('btnEndOk');
        if (btnEndOk) btnEndOk.onclick = function () {
            el.endScreen.classList.add('hidden');
            el.endScreen.style.display = 'none';
            hideGameUI();
            el.titleScreen.classList.remove('hidden');
            el.titleScreen.style.display = 'flex';
        };
    }

    // Business Legacy — comprehensive summary of the player's entire career
    function showBusinessLegacy() {
        if (typeof Player === 'undefined') return;
        var p = Player.state || {};
        var stats = Player.stats || {};
        var achStats = p.achievementStats || {};
        var day = Engine.getDay ? Engine.getDay() : 0;
        var years = Math.floor(day / (CONFIG.DAYS_PER_SEASON || 90));

        // Buildings summary
        var buildings = Player.buildings || [];
        var buildingTypes = {};
        for (var bi = 0; bi < buildings.length; bi++) {
            var bt = buildings[bi].type || 'unknown';
            buildingTypes[bt] = (buildingTypes[bt] || 0) + 1;
        }
        var buildHtml = '';
        if (buildings.length === 0) {
            buildHtml = '<div style="color:#888;">No buildings owned.</div>';
        } else {
            buildHtml = '<div style="display:grid;grid-template-columns:1fr auto;gap:2px 12px;max-width:340px;margin:0 auto;">';
            for (var btk in buildingTypes) {
                var bLabel = btk.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
                buildHtml += '<span style="text-align:left;">' + bLabel + '</span><span style="color:#f0c040;text-align:right;">' + buildingTypes[btk] + '</span>';
            }
            buildHtml += '</div>';
        }

        // Production summary — goods produced by buildings
        var productionHtml = '';
        var totalProduced = {};
        for (var pi = 0; pi < buildings.length; pi++) {
            var bld = buildings[pi];
            if (bld.totalProduced) {
                for (var pk in bld.totalProduced) {
                    totalProduced[pk] = (totalProduced[pk] || 0) + bld.totalProduced[pk];
                }
            }
        }
        var prodEntries = [];
        for (var prk in totalProduced) { if (totalProduced[prk] > 0) prodEntries.push({ good: prk, qty: totalProduced[prk] }); }
        prodEntries.sort(function(a, b) { return b.qty - a.qty; });
        if (prodEntries.length === 0) {
            productionHtml = '<div style="color:#888;">No production recorded.</div>';
        } else {
            productionHtml = '<div style="display:grid;grid-template-columns:1fr auto;gap:2px 12px;max-width:340px;margin:0 auto;">';
            for (var pe = 0; pe < Math.min(prodEntries.length, 15); pe++) {
                var gLabel = prodEntries[pe].good.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
                productionHtml += '<span style="text-align:left;">' + gLabel + '</span><span style="color:#90d090;text-align:right;">' + prodEntries[pe].qty + '</span>';
            }
            productionHtml += '</div>';
        }

        // Caravans summary
        var caravans = p.caravans || [];
        var caravansCompleted = stats.caravansCompleted || 0;

        // Top traded goods (sells)
        var sells = achStats.totalSells || {};
        var sellEntries = [];
        for (var sk in sells) { if (sells[sk] > 0) sellEntries.push({ good: sk, qty: sells[sk] }); }
        sellEntries.sort(function(a, b) { return b.qty - a.qty; });
        var top10Trades = '';
        if (sellEntries.length === 0) {
            top10Trades = '<div style="color:#888;">No goods sold.</div>';
        } else {
            top10Trades = '<div style="display:grid;grid-template-columns:auto 1fr auto;gap:2px 8px;max-width:340px;margin:0 auto;">';
            for (var ti = 0; ti < Math.min(sellEntries.length, 10); ti++) {
                var tLabel = sellEntries[ti].good.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
                top10Trades += '<span style="color:#888;">#' + (ti + 1) + '</span><span style="text-align:left;">' + tLabel + '</span><span style="color:#f0c040;text-align:right;">' + sellEntries[ti].qty + '</span>';
            }
            top10Trades += '</div>';
        }

        // Social status per kingdom
        var rankHtml = '';
        var sr = p.socialRank || {};
        var kingdoms = Engine.getKingdoms ? Engine.getKingdoms() : [];
        for (var ki = 0; ki < kingdoms.length; ki++) {
            var kd = kingdoms[ki];
            var rank = sr[kd.id] || 0;
            var rankName = (typeof CONFIG !== 'undefined' && CONFIG.SOCIAL_RANKS && CONFIG.SOCIAL_RANKS[rank]) ? CONFIG.SOCIAL_RANKS[rank].name : 'Peasant';
            var rep = (p.reputation && p.reputation[kd.id]) || 0;
            rankHtml += '<div style="display:flex;justify-content:space-between;gap:8px;"><span>' + kd.name + '</span><span style="color:#e8c080;">' + rankName + ' (Rep: ' + Math.round(rep) + ')</span></div>';
        }
        if (!rankHtml) rankHtml = '<div style="color:#888;">No kingdoms.</div>';

        // Gold summary
        var goldEarned = stats.totalGoldEarned || 0;
        var goldSpent = stats.totalGoldSpent || 0;
        var finalGold = Player.gold || 0;

        // Generation
        var generation = achStats.generation || 1;

        var body =
            '<div style="max-height:65vh;overflow-y:auto;padding:4px 8px;text-align:center;font-size:0.88rem;color:#d4c4a0;">' +
            '<h3 style="color:#f0c040;margin:4px 0 10px;">📊 The Legacy of ' + (p.fullName || 'Unknown') + '</h3>' +
            '<div style="color:#aaa;font-size:0.8rem;margin-bottom:10px;">Generation ' + generation + ' · ' + years + ' year' + (years !== 1 ? 's' : '') + ' in business</div>' +

            '<div style="background:rgba(60,50,30,0.4);border:1px solid rgba(180,150,80,0.3);border-radius:6px;padding:8px;margin-bottom:10px;">' +
            '<div style="color:#f0c040;font-weight:bold;margin-bottom:4px;">💰 Financial Summary</div>' +
            '<div style="display:grid;grid-template-columns:1fr auto;gap:2px 12px;max-width:300px;margin:0 auto;">' +
            '<span>Total Gold Earned</span><span style="color:#90d090;">' + formatGold(goldEarned) + '</span>' +
            '<span>Total Gold Spent</span><span style="color:#d09090;">' + formatGold(goldSpent) + '</span>' +
            '<span>Net Profit</span><span style="color:' + (goldEarned - goldSpent >= 0 ? '#90d090' : '#d09090') + ';">' + formatGold(goldEarned - goldSpent) + '</span>' +
            '<span>Final Gold</span><span style="color:#f0c040;">' + formatGold(finalGold) + '</span>' +
            '<span>Trades Completed</span><span style="color:#c0c0c0;">' + (stats.tradesCompleted || 0) + '</span>' +
            '</div></div>' +

            '<div style="background:rgba(60,50,30,0.4);border:1px solid rgba(180,150,80,0.3);border-radius:6px;padding:8px;margin-bottom:10px;">' +
            '<div style="color:#f0c040;font-weight:bold;margin-bottom:4px;">🏗️ Buildings (' + buildings.length + ')</div>' +
            buildHtml + '</div>' +

            '<div style="background:rgba(60,50,30,0.4);border:1px solid rgba(180,150,80,0.3);border-radius:6px;padding:8px;margin-bottom:10px;">' +
            '<div style="color:#f0c040;font-weight:bold;margin-bottom:4px;">⚒️ Total Production</div>' +
            productionHtml + '</div>' +

            '<div style="background:rgba(60,50,30,0.4);border:1px solid rgba(180,150,80,0.3);border-radius:6px;padding:8px;margin-bottom:10px;">' +
            '<div style="color:#f0c040;font-weight:bold;margin-bottom:4px;">🐪 Caravans</div>' +
            '<div>Active: ' + caravans.length + ' · Completed: ' + caravansCompleted + '</div>' +
            '</div>' +

            '<div style="background:rgba(60,50,30,0.4);border:1px solid rgba(180,150,80,0.3);border-radius:6px;padding:8px;margin-bottom:10px;">' +
            '<div style="color:#f0c040;font-weight:bold;margin-bottom:4px;">📈 Top Goods Sold</div>' +
            top10Trades + '</div>' +

            '<div style="background:rgba(60,50,30,0.4);border:1px solid rgba(180,150,80,0.3);border-radius:6px;padding:8px;margin-bottom:10px;">' +
            '<div style="color:#f0c040;font-weight:bold;margin-bottom:4px;">👑 Status Across Kingdoms</div>' +
            rankHtml + '</div>' +

            '</div>';

        var footer = '<button class="btn-medieval" data-action="closeModal">Close</button>';
        openModal('📊 Business Legacy', body, footer);
    }

    // ═══════════════════════════════════════════════════════════
    //  ACTION HELPERS (called from onclick attributes)
    // ═══════════════════════════════════════════════════════════

    // ---- Travel Options Dialog ----

    function calculateRouteDist(route) {
        var totalDist = 0;
        if (!route) return 0;
        for (var i = 0; i < route.length; i++) {
            var seg = route[i];
            var a = Engine.findTown(seg.fromTownId);
            var b = Engine.findTown(seg.toTownId);
            if (a && b) {
                var segDist = Math.hypot(a.x - b.x, a.y - b.y);
                if (seg.type === 'offroad') {
                    segDist /= (CONFIG.OFFROAD_SPEED_MULTIPLIER || 0.25);
                } else if (seg.type === 'sea') {
                    segDist /= (CONFIG.SEA_SPEED_MULTIPLIER || 1.5);
                } else {
                    segDist /= CONFIG.CARAVAN_ROAD_MULTIPLIER[seg.quality || 1] || 1;
                }
                totalDist += segDist;
            }
        }
        return totalDist;
    }

    function getTransportServices(fromTown, toTown, type) {
        var services = [];
        if (!fromTown || !toTown) return services;

        var kingdom = null;
        try { kingdom = Engine.findKingdom(fromTown.kingdomId); } catch (e) { /* ignore */ }

        var baseDist = Math.hypot((toTown.x || 0) - (fromTown.x || 0), (toTown.y || 0) - (fromTown.y || 0));
        var baseDays = Math.ceil(baseDist / (CONFIG.CARAVAN_BASE_SPEED * 1.5));
        if (baseDays < 1) baseDays = 1;

        // Kingdom Transport (if law active)
        if (kingdom && kingdom.laws && kingdom.laws.kingdomTransport) {
            var rate = kingdom.laws.transportRate || (CONFIG.KINGDOM_TRANSPORT ? CONFIG.KINGDOM_TRANSPORT.defaultRate : 15);
            var kDays = Math.ceil(baseDays * 0.6);
            services.push({
                icon: '👑',
                name: 'Kingdom Transport (' + rate + 'g)',
                desc: 'Official ' + (kingdom.name || 'Kingdom') + ' transport service.' + (type === 'sea' ? ' Royal vessel.' : ' Horse-drawn carriage.'),
                price: rate,
                days: Math.max(1, kDays),
                type: 'kingdom',
                kingdomId: kingdom.id
            });
        }

        // NPC Transport (based on town tier)
        var tier = fromTown.tier || 'town';
        if (tier !== 'village') {
            // Standard horse carriage (land only)
            if (type === 'land') {
                var carriagePrice = Math.round(10 + baseDays * 5);
                services.push({
                    icon: '🏇',
                    name: 'Horse Carriage (' + carriagePrice + 'g)',
                    desc: 'Hired transport by horse. Comfortable and faster than walking.',
                    price: carriagePrice,
                    days: Math.max(1, Math.ceil(baseDays * 0.55)),
                    type: 'npc_carriage'
                });
            }

            // Luxury wagon (cities and capitals, land only)
            if (type === 'land' && (tier === 'city' || tier === 'capital')) {
                var luxPrice = Math.round(25 + baseDays * 12);
                services.push({
                    icon: '🎪',
                    name: 'Luxury Wagon (' + luxPrice + 'g)',
                    desc: 'Padded wagon with canopy. Very comfortable, restores energy during travel.',
                    price: luxPrice,
                    days: Math.max(1, Math.ceil(baseDays * 0.5)),
                    type: 'npc_luxury',
                    restBonus: true
                });
            }

            // Merchant vessel (sea, at ports)
            if (type === 'sea' && fromTown.isPort) {
                var vesselPrice = Math.round(30 + baseDays * 8);
                services.push({
                    icon: '⛴️',
                    name: 'Merchant Vessel (' + vesselPrice + 'g)',
                    desc: 'Book passage on a merchant ship. Safer than solo sailing.',
                    price: vesselPrice,
                    days: Math.max(1, Math.ceil(baseDays * 0.7)),
                    type: 'npc_vessel'
                });
            }

            // Luxury cabin (sea, cities and capitals with ports)
            if (type === 'sea' && fromTown.isPort && (tier === 'city' || tier === 'capital')) {
                var luxSeaPrice = Math.round(50 + baseDays * 18);
                services.push({
                    icon: '🛳️',
                    name: 'Luxury Cabin (' + luxSeaPrice + 'g)',
                    desc: 'Private cabin on a galleon. Restores energy during the voyage.',
                    price: luxSeaPrice,
                    days: Math.max(1, Math.ceil(baseDays * 0.6)),
                    type: 'npc_luxury_sea',
                    restBonus: true
                });
            }
        }

        return services;
    }

    // Store state for travel options dialog
    var _travelOptions = [];
    var _travelDestTownId = null;
    var _travelRouteDanger = {};
    var _travelBringFamily = false;

    /** Closed borders dialog — offers military service or smuggling */
    function _showClosedBordersDialog(destTown, destKingdom, townId) {
        var hasSmugglersRun = Player.hasSkill && Player.hasSkill('smugglers_run');

        // Check if kingdom is at war (required for military enlistment)
        var atWar = false;
        try {
            var wars = Engine.getActiveWars ? Engine.getActiveWars() : {};
            for (var wId in wars) {
                var w = wars[wId];
                if (w.kingdomA === destKingdom.id || w.kingdomB === destKingdom.id) { atWar = true; break; }
            }
        } catch (e) { /* ignore */ }

        var html = '<div style="text-align:center;padding:10px;">';
        html += '<div style="font-size:2em;margin-bottom:8px;">🚫</div>';
        html += '<h3 style="color:#e74c3c;margin:0 0 8px;">Borders Closed</h3>';
        html += '<p style="margin:0 0 12px;color:#ddd;">The Kingdom of <strong>' + destKingdom.name + '</strong> has closed its borders to foreigners. You cannot enter ' + destTown.name + '.</p>';
        html += '<hr style="border-color:#555;margin:12px 0;">';

        // Option 1: Military Service (only if at war)
        if (atWar) {
            html += '<div style="background:#2a3a2a;border:1px solid #4a6a4a;border-radius:6px;padding:10px;margin-bottom:10px;text-align:left;">';
            html += '<div style="font-size:1.1em;font-weight:bold;color:#7cb342;">⚔️ Serve in Their Military</div>';
            html += '<p style="font-size:0.85em;color:#aaa;margin:4px 0 8px;">' + destKingdom.name + ' is at war and accepting foreign recruits. Serve until you reach the rank of <strong style="color:#f0c040;">Knight</strong> to earn citizenship. You cannot leave the military before then.</p>';
            html += '<button class="btn-medieval" style="width:100%;" onclick="UI._enlistForCitizenship(\'' + destKingdom.id + '\',\'' + townId + '\')">⚔️ Enlist for Citizenship</button>';
            html += '</div>';
        } else {
            html += '<div style="background:#3a3a2a;border:1px solid #6a6a4a;border-radius:6px;padding:10px;margin-bottom:10px;text-align:left;opacity:0.6;">';
            html += '<div style="font-size:1.1em;font-weight:bold;color:#888;">⚔️ Military Service (Unavailable)</div>';
            html += '<p style="font-size:0.85em;color:#777;margin:4px 0 0;">' + destKingdom.name + ' is not at war. They are not accepting foreign recruits. Wait for a war to break out.</p>';
            html += '</div>';
        }

        // Option 2: Smuggle across (requires Smuggler's Run skill)
        if (hasSmugglersRun) {
            html += '<div style="background:#3a2a2a;border:1px solid #6a4a4a;border-radius:6px;padding:10px;margin-bottom:10px;text-align:left;">';
            html += '<div style="font-size:1.1em;font-weight:bold;color:#e57373;">🏃 Sneak Across the Border</div>';
            html += '<p style="font-size:0.85em;color:#aaa;margin:4px 0 8px;">Use your <strong>Smuggler\'s Run</strong> skill to slip past border guards. If caught: <strong style="color:#e74c3c;">20 days jail + 25% gold fine</strong>.</p>';
            html += '<button class="btn-medieval" style="width:100%;background:#5a2a2a;" onclick="UI._smuggleBorder(\'' + townId + '\')">🏃 Attempt Border Crossing</button>';
            html += '</div>';
        } else {
            html += '<div style="background:#3a2a2a;border:1px solid #6a4a4a;border-radius:6px;padding:10px;margin-bottom:10px;text-align:left;opacity:0.6;">';
            html += '<div style="font-size:1.1em;font-weight:bold;color:#888;">🏃 Sneak Across (Unavailable)</div>';
            html += '<p style="font-size:0.85em;color:#777;margin:4px 0 0;">Requires the <strong>Smuggler\'s Run</strong> skill to attempt illegal border crossing.</p>';
            html += '</div>';
        }

        // Option 3: Petition from here (if at border town of same kingdom neighbor)
        html += '<div style="background:#2a2a3a;border:1px solid #4a4a6a;border-radius:6px;padding:10px;margin-bottom:10px;text-align:left;">';
        html += '<div style="font-size:1.1em;font-weight:bold;color:#64b5f6;">📜 Other Options</div>';
        html += '<p style="font-size:0.85em;color:#aaa;margin:4px 0 0;">Build reputation through trade with their merchants at other towns. Earn citizenship through military service during wartime. Or learn the Smuggler\'s Run skill from the Underworld skill tree.</p>';
        html += '</div>';

        html += '<button class="btn-medieval" style="width:100%;margin-top:8px;" data-action="closeModal">← Go Back</button>';
        html += '</div>';

        openModal('🚫 Closed Borders — ' + destKingdom.name, html);
    }

    /** Enlist in a foreign kingdom's military for citizenship */
    function _enlistForCitizenship(kingdomId, townId) {
        closeModal();
        var result = Player.enlistAsSoldier(kingdomId);
        if (result && result.success) {
            // Set mandatory service flag — cannot quit until Knight
            if (Player.state) {
                Player.state.militaryMandatory = true;
                Player.state.militaryBorderService = true;
            }
            toast('⚔️ Enlisted in ' + (Engine.findKingdom(kingdomId) || {}).name + '\'s military! Serve until Knight rank to earn citizenship.', 'success', 'military');
        } else {
            toast((result && result.message) || 'Cannot enlist.', 'danger');
        }
    }

    /** Attempt to smuggle across a closed border */
    function _smuggleBorder(townId) {
        closeModal();
        var result = Player.travelTo(townId);
        if (result && result.success) {
            toast('🏃 Slipped across the border undetected!', 'success');
        } else {
            toast((result && result.message) || 'Border crossing failed.', 'danger');
        }
    }

    // ── Forced Requisition Dialog ──
    function showRequisitionDialog(kingdom, targetRes, resName, seizeQty, seizeValue) {
        // Corruption Expert halves bribe cost
        var bribeMult = (Player.hasSkill && Player.hasSkill('corruption_expert')) ? 0.2 : 0.4;
        var bribeFloor = (Player.hasSkill && Player.hasSkill('corruption_expert')) ? 10 : 20;
        var bribeCost = Math.max(bribeFloor, Math.floor(seizeValue * bribeMult));
        var html = '<div style="text-align:center;margin-bottom:12px;">';
        html += '<div style="font-size:1.2rem;margin-bottom:8px;">⚠️ Guards Demand Your Goods!</div>';
        html += '<div style="font-size:0.8rem;color:#ccc;margin-bottom:12px;">Under <strong>Forced Requisition</strong> law in ' + kingdom.name + ', guards are seizing merchant goods for the crown.</div>';
        html += '<div style="background:rgba(180,60,60,0.2);padding:8px;border-radius:6px;margin-bottom:12px;">';
        html += '<strong>Demand:</strong> ' + seizeQty + 'x ' + resName + ' (worth ~' + seizeValue + 'g)';
        html += '</div>';
        html += '</div>';

        // Options
        html += '<div style="display:flex;flex-direction:column;gap:8px;">';
        // Comply
        html += '<button class="btn-medieval" onclick="Player.executeRequisition(\'' + targetRes + '\',' + seizeQty + '); UI.closeModal(); UI.toast(\'⚠️ Guards seized ' + seizeQty + ' ' + resName + '.\', \'danger\');" style="padding:8px;">';
        html += '😔 Comply (' + seizeQty + ' ' + resName + ' seized)</button>';
        // Bribe
        var bribeLabel = (Player.hasSkill && Player.hasSkill('corruption_expert')) ? '💰 Bribe the Guards (' + bribeCost + 'g — Corruption Expert)' : '💰 Bribe the Guards (' + bribeCost + 'g)';
        html += '<button class="btn-medieval" onclick="var r = Player.bribeRequisitionGuard(' + bribeCost + '); UI.closeModal(); if(!r.success){ Player.executeRequisition(\'' + targetRes + '\',' + seizeQty + '); }" style="padding:8px;">';
        html += bribeLabel + '</button>';
        // Resist (if player has combat skills)
        if (Player.hasSkill && (Player.hasSkill('combat_trained') || Player.hasSkill('battle_hardened'))) {
            html += '<button class="btn-medieval" onclick="UI._resistRequisition(\'' + targetRes + '\',' + seizeQty + ',\'' + kingdom.id + '\');" style="padding:8px;border-color:#c44;">';
            html += '⚔️ Resist (Combat — risky!)</button>';
        }
        // Fighting Retreat (if player has the skill)
        if (Player.hasSkill && Player.hasSkill('fighting_retreat')) {
            var combatLvl = (Player.getCombatLevel ? Player.getCombatLevel() : 0);
            var fleeChance = Math.min(85, Math.round(combatLvl));
            html += '<button class="btn-medieval" onclick="UI._fightingRetreat(\'' + targetRes + '\',' + seizeQty + ',\'' + kingdom.id + '\');" style="padding:8px;border-color:#c90;">';
            html += '🏃 Fighting Retreat (~' + fleeChance + '% — hit and run)</button>';
        }
        html += '</div>';

        openModal('⚠️ Forced Requisition', html);
    }

    function _resistRequisition(targetRes, seizeQty, kingdomId) {
        closeModal();
        var rng = Engine.getRng ? Engine.getRng() : null;
        var combatSkill = (Player.hasSkill && Player.hasSkill('battle_hardened')) ? 0.6 : 0.35;
        if (rng && rng.chance(combatSkill)) {
            toast('⚔️ You fought off the guards! But your notoriety increased.', 'success');
            if (Player.state) Player.state.notoriety = Math.min(100, (Player.state.notoriety || 0) + 25);
            var kingdom = Engine.findKingdom(kingdomId);
            if (kingdom && Player.state.reputation) {
                Player.state.reputation[kingdomId] = Math.max(0, (Player.state.reputation[kingdomId] || 50) - 20);
            }
            Engine.logEvent(Player.state.fullName + ' resisted forced requisition by force!');
        } else {
            toast('⚔️ You tried to resist but were overpowered! Goods seized + fined.', 'danger');
            Player.executeRequisition(targetRes, seizeQty);
            if (Player.state) Player.state.notoriety = Math.min(100, (Player.state.notoriety || 0) + 30);
            var fineAmt = Math.floor(seizeQty * 10);
            Player.state.gold = Math.max(0, (Player.state.gold || 0) - fineAmt);
            var kingdom2 = Engine.findKingdom(kingdomId);
            if (kingdom2 && Player.state.reputation) {
                Player.state.reputation[kingdomId] = Math.max(0, (Player.state.reputation[kingdomId] || 50) - 25);
            }
            Engine.logEvent(Player.state.fullName + ' tried to resist requisition but was captured! Fined ' + fineAmt + 'g.');
        }
    }

    function _fightingRetreat(targetRes, seizeQty, kingdomId) {
        closeModal();
        var rng = Engine.getRng ? Engine.getRng() : null;
        var combatLevel = (Player.getCombatLevel ? Player.getCombatLevel() : 0);
        var fleeChance = Math.min(0.85, combatLevel / 100);
        if (rng && rng.chance(fleeChance)) {
            toast('🏃 You fought the guards and escaped with your goods!', 'success');
            if (Player.state) Player.state.notoriety = Math.min(100, (Player.state.notoriety || 0) + 10);
            var kingdom = Engine.findKingdom(kingdomId);
            if (kingdom && Player.state.reputation) {
                Player.state.reputation[kingdomId] = Math.max(0, (Player.state.reputation[kingdomId] || 50) - 10);
            }
            Engine.logEvent(Player.state.fullName + ' fought off requisition guards and fled!');
        } else {
            toast('🏃 You tried to flee but the guards caught you! Goods seized.', 'danger');
            Player.executeRequisition(targetRes, seizeQty);
            if (Player.state) Player.state.notoriety = Math.min(100, (Player.state.notoriety || 0) + 15);
            Engine.logEvent(Player.state.fullName + ' tried to flee requisition but was caught.');
        }
    }

    // ── Exclusive Citizenship Dialog ──
    function showExclusiveCitizenshipDialog(enforcingKingdom, citizenKingdoms) {
        var html = '<div style="text-align:center;margin-bottom:12px;">';
        html += '<div style="font-size:1.2rem;margin-bottom:8px;">🛡️ Exclusive Citizenship Enforced!</div>';
        html += '<div style="font-size:0.8rem;color:#ccc;margin-bottom:12px;"><strong>' + enforcingKingdom.name + '</strong> has enacted the <em>Exclusive Citizenship</em> law. You cannot hold citizenship in multiple kingdoms.</div>';
        html += '<div style="font-size:0.78rem;color:#e8c170;margin-bottom:12px;">You must choose which kingdom to remain a citizen of. You will lose your rank and reputation (-15) in all others.</div>';
        html += '</div>';

        html += '<div style="display:flex;flex-direction:column;gap:8px;">';
        for (var i = 0; i < citizenKingdoms.length; i++) {
            var kId = citizenKingdoms[i];
            var k = Engine.findKingdom(kId);
            if (!k) continue;
            var rankIdx = (Player.state.socialRank[kId] || 0);
            var rankName = CONFIG.SOCIAL_RANKS[rankIdx] ? CONFIG.SOCIAL_RANKS[rankIdx].name : 'Citizen';
            var rep = Math.floor(Player.state.reputation[kId] || 0);
            var isPrimary = kId === Player.state.citizenshipKingdomId;
            html += '<button class="btn-medieval" onclick="UI._chooseExclusiveCitizenship(\'' + kId + '\',' + JSON.stringify(citizenKingdoms) + ');" style="padding:8px;' + (isPrimary ? 'border-color:#d4af37;' : '') + '">';
            html += '👑 Keep <strong>' + k.name + '</strong> — ' + rankName + ' (Rep: ' + rep + ')';
            if (isPrimary) html += ' ★';
            html += '</button>';
        }
        html += '</div>';

        openModal('🛡️ Choose Your Allegiance', html);
    }

    function _chooseExclusiveCitizenship(keepKingdomId, allKingdoms) {
        closeModal();
        var kept = Engine.findKingdom(keepKingdomId);
        for (var i = 0; i < allKingdoms.length; i++) {
            if (allKingdoms[i] !== keepKingdomId) {
                Player.forceRenounceCitizenship(allKingdoms[i]);
            }
        }
        Player.state.citizenshipKingdomId = keepKingdomId;
        toast('🛡️ You pledged exclusive allegiance to ' + (kept ? kept.name : 'your kingdom') + '.', 'success');
    }

    // ========================================================
    // HORSE PERMIT VIOLATION DIALOG
    // ========================================================
    function showHorsePermitViolationDialog(kingdom) {
        var cfg = CONFIG.DRAFT_ANIMAL_LAW || {};
        var fine = cfg.confiscationFine || 500;
        var jailDays = cfg.jailDays || 30;
        var canPay = Player.gold >= fine;

        var html = '<div style="text-align:center;">';
        html += '<p style="font-size:1.1em;color:#c44;">🐴⚠️ <strong>Horse Permit Violation!</strong></p>';
        html += '<p>Guards in <strong>' + kingdom.name + '</strong> have stopped you and discovered you own horses without a valid permit under the <strong>Draft Animal Law</strong>.</p>';
        html += '<p>The fine is <strong style="color:gold;">' + fine + ' gold</strong>.</p>';
        if (!canPay) {
            html += '<p style="color:#c88;">You only have <strong>' + Math.floor(Player.gold) + ' gold</strong> — not enough to pay.</p>';
        }
        html += '<div style="display:flex;gap:8px;justify-content:center;margin-top:12px;">';
        if (canPay) {
            html += '<button class="btn-medieval" onclick="Player.payHorsePermitFine(); UI.closeModal();" style="background:linear-gradient(135deg,#3a5a1a,#4a7a2a);">💰 Pay Fine (' + fine + 'g)</button>';
        }
        html += '<button class="btn-medieval" onclick="Player.refuseHorsePermitFine(); UI.closeModal();" style="background:linear-gradient(135deg,#5a1a1a,#7a2a2a);">🔒 ' + (canPay ? 'Refuse to Pay' : 'Accept Jail') + ' (' + jailDays + ' days)</button>';
        html += '</div>';
        html += '<p style="font-size:0.8em;color:#888;margin-top:10px;">💡 Tip: Buy a permit from the Character panel, or rank up to Burgher to be exempt.</p>';
        html += '</div>';
        openModal('🐴 Draft Animal Violation', html);
    }

    function openTravelOptions(townId) {
        if (_isBankruptcyBlocked()) { toast('💸 You must resolve your bankruptcy first!', 'danger', 'critical'); return; }
        var destTown = Engine.findTown(townId);
        if (!destTown) return;

        // Determine origin — use townId if in town, or nearest town if on road/traveling
        var _originTownId = Player.townId;
        if (!_originTownId && Player.getPlayerWorldPosition) {
            var _oPos = Player.getPlayerWorldPosition();
            if (_oPos) {
                var _oTowns = Engine.getTowns();
                var _oBest = Infinity;
                for (var _oi = 0; _oi < _oTowns.length; _oi++) {
                    var _od = Math.hypot(_oTowns[_oi].x - _oPos.x, _oTowns[_oi].y - _oPos.y);
                    if (_od < _oBest) { _oBest = _od; _originTownId = _oTowns[_oi].id; }
                }
            }
        }
        var currentTown = Engine.findTown(_originTownId);
        if (!currentTown) return;
        if (_originTownId === townId && !Player.traveling) { toast('You are already here.', 'info'); return; }
        if (Player.traveling && Player.travelPaid) { toast('Cannot redirect while on paid transport.', 'warning'); return; }

        // ===== CLOSED BORDERS CHECK =====
        var destKingdom = null;
        var kingdoms = Engine.getKingdoms ? Engine.getKingdoms() : [];
        for (var ki = 0; ki < kingdoms.length; ki++) {
            if (kingdoms[ki].id === destTown.kingdomId) { destKingdom = kingdoms[ki]; break; }
        }
        if (destKingdom && !Player.isPlayerCitizenOf(destKingdom.id)) {
            var hasClosed = false;
            // Check all law storage formats
            if (destKingdom.immigrationPolicy === 'closed') hasClosed = true;
            if (Engine.hasSpecialLaw && Engine.hasSpecialLaw(destKingdom, 'closed_borders')) hasClosed = true;
            if (destKingdom.laws) {
                if (Array.isArray(destKingdom.laws)) {
                    for (var li = 0; li < destKingdom.laws.length; li++) {
                        var law = destKingdom.laws[li];
                        if (law.type === 'closed_borders' || law.type === 'foreign_ban' ||
                            (law.type === 'immigration' && law.policy === 'citizens_only')) hasClosed = true;
                    }
                }
                if (destKingdom.laws.specialLaws) {
                    for (var si = 0; si < destKingdom.laws.specialLaws.length; si++) {
                        if (destKingdom.laws.specialLaws[si].id === 'closed_borders') hasClosed = true;
                    }
                }
            }

            if (hasClosed) {
                _showClosedBordersDialog(destTown, destKingdom, townId);
                return;
            }
        }

        // ===== CALCULATE ROUTES =====
        var mixedRoute = null;
        try { mixedRoute = Engine.findPath(_originTownId, townId); } catch (e) { /* ignore */ }

        var landRoute = null;
        try { landRoute = Engine.findPath(_originTownId, townId, { excludeSea: true }); } catch (e) { /* ignore */ }

        var canSea = false;
        try { canSea = Player.canTravelBySea(townId); } catch (e) { /* ignore */ }

        var hasHorse = Player.horses && Player.horses.length > 0;
        var hasSaddle = Player.inventory && (Player.inventory.saddles || 0) > 0;
        var hasShip = Player.ships && Player.ships.length > 0;
        var playerGold = Player.gold || 0;

        // Cart state
        var playerContainer = Player.state ? Player.state.storageContainer : null;
        var containerCfg = playerContainer ? CONFIG.STORAGE_CONTAINERS[playerContainer] : null;
        var isCartType = containerCfg && (playerContainer === 'cart' || playerContainer === 'small_wagon' || playerContainer === 'wagon' || playerContainer === 'large_wagon');

        // Horse purchase info
        var horseCost = 80;
        var horseAvailable = false;
        if (!hasHorse) {
            try {
                var horsePrice = currentTown.market && currentTown.market.prices && currentTown.market.prices.horses ? currentTown.market.prices.horses : 80;
                horseCost = Math.ceil(horsePrice);
            } catch (e) { /* ignore */ }
            var horseLegal = true;
            try {
                var hKingdom = Engine.findKingdom(currentTown.kingdomId);
                if (hKingdom && hKingdom.laws && hKingdom.laws.bannedGoods && hKingdom.laws.bannedGoods.indexOf('horses') !== -1) {
                    horseLegal = Player.hasLicense && Player.hasLicense(currentTown.kingdomId, 'horses');
                }
            } catch (e) { /* ignore */ }
            horseAvailable = horseLegal && currentTown.market && currentTown.market.supply && (currentTown.market.supply.horses || 0) > 0;
        }

        // ===== SPEED / DISTANCE HELPERS =====
        var baseSpeed = CONFIG.CARAVAN_BASE_SPEED * 1.5;
        if (typeof Player !== 'undefined' && Player.hasSkill && Player.hasSkill('road_knowledge')) baseSpeed *= 1.15;
        if (typeof Player !== 'undefined' && Player.hasSkill && Player.hasSkill('cartographer')) baseSpeed *= 1.05;
        var horseSpd = baseSpeed * (1 + (CONFIG.HORSE_TRAVEL_SPEED_BONUS || 0.3));
        if (hasSaddle) horseSpd *= CONFIG.SADDLE_BONUS_MULTIPLIER || 2;
        var seaSpd = CONFIG.CARAVAN_BASE_SPEED * 1.5 * (CONFIG.SEA_SPEED_MULTIPLIER || 1.5);
        if (typeof Player !== 'undefined' && Player.hasSkill && Player.hasSkill('expert_navigator')) seaSpd *= 1.2;
        var passageSpd = seaSpd * 0.8;

        function _splitRouteDists(route) {
            var ld = 0, sd = 0;
            if (!route) return { land: 0, sea: 0 };
            for (var i = 0; i < route.length; i++) {
                var s = route[i], a = Engine.findTown(s.fromTownId), b = Engine.findTown(s.toTownId);
                if (!a || !b) continue;
                var d = Math.hypot(a.x - b.x, a.y - b.y);
                if (s.type === 'sea') sd += d / (CONFIG.SEA_SPEED_MULTIPLIER || 1.5);
                else if (s.type === 'offroad') ld += d / (CONFIG.OFFROAD_SPEED_MULTIPLIER || 0.25);
                else ld += d / (CONFIG.CARAVAN_ROAD_MULTIPLIER[s.quality || 1] || 1);
            }
            return { land: ld, sea: sd };
        }

        function _calcDays(landDist, seaDist, landMode, seaMode) {
            var ls = (landMode === 'horse' || landMode === 'buy_horse') ? horseSpd : baseSpeed;
            var ss = seaMode === 'sail_own' ? seaSpd : passageSpd;
            var time = (landDist > 0 ? landDist / ls : 0) + (seaDist > 0 ? seaDist / ss : 0);
            return Math.max(1, Math.ceil(time));
        }

        // ===== SEGMENT CHAIN DISPLAY =====
        function _segChain(route) {
            if (!route || !route.length) return '';
            var icons = { road: '🚶', sea: '⛵', offroad: '🥾' };
            var chain = '';
            var first = Engine.findTown(route[0].fromTownId);
            chain += '<span style="white-space:nowrap;">' + (icons[route[0].type] || '🚶') + ' ' + (first ? first.name : '?') + '</span>';
            for (var i = 0; i < route.length; i++) {
                var to = Engine.findTown(route[i].toTownId);
                chain += ' <span style="color:var(--text-muted);">→</span> ';
                chain += '<span style="white-space:nowrap;">' + (icons[route[i].type] || '🚶') + ' ' + (to ? to.name : '?') + '</span>';
            }
            return chain;
        }

        // ===== ROUTE DANGER ASSESSMENT =====
        function _routeDangerInfo(route) {
            if (!route || !route.length) return { level: 'low', label: '🟢 Low', color: '#2ecc71', bandits: 0, atWar: false, modifiers: [], potentialModifiers: [] };
            var maxBandit = 0;
            var atWar = false;
            var hasPirates = false;
            var worstSegSafe = true;
            var worstTownSecurity = 100;
            for (var i = 0; i < route.length; i++) {
                var seg = route[i];
                if (seg.type === 'sea') {
                    hasPirates = true;
                    continue;
                }
                var bt = seg.banditThreat || 0;
                if (bt > maxBandit) maxBandit = bt;
                if (seg.safe === false) worstSegSafe = false;
                // Check actual war status between the two towns' kingdoms
                var fromT = Engine.findTown(seg.fromTownId);
                var toT = Engine.findTown(seg.toTownId);
                if (fromT && toT && fromT.kingdomId !== toT.kingdomId) {
                    var _rdFromK = typeof Engine.findKingdom === 'function' ? Engine.findKingdom(fromT.kingdomId) : null;
                    if (_rdFromK && _rdFromK.atWar && _rdFromK.atWar.has && _rdFromK.atWar.has(toT.kingdomId)) {
                        atWar = true;
                    }
                }
                if (fromT && (fromT.security || 50) < worstTownSecurity) worstTownSecurity = fromT.security || 50;
                if (toT && (toT.security || 50) < worstTownSecurity) worstTownSecurity = toT.security || 50;
            }

            var baseLand = CONFIG.ENCOUNTER_LAND_BASE_CHANCE || 0.05;
            var baseSea = CONFIG.ENCOUNTER_SEA_BASE_CHANCE || 0.04;
            var chance = hasPirates ? baseSea : baseLand;
            var modifiers = [];
            var potentialModifiers = [];

            // Road danger
            if (maxBandit > 50 || !worstSegSafe) {
                var rdm = CONFIG.ENCOUNTER_ROAD_DANGER_MULT || 1.5;
                chance *= rdm;
                modifiers.push({ name: atWar ? '⚔️ War zone road' : '☠️ High bandit activity', effect: '+' + Math.round((rdm - 1) * 100) + '%', bad: true });
            }
            if (worstTownSecurity < 30) {
                var psm = CONFIG.ENCOUNTER_POOR_SECURITY_MULT || 1.3;
                chance *= psm;
                modifiers.push({ name: '🏚️ Poor town security', effect: '+' + Math.round((psm - 1) * 100) + '%', bad: true });
            }
            if (atWar) {
                var wtm = CONFIG.ENCOUNTER_WARTIME_CHANCE_MULT || 1.8;
                chance *= wtm;
                modifiers.push({ name: '⚔️ Wartime multiplier', effect: '+' + Math.round((wtm - 1) * 100) + '%', bad: true });
            }

            // Guards
            var guards = (Player.guards || []).length;
            var guardReduction = hasPirates ? (CONFIG.ENCOUNTER_SEA_GUARD_REDUCTION || 0.70) : (1.0 - (CONFIG.ENCOUNTER_GUARD_REDUCTION || 0.40));
            if (guards > 0) {
                for (var g = 0; g < guards; g++) chance *= guardReduction;
                var totalGuardPct = Math.round((1 - Math.pow(guardReduction, guards)) * 100);
                modifiers.push({ name: '🛡️ Personal guards (' + guards + ')', effect: '-' + totalGuardPct + '%', bad: false });
            } else {
                potentialModifiers.push({ name: '🛡️ Hire guards', desc: 'Each guard reduces encounter chance by ' + Math.round((1 - guardReduction) * 100) + '%', source: 'Character panel → Guards' });
            }
            if (Player.hasSkill && Player.hasSkill('veteran_guards') && guards > 0) {
                chance *= 0.70;
                modifiers.push({ name: '🎖️ Veteran Guards skill', effect: '-30%', bad: false });
            } else if (guards > 0) {
                potentialModifiers.push({ name: '🎖️ Veteran Guards skill', desc: 'Additional -30% with guards', source: 'Learn skill' });
            }

            // Horse
            if (!hasPirates && Player.horses && Player.horses.length > 0) {
                var hr = CONFIG.ENCOUNTER_HORSE_REDUCTION || 0.85;
                chance *= hr;
                modifiers.push({ name: '🐴 Riding horse', effect: '-' + Math.round((1 - hr) * 100) + '%', bad: false });
            } else if (!hasPirates) {
                potentialModifiers.push({ name: '🐴 Horse', desc: '-' + Math.round((1 - (CONFIG.ENCOUNTER_HORSE_REDUCTION || 0.85)) * 100) + '% encounter chance', source: 'Buy at market or stable' });
            }

            // Weapon
            var wepRed = hasPirates ? (CONFIG.ENCOUNTER_SEA_WEAPON_REDUCTION || 0.97) : (CONFIG.ENCOUNTER_WEAPON_REDUCTION || 0.90);
            if (Player.weapon) {
                chance *= wepRed;
                modifiers.push({ name: '⚔️ Carrying weapon', effect: '-' + Math.round((1 - wepRed) * 100) + '%', bad: false });
            } else {
                potentialModifiers.push({ name: '⚔️ Weapon', desc: '-' + Math.round((1 - wepRed) * 100) + '% encounter chance', source: 'Buy at market' });
            }

            // Armor
            var armRed = hasPirates ? (CONFIG.ENCOUNTER_SEA_ARMOR_REDUCTION || 0.98) : (CONFIG.ENCOUNTER_ARMOR_REDUCTION || 0.93);
            if (Player.armor) {
                chance *= armRed;
                modifiers.push({ name: '🛡️ Wearing armor', effect: '-' + Math.round((1 - armRed) * 100) + '%', bad: false });
            } else {
                potentialModifiers.push({ name: '🛡️ Armor', desc: '-' + Math.round((1 - armRed) * 100) + '% encounter chance', source: 'Buy at market' });
            }

            // Skills
            if (Player.hasSkill && Player.hasSkill('street_smart')) {
                var ss = CONFIG.ENCOUNTER_SKILL_STREET_SMART || 0.90;
                chance *= ss;
                modifiers.push({ name: '🧠 Street Smart', effect: '-' + Math.round((1 - ss) * 100) + '%', bad: false });
            } else {
                potentialModifiers.push({ name: '🧠 Street Smart', desc: '-' + Math.round((1 - (CONFIG.ENCOUNTER_SKILL_STREET_SMART || 0.90)) * 100) + '% encounter chance', source: 'Learn skill' });
            }
            if (Player.hasSkill && Player.hasSkill('intimidating_presence')) {
                var ip = CONFIG.ENCOUNTER_SKILL_INTIMIDATING || 0.85;
                chance *= ip;
                modifiers.push({ name: '💪 Intimidating Presence', effect: '-' + Math.round((1 - ip) * 100) + '%', bad: false });
            } else {
                potentialModifiers.push({ name: '💪 Intimidating Presence', desc: '-' + Math.round((1 - (CONFIG.ENCOUNTER_SKILL_INTIMIDATING || 0.85)) * 100) + '% encounter chance', source: 'Learn skill' });
            }
            if (!hasPirates) {
                if (Player.hasSkill && Player.hasSkill('road_knowledge')) {
                    chance *= 0.92;
                    modifiers.push({ name: '🗺️ Road Knowledge', effect: '-8%', bad: false });
                } else {
                    potentialModifiers.push({ name: '🗺️ Road Knowledge', desc: '-8% encounter chance on land', source: 'Learn skill' });
                }
            }
            if (hasPirates) {
                if (Player.hasSkill && Player.hasSkill('expert_navigator')) {
                    chance *= 0.90;
                    modifiers.push({ name: '🧭 Expert Navigator', effect: '-10%', bad: false });
                } else {
                    potentialModifiers.push({ name: '🧭 Expert Navigator', desc: '-10% encounter chance at sea', source: 'Learn skill' });
                }
            }
            // Bandit evasion
            if (!atWar) {
                if (Player.hasSkill && Player.hasSkill('bandit_mastery')) {
                    chance *= 0.50;
                    modifiers.push({ name: '🎯 Bandit Mastery', effect: '-50%', bad: false });
                } else if (Player.hasSkill && Player.hasSkill('bandit_evasion')) {
                    chance *= 0.75;
                    modifiers.push({ name: '🏃 Bandit Evasion', effect: '-25%', bad: false });
                } else {
                    potentialModifiers.push({ name: '🏃 Bandit Evasion', desc: '-25% encounter chance', source: 'Learn skill' });
                    potentialModifiers.push({ name: '🎯 Bandit Mastery', desc: '-50% encounter chance', source: 'Learn skill (advanced)' });
                }
            } else {
                if (Player.hasSkill && Player.hasSkill('bandit_mastery')) {
                    chance *= 0.75;
                    modifiers.push({ name: '🎯 Bandit Mastery (wartime)', effect: '-25%', bad: false });
                }
            }

            // Clamp
            var minC = hasPirates ? (CONFIG.ENCOUNTER_SEA_MIN_CHANCE || 0.0001) : (CONFIG.ENCOUNTER_LAND_MIN_CHANCE || 0.001);
            var maxC = hasPirates ? (CONFIG.ENCOUNTER_SEA_MAX_CHANCE || 0.10) : (CONFIG.ENCOUNTER_LAND_MAX_CHANCE || 0.15);
            chance = Math.max(minC, Math.min(maxC, chance));

            var level = 'low';
            var label = '🟢 Low';
            var color = '#2ecc71';
            if (chance >= 0.06) {
                level = 'high'; label = '🔴 High'; color = '#e74c3c';
            } else if (chance >= 0.025) {
                level = 'medium'; label = '🟡 Medium'; color = '#e67e22';
            }
            return { level: level, label: label, color: color, bandits: maxBandit, atWar: atWar, hasPirates: hasPirates, chance: chance, modifiers: modifiers, potentialModifiers: potentialModifiers };
        }

        // ===== CLASSIFY ROUTES =====
        var mixedHasSea = mixedRoute && mixedRoute.some(function(s) { return s.type === 'sea'; });
        var mixedHasLand = mixedRoute && mixedRoute.some(function(s) { return s.type !== 'sea'; });
        var landValid = landRoute && landRoute.length > 0 && !landRoute.every(function(s) { return s.type === 'sea'; });

        var showLand = landValid;
        var showMixed = mixedRoute && mixedRoute.length > 0 && mixedHasSea && mixedHasLand;
        var showSea = canSea;

        // If mixed has no sea, it's same as land
        if (!mixedHasSea) showMixed = false;

        // Deduplicate land vs mixed
        if (showLand && showMixed && landRoute.length === mixedRoute.length) {
            var _same = true;
            for (var ci = 0; ci < landRoute.length; ci++) {
                if (landRoute[ci].fromTownId !== mixedRoute[ci].fromTownId ||
                    landRoute[ci].toTownId !== mixedRoute[ci].toTownId ||
                    landRoute[ci].type !== mixedRoute[ci].type) { _same = false; break; }
            }
            if (_same) showMixed = false;
        }

        // Fallback: no categorized routes, try mixed as generic
        if (!showLand && !showSea && !showMixed && mixedRoute && mixedRoute.length > 0) showMixed = true;

        // ===== BUILD OPTIONS (tagged with route category) =====
        var options = [];
        var routeLabels = { land: '🚶 Land Route', mixed: '🗺️ Mixed Route', sea: '⛵ Sea Route', god: '⚡ God Mode' };
        var routeDanger = {};
        if (landRoute) routeDanger.land = _routeDangerInfo(landRoute);
        if (mixedRoute) routeDanger.mixed = _routeDangerInfo(mixedRoute);
        if (canSea) routeDanger.sea = { level: 'medium', label: '🟡 Medium', color: '#e67e22', bandits: 0, atWar: false, hasPirates: true };
        routeDanger.god = { level: 'low', label: '🟢 Low', color: '#2ecc71', bandits: 0, atWar: false, hasPirates: false };

        // --- LAND ROUTE OPTIONS ---
        if (showLand) {
            var lDists = _splitRouteDists(landRoute);
            var lChain = _segChain(landRoute);

            // Walk
            options.push({
                id: 'land_walk', icon: '🚶', name: 'Walk',
                desc: 'Travel on foot. Slow but free.',
                cost: 0, days: _calcDays(lDists.land, lDists.sea, 'walk', 'sail_own'),
                available: true, route: 'land', routeChain: lChain,
                action: function () { return Player.travelTo(townId, { bringFamily: _travelBringFamily }); }
            });

            // Ride Horse
            if (hasHorse) {
                options.push({
                    id: 'land_horse', icon: '🐴', name: 'Ride Your Horse',
                    desc: 'Much faster travel. Less tiring.',
                    cost: 0, days: _calcDays(lDists.land, lDists.sea, 'horse', 'sail_own'),
                    available: true, route: 'land', routeChain: lChain,
                    action: function () { return Player.travelTo(townId, { mode: 'horse', bringFamily: _travelBringFamily }); }
                });
            }

            // Buy Horse & Ride
            if (!hasHorse && horseAvailable) {
                var canAffordHorse = playerGold >= horseCost;
                options.push({
                    id: 'land_buy_horse', icon: '🐴💰',
                    name: 'Buy Horse & Ride (' + horseCost + 'g)',
                    desc: 'Purchase a horse first, then ride. You keep the horse after.',
                    cost: horseCost, days: _calcDays(lDists.land, lDists.sea, 'horse', 'sail_own'),
                    available: canAffordHorse,
                    unavailableReason: !canAffordHorse ? 'Not enough gold' : '',
                    route: 'land', routeChain: lChain,
                    action: (function (hCost) { return function () { return Player.buyHorseForTravel(townId, hCost, { bringFamily: _travelBringFamily }); }; })(horseCost)
                });
            }

            // Cart options
            if (isCartType) {
                var cartPenalty = hasHorse ? 1.0 : 1.4;
                var bringSpeed = hasHorse ? horseSpd : baseSpeed;
                var bringDays = Math.max(1, Math.ceil((lDists.land * cartPenalty) / bringSpeed));
                options.push({
                    id: 'land_bring_cart', icon: '🛒',
                    name: 'Bring ' + containerCfg.name,
                    desc: hasHorse ? 'Your horse pulls the ' + containerCfg.name + '. No speed penalty.' : 'Drag the ' + containerCfg.name + ' by hand — 40% slower!',
                    cost: 0, days: bringDays,
                    available: true, route: 'land', routeChain: lChain,
                    action: (function (tid) { return function () { return Player.travelTo(tid, { leaveCart: false, bringFamily: _travelBringFamily }); }; })(townId)
                });

                var leaveDays = hasHorse
                    ? _calcDays(lDists.land, lDists.sea, 'horse', 'sail_own')
                    : _calcDays(lDists.land, lDists.sea, 'walk', 'sail_own');
                options.push({
                    id: 'land_leave_cart', icon: '🛒📦',
                    name: 'Leave ' + containerCfg.name + ' Behind',
                    desc: 'Travel light. Cart may be stolen (15%). Goods on it get raided daily.',
                    cost: 0, days: leaveDays,
                    available: true, route: 'land', routeChain: lChain,
                    action: (function (tid) { return function () { return Player.travelTo(tid, { leaveCart: true, bringFamily: _travelBringFamily }); }; })(townId)
                });
            }

            // Land transport services
            var landTransport = getTransportServices(currentTown, destTown, 'land');
            for (var ti = 0; ti < landTransport.length; ti++) {
                var svc = landTransport[ti];
                options.push({
                    id: 'land_transport_' + ti, icon: svc.icon || '🏇', name: svc.name,
                    desc: svc.desc, cost: svc.price, days: svc.days,
                    available: playerGold >= svc.price,
                    unavailableReason: playerGold < svc.price ? 'Not enough gold' : '',
                    route: 'land', routeChain: lChain,
                    action: (function (service) { return function () { return Player.useTransportService(townId, service, { bringFamily: _travelBringFamily }); }; })(svc)
                });
            }
        }

        // --- MIXED ROUTE OPTIONS ---
        if (showMixed) {
            var mDists = _splitRouteDists(mixedRoute);
            var mChain = _segChain(mixedRoute);

            // Land modes available for mixed route
            var _landModes = [{ id: 'walk', icon: '🚶', name: 'Walk' }];
            if (hasHorse) _landModes.push({ id: 'horse', icon: '🐴', name: 'Ride' });

            // Sea modes available for mixed route
            var _seaModes = [];
            if (hasShip) _seaModes.push({ id: 'sail_own', icon: '⛵', name: 'Sail Own Ship', cost: 0 });
            _seaModes.push({ id: 'sea_passage', icon: '🚢', name: 'Book Passage', cost: CONFIG.SEA_PASSAGE_COST || 50 });

            // Generate one option per land×sea combination
            for (var mli = 0; mli < _landModes.length; mli++) {
                for (var msi = 0; msi < _seaModes.length; msi++) {
                    var lm = _landModes[mli], sm = _seaModes[msi];
                    var mixedCost = sm.cost;
                    var mixedDays = _calcDays(mDists.land, mDists.sea, lm.id, sm.id);
                    var mixedAvail = mixedCost === 0 || playerGold >= mixedCost;
                    options.push({
                        id: 'mixed_' + lm.id + '_' + sm.id,
                        icon: lm.icon + sm.icon,
                        name: lm.name + ' + ' + sm.name,
                        desc: lm.name + ' on land, ' + sm.name.toLowerCase() + ' at sea.',
                        cost: mixedCost, days: mixedDays,
                        available: mixedAvail,
                        unavailableReason: !mixedAvail ? 'Not enough gold' : '',
                        route: 'mixed', routeChain: mChain,
                        action: (function (lMode, sMode) {
                            return function () {
                                return Player.travelTo(townId, { mode: lMode, seaMode: sMode, bringFamily: _travelBringFamily });
                            };
                        })(lm.id, sm.id)
                    });
                }
            }
        }

        // --- SEA ROUTE OPTIONS ---
        if (showSea) {
            var seaDist = 500;
            try {
                var seaRoutes = Engine.getSeaRoutes();
                var sr = null;
                for (var sri = 0; sri < seaRoutes.length; sri++) {
                    var r = seaRoutes[sri];
                    if ((r.fromTownId === Player.townId && r.toTownId === townId) || (r.toTownId === Player.townId && r.fromTownId === townId)) {
                        sr = r;
                        break;
                    }
                }
                if (sr) seaDist = sr.distance || 500;
            } catch (e) { /* ignore */ }

            var seaChain = '<span style="white-space:nowrap;">⛵ ' + (currentTown.name || '?') + '</span>'
                + ' <span style="color:var(--text-muted);">→</span> '
                + '<span style="white-space:nowrap;">⛵ ' + (destTown.name || '?') + '</span>';

            // Sail own ship
            if (hasShip) {
                var sailDays = Math.max(1, Math.ceil(seaDist / seaSpd));
                options.push({
                    id: 'sea_sail', icon: '⛵', name: 'Sail Your Ship',
                    desc: 'Use your own vessel. Risk of pirates and storms.',
                    cost: 0, days: sailDays,
                    available: true, route: 'sea', routeChain: seaChain,
                    action: function () { return Player.travelBySea(townId, { bringFamily: _travelBringFamily }); }
                });
            }

            // Paid passage
            var passageCost = CONFIG.SEA_PASSAGE_COST || 50;
            var passageDays = Math.max(1, Math.ceil(seaDist / passageSpd));
            options.push({
                id: 'sea_passage', icon: '🚢',
                name: 'Book Passage (' + passageCost + 'g)',
                desc: 'Pay for passage on a merchant vessel. Safer than solo.',
                cost: passageCost, days: passageDays,
                available: playerGold >= passageCost,
                unavailableReason: playerGold < passageCost ? 'Not enough gold' : '',
                route: 'sea', routeChain: seaChain,
                action: function () { return Player.travelBySea(townId, { paid: true, bringFamily: _travelBringFamily }); }
            });

            // Sea transport services
            var seaTransport = getTransportServices(currentTown, destTown, 'sea');
            for (var sti = 0; sti < seaTransport.length; sti++) {
                var ssvc = seaTransport[sti];
                options.push({
                    id: 'sea_transport_' + sti, icon: ssvc.icon || '🚢', name: ssvc.name,
                    desc: ssvc.desc, cost: ssvc.price, days: ssvc.days,
                    available: playerGold >= ssvc.price,
                    unavailableReason: playerGold < ssvc.price ? 'Not enough gold' : '',
                    route: 'sea', routeChain: seaChain,
                    action: (function (service) { return function () { return Player.useTransportService(townId, service, { bringFamily: _travelBringFamily }); }; })(ssvc)
                });
            }
        }

        // --- GOD MODE ---
        if (typeof Game !== 'undefined' && Game.isGodMode && Game.isGodMode()) {
            options.push({
                id: 'god_warp', icon: '⚡', name: 'Warp (God Mode)',
                desc: 'Instantly teleport to this town.',
                cost: 0, days: 0,
                available: true, route: 'god', routeChain: '⚡ Instant teleport',
                action: function () {
                    var ps = Player.state;
                    ps.townId = townId;
                    ps.traveling = false;
                    ps.travelRoute = null;
                    ps.travelProgress = 0;
                    ps.travelDestination = null;
                    ps.travelBySea = false;
                    ps.travelOffroad = false;
                    if (destTown) {
                        ps.worldX = destTown.x;
                        ps.worldY = destTown.y;
                    }
                    toast('⚡ Warped to ' + destTown.name + '!', 'success');
                    closeModal();
                }
            });
        }

        // ===== BUILD THE MODAL =====
        if (options.length === 0) {
            toast('No travel route available to ' + destTown.name + '.', 'warning');
            return;
        }

        var html = '<div style="max-height:450px;overflow-y:auto;">';
        html += '<p style="font-size:0.85rem;color:var(--text-muted);margin-bottom:10px;">\u{1F4CD} ' + (currentTown.name || '?') + ' \u2192 ' + (destTown.name || '?') + '</p>';

        // "Bring Family" checkbox if family members are in the same town
        var _familyInTown = [];
        if (typeof Player !== 'undefined' && Player.familyMembers && Player.familyMembers.length > 0) {
            for (var _ffi = 0; _ffi < Player.familyMembers.length; _ffi++) {
                var _ffm = Player.familyMembers[_ffi];
                var _ffp = Engine.findPerson(_ffm.npcId);
                if (_ffp && _ffp.alive && _ffp.townId === Player.townId) {
                    _familyInTown.push(_ffm);
                }
            }
        }
        if (_familyInTown.length > 0) {
            html += '<div style="background:rgba(139,115,85,0.12);border:1px solid rgba(255,255,255,0.12);border-radius:8px;padding:8px 10px;margin-bottom:10px;">';
            html += '<label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:0.88rem;color:var(--parchment);">';
            html += '<input type="checkbox" id="travelBringFamily" style="width:16px;height:16px;cursor:pointer;">';
            html += '<span>👨‍👩‍👧‍👦 Bring family along</span>';
            html += '</label>';
            html += '<div style="font-size:0.75rem;color:var(--text-muted);margin-top:4px;padding-left:24px;">';
            var _familyNames = _familyInTown.map(function(f) { return f.name + ' (' + f.role + ')'; });
            html += _familyNames.join(', ');
            html += '<br><span style="color:#e67e22;">⚠️ Family can be injured in encounters!</span>';
            html += '</div>';
            html += '</div>';
        }

        // Group options by route category
        var _routeOrder = ['land', 'mixed', 'sea', 'god'];
        for (var ro = 0; ro < _routeOrder.length; ro++) {
            var routeKey = _routeOrder[ro];
            var routeOpts = [];
            for (var oi = 0; oi < options.length; oi++) {
                if (options[oi].route === routeKey) routeOpts.push(options[oi]);
            }
            if (routeOpts.length === 0) continue;

            // Route category card
            html += '<div style="background:rgba(139,115,85,0.08);border:1px solid rgba(255,255,255,0.12);border-radius:8px;padding:10px;margin-bottom:10px;">';
            var _rdInfo = routeDanger[routeKey];
            var _dangerHtml = '';
            if (_rdInfo && routeKey !== 'god') {
                var _dangerTip = _rdInfo.level.charAt(0).toUpperCase() + _rdInfo.level.slice(1) + ' risk';
                var _tipParts = [];
                if (_rdInfo.bandits > 0) _tipParts.push('Bandit threat: ' + _rdInfo.bandits + '/100');
                if (_rdInfo.atWar) _tipParts.push('War zone');
                if (_rdInfo.hasPirates) _tipParts.push('Pirates active');
                _dangerTip += _tipParts.length ? ' (' + _tipParts.join(', ') + ')' : '';
                _dangerTip += ' — Click for details';
                var _riskTypeLabel = _rdInfo.hasPirates && _rdInfo.bandits === 0 ? 'Pirate Risk' : (_rdInfo.atWar ? 'War Risk' : 'Bandit Risk');
                _dangerHtml = ' <span onclick="UI.showRouteDangerDetail(\'' + routeKey + '\')" style="font-size:0.75rem;margin-left:6px;cursor:pointer;" title="' + _dangerTip + '">⚔️ <span style="color:' + _rdInfo.color + ';font-weight:bold;">' + _rdInfo.level.charAt(0).toUpperCase() + _rdInfo.level.slice(1) + '</span> <span style="color:#ddd;">' + _riskTypeLabel + '</span></span>';
            }
            html += '<div style="font-size:0.95rem;font-weight:bold;margin-bottom:4px;">' + (routeLabels[routeKey] || routeKey) + _dangerHtml + '</div>';
            html += '<div style="font-size:0.78rem;color:var(--text-muted);margin-bottom:8px;line-height:1.5;">' + routeOpts[0].routeChain + '</div>';

            // Options within this category
            for (var oi2 = 0; oi2 < routeOpts.length; oi2++) {
                var opt = routeOpts[oi2];
                var isAvail = opt.available;
                var opacity = isAvail ? '1' : '0.4';

                html += '<div style="background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.08);border-radius:5px;padding:8px;margin-bottom:6px;opacity:' + opacity + ';">';
                html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
                html += '<div style="flex:1;min-width:0;">';
                html += '<span style="font-size:1rem;">' + opt.icon + '</span> ';
                html += '<strong style="font-size:0.88rem;">' + opt.name + '</strong>';
                html += '<br><span style="font-size:0.75rem;color:var(--text-muted);">' + opt.desc + '</span>';
                html += '</div>';
                html += '<div style="text-align:right;min-width:75px;margin-left:8px;">';
                if (opt.days === 0) {
                    html += '<div style="font-size:0.85rem;color:#8f8;">⚡ Instant</div>';
                } else {
                    html += '<div style="font-size:0.85rem;color:var(--gold);">\u23F1\uFE0F ~' + opt.days + ' day' + (opt.days !== 1 ? 's' : '') + '</div>';
                }
                if (opt.cost > 0) {
                    html += '<div style="font-size:0.8rem;color:#c9a96e;">\u{1F4B0} ' + opt.cost + 'g</div>';
                } else {
                    html += '<div style="font-size:0.8rem;color:#8f8;">Free</div>';
                }
                html += '</div>';
                html += '</div>';
                if (isAvail) {
                    html += '<button class="btn-medieval" style="width:100%;margin-top:5px;padding:5px;font-size:0.85rem;" onclick="UI.confirmTravel(\'' + townId + '\',\'' + opt.id + '\')">Select</button>';
                } else {
                    html += '<div style="text-align:center;margin-top:3px;font-size:0.78rem;color:#c44e52;">' + (opt.unavailableReason || 'Unavailable') + '</div>';
                }
                html += '</div>';
            }

            html += '</div>'; // end route card
        }

        html += '</div>';

        // Store options for confirm handler
        _travelOptions = options;
        _travelDestTownId = townId;
        _travelRouteDanger = routeDanger;

        openModal('\u{1F5FA}\uFE0F Travel to ' + destTown.name, html);
    }

    function confirmTravel(townId, optionId) {
        var options = _travelOptions || [];
        var opt = null;
        for (var i = 0; i < options.length; i++) {
            if (options[i].id === optionId) { opt = options[i]; break; }
        }
        if (!opt || !opt.available || !opt.action) return;

        // Check quarantine before executing travel (skip for god mode warp)
        if (optionId !== 'god_warp' && typeof Player !== 'undefined' && Player.getRouteQuarantineInfo) {
            var qInfo = Player.getRouteQuarantineInfo(townId);
            if (qInfo && qInfo.blocked) {
                // Show quarantine decision popup instead of traveling
                _showQuarantinePopup(townId, optionId, qInfo);
                return;
            }
        }

        // No quarantine or player passes freely — execute travel
        _executeTravel(townId, opt);
    }

    function _showQuarantinePopup(townId, optionId, qInfo) {
        var qIcon = qInfo.isMartial ? '⚔️🔒' : '🔒';
        var sneakPct = Math.round(qInfo.sneakChance * 100);
        var playerGold = (typeof Player !== 'undefined' && Player.gold != null) ? Player.gold : 0;

        var html = '<div style="max-width:460px;">';

        // Header
        html += '<div style="text-align:center;margin-bottom:12px;">';
        html += '<div style="font-size:2rem;">' + qIcon + '</div>';
        html += '<div style="font-size:1.2rem;color:var(--gold-bright);font-weight:bold;margin-top:4px;">' + qInfo.townName + ' is under ' + qInfo.qLabel + '!</div>';
        html += '</div>';

        // Guard name
        var _guardRelTag = '';
        if (qInfo.guardRelLevel >= 60) _guardRelTag = ' <span style="color:#55a868;font-size:0.75rem;">(Friendly)</span>';
        else if (qInfo.guardRelLevel >= 40) _guardRelTag = ' <span style="color:#e6c422;font-size:0.75rem;">(Known)</span>';
        html += '<div style="text-align:center;margin-bottom:10px;font-size:0.9rem;color:var(--parchment);">🛡️ Guard: <strong style="color:var(--gold);">' + (qInfo.guardName || 'Guard Captain') + '</strong>' + _guardRelTag + '</div>';

        html += '<div style="background:rgba(196,78,82,0.15);border:1px solid rgba(196,78,82,0.3);border-radius:6px;padding:10px;margin-bottom:10px;">';
        html += '<div style="font-size:0.85rem;color:var(--parchment);">Your route passes through a quarantine zone. Travel is restricted to certain social ranks.</div>';
        html += '</div>';

        // Allowed ranks
        html += '<div style="margin-bottom:10px;">';
        html += '<div style="font-size:0.8rem;color:var(--gold);font-weight:bold;margin-bottom:3px;">✅ Allowed Through:</div>';
        for (var ri = 0; ri < qInfo.allowedRanks.length; ri++) {
            html += '<div style="font-size:0.8rem;color:var(--parchment);padding-left:12px;">• ' + qInfo.allowedRanks[ri] + '</div>';
        }
        html += '</div>';

        // === Sneak Past section ===
        html += '<div style="background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);border-radius:6px;padding:10px;margin-bottom:10px;">';
        html += '<div style="font-size:0.85rem;color:var(--gold);font-weight:bold;margin-bottom:4px;">🤫 Sneak Past the Guards</div>';

        // Sneak chance bar
        var barColor = sneakPct >= 50 ? '#55a868' : (sneakPct >= 30 ? '#e67e22' : '#c44e52');
        html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;">';
        html += '<div style="font-size:0.8rem;color:var(--text-muted);min-width:90px;">Sneak chance:</div>';
        html += '<div style="flex:1;height:14px;background:rgba(0,0,0,0.3);border-radius:7px;overflow:hidden;">';
        html += '<div style="width:' + sneakPct + '%;height:100%;background:' + barColor + ';border-radius:7px;"></div>';
        html += '</div>';
        html += '<div style="font-size:0.9rem;font-weight:bold;color:' + barColor + ';min-width:40px;text-align:right;">' + sneakPct + '%</div>';
        html += '</div>';

        // Sneak skill modifiers
        if (qInfo.sneakModifiers && qInfo.sneakModifiers.length > 0) {
            html += '<div style="font-size:0.72rem;color:var(--text-muted);margin-bottom:4px;">Bonuses: ';
            var _smParts = [];
            for (var _smi = 0; _smi < qInfo.sneakModifiers.length; _smi++) {
                _smParts.push(qInfo.sneakModifiers[_smi].name + ' (+' + qInfo.sneakModifiers[_smi].bonus + '%)');
            }
            html += _smParts.join(', ') + '</div>';
        }

        // Sneak button
        html += '<button class="btn-medieval" style="width:100%;padding:8px 10px;font-size:0.9rem;background:rgba(196,78,82,0.25);border:2px solid rgba(196,78,82,0.6);color:#f0e6d2;" onclick="UI._quarantineSneakAttempt(\'' + townId + '\',\'' + optionId + '\')">🤫 <strong style="color:#fff;">Try to Sneak</strong> (<span style="color:#e67e22;font-weight:bold;">' + sneakPct + '%</span>)</button>';
        html += '</div>';

        // === Bribe the Guard section ===
        html += '<div style="background:rgba(218,165,32,0.08);border:1px solid rgba(218,165,32,0.25);border-radius:6px;padding:10px;margin-bottom:10px;">';
        html += '<div style="font-size:0.85rem;color:var(--gold);font-weight:bold;margin-bottom:6px;">💰 Bribe the Guard</div>';

        if (qInfo.bribes && qInfo.bribes.length > 0) {
            var _bribeColors = { low: '#c44e52', medium: '#e67e22', high: '#55a868' };
            for (var _bi = 0; _bi < qInfo.bribes.length; _bi++) {
                var _b = qInfo.bribes[_bi];
                var _bPct = Math.round(_b.chance * 100);
                var _bColor = _bribeColors[_b.tier] || '#888';
                var _bDisabled = playerGold < _b.cost;
                var _bStyle = 'width:100%;padding:8px 10px;font-size:0.85rem;margin-bottom:4px;';
                if (_bDisabled) {
                    _bStyle += 'opacity:0.4;cursor:not-allowed;background:rgba(100,100,100,0.2);border-color:rgba(100,100,100,0.3);color:#888;';
                } else {
                    _bStyle += 'background:rgba(' + (_b.tier === 'low' ? '196,78,82' : (_b.tier === 'medium' ? '230,126,34' : '85,168,104')) + ',0.25);border:2px solid ' + _bColor + ';color:#f0e6d2;';
                }
                html += '<button class="btn-medieval" style="' + _bStyle + '"';
                if (_bDisabled) {
                    html += ' disabled';
                } else {
                    html += ' onclick="UI._quarantineBribeAttempt(\'' + townId + '\',\'' + optionId + '\',\'' + _b.tier + '\',' + _b.cost + ')"';
                }
                html += '>';
                html += '<strong style="color:#fff;">' + _b.label + '</strong> — <strong style="color:#ffd700;">' + _b.cost + 'g</strong> (<span style="color:' + _bColor + ';font-weight:bold;font-size:1rem;">' + _bPct + '%</span>)';
                if (_bDisabled) html += ' <span style="font-size:0.75rem;color:#888;">(not enough gold)</span>';
                html += '</button>';
            }
        }

        // Bribe skill modifiers
        if (qInfo.bribeModifiers && qInfo.bribeModifiers.length > 0) {
            html += '<div style="font-size:0.72rem;color:var(--text-muted);margin-top:2px;">Bonuses: ';
            var _bmParts = [];
            for (var _bmi = 0; _bmi < qInfo.bribeModifiers.length; _bmi++) {
                _bmParts.push(qInfo.bribeModifiers[_bmi].name + ' (+' + qInfo.bribeModifiers[_bmi].bonus + '%)');
            }
            html += _bmParts.join(', ') + '</div>';
        }
        html += '</div>';

        // === Doctor Persuasion section ===
        if (qInfo.doctorPersuasion) {
            var _dp = qInfo.doctorPersuasion;
            var _dpPct = Math.round(_dp.chance * 100);
            html += '<div style="background:rgba(46,204,113,0.08);border:1px solid rgba(46,204,113,0.25);border-radius:6px;padding:10px;margin-bottom:10px;">';
            html += '<div style="font-size:0.85rem;color:var(--gold);font-weight:bold;margin-bottom:6px;">⚕️ Medical Persuasion</div>';
            html += '<div style="font-size:0.8rem;color:var(--parchment);margin-bottom:6px;">Convince the guard you need passage for medical reasons. <strong style="color:#55a868;">No penalty if refused</strong> — 7 day cooldown on failure.</div>';
            if (_dp.reasons && _dp.reasons.length > 0) {
                html += '<div style="font-size:0.72rem;color:var(--text-muted);margin-bottom:6px;">';
                for (var _dri = 0; _dri < _dp.reasons.length; _dri++) {
                    html += '<div>• ' + _dp.reasons[_dri] + '</div>';
                }
                html += '</div>';
            }
            if (_dp.onCooldown) {
                html += '<button class="btn-medieval" style="width:100%;padding:8px 10px;font-size:0.85rem;opacity:0.4;cursor:not-allowed;background:rgba(100,100,100,0.2);border-color:rgba(100,100,100,0.3);color:#888;" disabled>';
                html += '⚕️ <strong>Persuade Guard</strong> — cooldown: ' + _dp.cooldownDays + ' day' + (_dp.cooldownDays > 1 ? 's' : '') + ' remaining';
                html += '</button>';
            } else {
                html += '<button class="btn-medieval" style="width:100%;padding:8px 10px;font-size:0.85rem;background:rgba(46,204,113,0.25);border:2px solid #55a868;color:#f0e6d2;" onclick="UI._quarantineDoctorPersuade(\'' + townId + '\',\'' + optionId + '\')">';
                html += '⚕️ <strong style="color:#fff;">Persuade Guard</strong> (<span style="color:#55a868;font-weight:bold;font-size:1rem;">' + _dpPct + '%</span>)';
                html += '</button>';
            }
            html += '</div>';
        }

        // === Consequences Warning ===
        html += '<div style="background:rgba(139,69,19,0.12);border:1px solid rgba(139,69,19,0.3);border-radius:6px;padding:8px;margin-bottom:10px;font-size:0.78rem;color:var(--text-muted);">';
        html += '<div style="font-weight:bold;color:var(--gold);margin-bottom:3px;">⚠️ Consequences if Caught</div>';
        html += '<div>Sneaking: <strong>' + (qInfo.sneakFine || 0) + 'g</strong> fine or <strong>' + (qInfo.sneakJailDays || 0) + '</strong> days jail</div>';
        html += '<div>Bribing: <strong>' + (qInfo.bribeFine || 0) + 'g</strong> fine or <strong>' + (qInfo.bribeJailDays || 0) + '</strong> days jail <span style="color:#c44e52;">(bribery charge)</span></div>';
        var _kingDesc = 'fair';
        if (qInfo.kingTemperament === 'strict') _kingDesc = '<span style="color:#c44e52;">strict</span>';
        else if (qInfo.kingTemperament === 'merciful') _kingDesc = '<span style="color:#55a868;">merciful</span>';
        html += '<div style="margin-top:3px;font-style:italic;">This king is known to be ' + _kingDesc + '.</div>';
        html += '</div>';

        // Turn Back button
        html += '<div style="text-align:center;">';
        html += '<button class="btn-medieval" style="padding:8px 24px;font-size:0.9rem;" data-action="closeModal">🚫 Turn Back</button>';
        html += '</div>';

        html += '</div>';
        openModal(qIcon + ' Quarantine Checkpoint', html);
    }

    function _quarantineSneakAttempt(townId, optionId) {
        closeModal();

        // Execute the sneak attempt through Player
        var sneakResult = Player.attemptQuarantineSneak(townId);

        if (sneakResult && !sneakResult.allowed) {
            // Caught — message already toasted by _checkRouteQuarantine
            return;
        }

        // Sneak succeeded or no quarantine — proceed with travel, skipping the quarantine check
        var options = _travelOptions || [];
        var opt = null;
        for (var i = 0; i < options.length; i++) {
            if (options[i].id === optionId) { opt = options[i]; break; }
        }
        if (!opt || !opt.action) return;

        if (sneakResult && sneakResult.allowed && sneakResult.message) {
            toast(sneakResult.message, 'success', 'travel_events');
        }

        // Wrap the action to add skipQuarantineCheck
        closeRightPanel();
        try {
            // We need to pass skipQuarantineCheck to the underlying Player.travelTo call
            // Temporarily patch the action to include skipQuarantineCheck
            var result = _executeTravelAction(townId, opt);
            if (result && result.success === false) {
                toast(result.message || 'Travel failed.', 'danger');
                return;
            }
        } catch (e) {
            toast('Travel error: ' + (e.message || e), 'danger');
            return;
        }
        if (typeof Renderer !== 'undefined') {
            var town = Engine.getTown(townId);
            if (town) Renderer.panTo(town.x, town.y);
        }
    }

    function _quarantineBribeAttempt(townId, optionId, tier, bribeCost) {
        closeModal();

        // Execute the bribe attempt through Player
        var bribeResult = Player.attemptQuarantineBribe(townId, tier, bribeCost);

        if (bribeResult && !bribeResult.allowed) {
            // Caught — message already toasted by attemptQuarantineBribe
            return;
        }

        // Bribe succeeded — proceed with travel, skipping the quarantine check
        var options = _travelOptions || [];
        var opt = null;
        for (var i = 0; i < options.length; i++) {
            if (options[i].id === optionId) { opt = options[i]; break; }
        }
        if (!opt || !opt.action) return;

        if (bribeResult && bribeResult.allowed && bribeResult.message) {
            toast(bribeResult.message, 'success', 'travel_events');
        }

        closeRightPanel();
        try {
            var result = _executeTravelAction(townId, opt);
            if (result && result.success === false) {
                toast(result.message || 'Travel failed.', 'danger');
                return;
            }
        } catch (e) {
            toast('Travel error: ' + (e.message || e), 'danger');
            return;
        }
        if (typeof Renderer !== 'undefined') {
            var town = Engine.getTown(townId);
            if (town) Renderer.panTo(town.x, town.y);
        }
    }

    function _quarantineDoctorPersuade(townId, optionId) {
        closeModal();

        var result = Player.attemptQuarantineDoctorPersuasion(townId);

        if (result && !result.allowed) {
            // Failed — toast already shown by player.js, re-open popup after brief delay
            setTimeout(function() {
                var qInfo = Player.getRouteQuarantineInfo(townId);
                if (qInfo && qInfo.blocked) _showQuarantinePopup(townId, optionId, qInfo);
            }, 1500);
            return;
        }

        // Success — proceed with travel
        var options = _travelOptions || [];
        var opt = null;
        for (var i = 0; i < options.length; i++) {
            if (options[i].id === optionId) { opt = options[i]; break; }
        }
        if (!opt || !opt.action) return;

        if (result && result.allowed && result.message) {
            toast(result.message, 'success', 'travel_events');
        }

        closeRightPanel();
        try {
            var travelResult = _executeTravelAction(townId, opt);
            if (travelResult && travelResult.success === false) {
                toast(travelResult.message || 'Travel failed.', 'danger');
                return;
            }
        } catch (e) {
            toast('Travel error: ' + (e.message || e), 'danger');
            return;
        }
        if (typeof Renderer !== 'undefined') {
            var town = Engine.getTown(townId);
            if (town) Renderer.panTo(town.x, town.y);
        }
    }

    function _executeTravelAction(townId, opt) {
        // For standard travel options, call Player.travelTo with skipQuarantineCheck
        // Parse the option to determine what kind of travel
        if (opt.id && opt.id.indexOf('land_walk') === 0) return Player.travelTo(townId, { skipQuarantineCheck: true, bringFamily: _travelBringFamily });
        if (opt.id && opt.id.indexOf('land_horse') === 0) return Player.travelTo(townId, { mode: 'horse', skipQuarantineCheck: true, bringFamily: _travelBringFamily });
        if (opt.id && opt.id.indexOf('land_buy_horse') === 0) {
            return Player.buyHorseForTravel(townId, opt.cost, { skipQuarantineCheck: true, bringFamily: _travelBringFamily });
        }
        if (opt.id && opt.id.indexOf('land_bring_cart') === 0) return Player.travelTo(townId, { leaveCart: false, skipQuarantineCheck: true, bringFamily: _travelBringFamily });
        if (opt.id && opt.id.indexOf('land_leave_cart') === 0) return Player.travelTo(townId, { leaveCart: true, skipQuarantineCheck: true, bringFamily: _travelBringFamily });
        if (opt.id && opt.id.indexOf('mixed_') === 0) {
            var parts = opt.id.replace('mixed_', '').split('_');
            var lMode = parts[0];
            var sMode = parts.slice(1).join('_');
            return Player.travelTo(townId, { mode: lMode, seaMode: sMode, skipQuarantineCheck: true, bringFamily: _travelBringFamily });
        }
        // Fallback: just call the original action
        return opt.action();
    }

    function _executeTravel(townId, opt) {
        // Check "Bring Family" checkbox before closing modal
        var _bringFamily = false;
        var cbEl = document.getElementById('travelBringFamily');
        if (cbEl && cbEl.checked) _bringFamily = true;
        _travelBringFamily = _bringFamily;

        closeModal();
        closeRightPanel();
        try {
            var result = opt.action();
            if (result && result.success === false) {
                toast(result.message || 'Travel failed.', 'danger');
                return;
            }
        } catch (e) {
            toast('Travel error: ' + (e.message || e), 'danger');
            return;
        }
        if (typeof Renderer !== 'undefined') {
            var town = Engine.getTown(townId);
            if (town) Renderer.panTo(town.x, town.y);
        }
    }

    function showRouteDangerDetail(routeKey) {
        var info = _travelRouteDanger[routeKey];
        if (!info) return;
        var routeNames = { land: 'Land Route', mixed: 'Mixed Route', sea: 'Sea Route' };
        var html = '<div style="max-height:400px;overflow-y:auto;">';

        // Header
        html += '<div style="text-align:center;margin-bottom:12px;">';
        html += '<div style="font-size:1.5rem;">' + info.label + '</div>';
        html += '<div style="font-size:0.85rem;color:var(--text-muted);">' + (routeNames[routeKey] || routeKey) + ' — Encounter Risk</div>';
        html += '<div style="font-size:0.8rem;color:' + info.color + ';margin-top:4px;">Daily encounter chance: ~' + (info.chance * 100).toFixed(1) + '%</div>';
        html += '</div>';

        // Active modifiers
        html += '<div style="margin-bottom:12px;">';
        html += '<div style="font-size:0.85rem;font-weight:bold;margin-bottom:6px;color:var(--gold);">Active Modifiers</div>';
        if (info.modifiers && info.modifiers.length > 0) {
            for (var i = 0; i < info.modifiers.length; i++) {
                var m = info.modifiers[i];
                var mColor = m.bad ? '#e74c3c' : '#2ecc71';
                html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:4px 6px;margin-bottom:3px;background:rgba(' + (m.bad ? '200,50,50' : '46,204,113') + ',0.08);border-radius:4px;border-left:3px solid ' + mColor + ';">';
                html += '<span style="font-size:0.8rem;">' + m.name + '</span>';
                html += '<span style="font-size:0.8rem;font-weight:bold;color:' + mColor + ';">' + m.effect + '</span>';
                html += '</div>';
            }
        } else {
            html += '<div style="font-size:0.8rem;color:#888;font-style:italic;">No active modifiers — base risk only.</div>';
        }
        html += '</div>';

        // How to reduce risk
        html += '<div style="margin-bottom:12px;">';
        html += '<div style="font-size:0.85rem;font-weight:bold;margin-bottom:6px;color:var(--gold);">How to Reduce Risk</div>';
        if (info.potentialModifiers && info.potentialModifiers.length > 0) {
            for (var j = 0; j < info.potentialModifiers.length; j++) {
                var pm = info.potentialModifiers[j];
                html += '<div style="padding:4px 6px;margin-bottom:3px;background:rgba(255,255,255,0.04);border-radius:4px;border-left:3px solid #555;">';
                html += '<div style="font-size:0.8rem;color:#aaa;">' + pm.name + ' <span style="color:#6a9;">' + pm.desc + '</span></div>';
                html += '<div style="font-size:0.72rem;color:#777;margin-top:1px;">📍 ' + pm.source + '</div>';
                html += '</div>';
            }
        } else {
            html += '<div style="font-size:0.8rem;color:#2ecc71;">✅ You have all available protections!</div>';
        }
        html += '</div>';

        // Route conditions
        html += '<div style="padding:8px;background:rgba(0,0,0,0.2);border-radius:4px;font-size:0.78rem;color:var(--text-muted);">';
        html += '<strong>Route Conditions:</strong><br>';
        if (info.bandits > 0) {
            html += '☠️ Max bandit threat: ' + info.bandits + '/100<br>';
        } else if (!info.hasPirates) {
            html += '☠️ Bandit threat: None<br>';
        }
        if (info.atWar) html += '⚔️ <span style="color:#e74c3c;">Passes through war zone!</span><br>';
        if (info.hasPirates) html += '🏴‍☠️ <span style="color:#e67e22;">Sea segment — pirates possible</span><br>';
        html += '</div>';

        html += '</div>';
        openModal('⚔️ Route Danger: ' + (routeNames[routeKey] || routeKey), html, '<button class="btn-medieval" data-action="closeModal">Close</button>');
    }

    function turnBackUI() {
        if (typeof Player === 'undefined' || !Player.turnBack) return;
        var result = Player.turnBack();
        if (result && result.success) {
            toast('🔄 Turning back...', 'info', 'travel_events');
            update(); // refresh travel panel immediately
        } else {
            toast((result && result.message) || 'Cannot turn back', 'warning');
        }
    }

    function stopTravelUI() {
        if (typeof Player === 'undefined' || !Player.stopTravel) return;
        var result = Player.stopTravel();
        if (result && result.success) {
            if (result.atTown) {
                toast('🛑 Stopped at ' + result.atTown + '.', 'info', 'travel_events');
            } else {
                toast('🛑 Stopped on the road.', 'info', 'travel_events');
            }
            update(); // refresh UI to show town/wilderness view
        } else {
            toast((result && result.message) || 'Cannot stop', 'warning');
        }
    }

    function travelTo(townId) {
        if (_isBankruptcyBlocked()) { toast('💸 You must resolve your bankruptcy first!', 'danger', 'critical'); return; }
        try {
            const result = Player.travelTo(townId);
            if (result && result.success) {
                toast('Traveling by land...', 'info');
            } else {
                toast((result && result.message) || 'Cannot travel', 'danger');
            }
            closeRightPanel();
            if (typeof Renderer !== 'undefined') {
                const town = Engine.getTown(townId);
                if (town) Renderer.panTo(town.x, town.y);
            }
        } catch (e) {
            toast(e.message || 'Cannot travel', 'danger');
        }
    }

    function travelBySeaUI(townId) {
        if (_isBankruptcyBlocked()) { toast('💸 You must resolve your bankruptcy first!', 'danger', 'critical'); return; }
        try {
            const result = Player.travelBySea(townId);
            if (result && result.success) {
                toast(result.message || 'Setting sail...', 'info');
            } else {
                toast((result && result.message) || 'Cannot sail', 'danger');
            }
            closeRightPanel();
            if (typeof Renderer !== 'undefined') {
                const town = Engine.getTown(townId);
                if (town) Renderer.panTo(town.x, town.y);
            }
        } catch (e) {
            toast(e.message || 'Cannot sail', 'danger');
        }
    }

    function forageNearby() {
        try {
            const result = Player.forage();
            toast(result.message, result.success ? 'success' : 'warning');
            if (Player.townId) showTownDetail(Engine.findTown(Player.townId));
        } catch (e) {
            toast(e.message || 'Cannot forage here', 'warning');
        }
    }

    function rebuildBridge(roadIdx) {
        try {
            const result = Player.playerRebuildBridge(roadIdx);
            toast(result.message, result.success ? 'success' : 'warning');
            if (Player.townId) showTownDetail(Engine.findTown(Player.townId));
        } catch (e) {
            toast(e.message || 'Cannot rebuild bridge', 'warning');
        }
    }

    function repairBridgeUI(roadIdx, bridgeId) {
        try {
            var result = Player.playerRebuildBridge(roadIdx, bridgeId);
            toast(result.message, result.success ? 'success' : 'warning');
        } catch (e) {
            toast(e.message || 'Cannot repair bridge', 'warning');
        }
    }

    function destroyBridge(roadIdx) {
        // Check if already destroying a bridge
        if (Player.bridgeDestruction) {
            var status = Player.getBridgeDestructionStatus();
            if (status) {
                var html = '<div style="text-align:center;margin-bottom:12px;">';
                html += '<div style="font-size:1.2rem;">💣 Bridge Sabotage In Progress</div>';
                html += '<div style="font-size:0.85rem;color:#ccc;margin-top:8px;">';
                html += '<strong>' + status.fromTown + ' – ' + status.toTown + '</strong><br>';
                html += 'Method: ' + status.methodName + '<br>';
                html += 'Progress: Day ' + status.daysElapsed + ' / ' + status.totalDays + '<br>';
                html += 'Detection risk: ' + Math.round(status.detectionRate * 100) + '% per day<br>';
                html += '</div>';
                html += '<div style="margin-top:8px;background:rgba(0,0,0,0.3);border-radius:4px;height:12px;overflow:hidden;">';
                var pct = Math.round((status.daysElapsed / status.totalDays) * 100);
                html += '<div style="height:100%;width:' + pct + '%;background:linear-gradient(90deg,#c44e52,#e67e22);transition:width 0.3s;"></div>';
                html += '</div>';
                html += '<div style="font-size:0.75rem;color:#aaa;margin-top:4px;">' + status.daysRemaining + ' days remaining</div>';
                html += '</div>';
                html += '<div style="text-align:center;">';
                html += '<button class="btn-medieval" onclick="(function(){var r=Player.cancelBridgeDestruction();UI.toast(r.message,r.success?\'warning\':\'danger\');UI.closeModal();})()" style="background:rgba(200,60,50,0.35);border-color:rgba(200,60,50,0.6);color:#f0d0a0;">⏹️ Cancel Sabotage</button>';
                html += '</div>';
                openModal('💣 Bridge Sabotage', html);
                return;
            }
        }

        var roads = Engine.getRoads();
        var road = roads[roadIdx];
        if (!road || !road.hasBridge) { toast('No bridge on this road.', 'warning'); return; }
        if (road.bridgeDestroyed) { toast('Bridge already destroyed.', 'warning'); return; }

        var fromTown = Engine.findTown(road.fromTownId);
        var toTown = Engine.findTown(road.toTownId);
        var bridgeName = (fromTown ? fromTown.name : '?') + ' – ' + (toTown ? toTown.name : '?');

        var methods = CONFIG.BRIDGE_DESTROY_METHODS;
        if (!methods) { toast('Bridge destruction not configured.', 'warning'); return; }

        var hasSkill = false;
        var skillNames = CONFIG.BRIDGE_DESTROY_SKILLS || [];
        for (var si = 0; si < skillNames.length; si++) {
            if (typeof Player.hasSkill === 'function' && Player.hasSkill(skillNames[si])) { hasSkill = true; break; }
        }

        var cost = CONFIG.BRIDGE_DESTROY_COST || 500;
        var html = '<div style="text-align:center;margin-bottom:12px;">';
        html += '<div style="font-size:0.9rem;color:var(--gold);">🌉 Bridge: <strong>' + bridgeName + '</strong></div>';
        html += '<div style="font-size:0.8rem;color:#ccc;margin-top:4px;">Cost: <strong>' + cost + 'g</strong> + materials below</div>';
        if (hasSkill) {
            html += '<div style="font-size:0.75rem;color:#7bed9f;margin-top:4px;">✅ Relevant skills detected — faster & stealthier</div>';
        }
        html += '</div>';

        html += '<div style="display:flex;flex-direction:column;gap:8px;">';
        for (var key in methods) {
            var m = methods[key];
            var days = hasSkill ? m.skilledDays : m.baseDays;
            var detect = hasSkill ? m.skilledDetectionPerDay : m.detectionPerDay;
            var reqs = m.requires || {};

            // Check if player has materials
            var canAfford = Player.gold >= cost;
            var missingItems = [];
            for (var resId in reqs) {
                var have = (Player.inventory && Player.inventory[resId]) || 0;
                var need = reqs[resId];
                if (have < need) {
                    var res = typeof RESOURCE_TYPES !== 'undefined' ? Object.values(RESOURCE_TYPES).find(function(r) { return r.id === resId; }) : null;
                    missingItems.push((res ? res.name : resId) + ' (' + have + '/' + need + ')');
                }
            }
            var canDo = canAfford && missingItems.length === 0;

            // Build material list
            var matList = [];
            for (var resId2 in reqs) {
                var res2 = typeof RESOURCE_TYPES !== 'undefined' ? Object.values(RESOURCE_TYPES).find(function(r) { return r.id === resId2; }) : null;
                var icon2 = res2 ? res2.icon : '📦';
                var name2 = res2 ? res2.name : resId2;
                var have2 = (Player.inventory && Player.inventory[resId2]) || 0;
                var need2 = reqs[resId2];
                var color2 = have2 >= need2 ? '#7bed9f' : '#ff6b6b';
                matList.push(icon2 + ' ' + name2 + ': <span style="color:' + color2 + '">' + have2 + '/' + need2 + '</span>');
            }

            var detectPct = Math.round(detect * 100);
            var borderColor = canDo ? 'rgba(200,170,80,0.4)' : 'rgba(100,100,100,0.3)';
            var bgColor = canDo ? 'rgba(200,170,80,0.08)' : 'rgba(50,50,50,0.1)';

            html += '<div style="padding:10px;border:1px solid ' + borderColor + ';border-radius:6px;background:' + bgColor + ';">';
            html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
            html += '<strong>' + m.icon + ' ' + m.name + '</strong>';
            html += '<span style="font-size:0.75rem;color:#aaa;">⏱ ' + days + ' days · 🔍 ' + detectPct + '%/day</span>';
            html += '</div>';
            html += '<div style="font-size:0.78rem;color:#bbb;margin:4px 0;">' + m.description + '</div>';
            html += '<div style="font-size:0.75rem;margin:4px 0;">' + matList.join(' · ') + '</div>';

            if (missingItems.length > 0) {
                html += '<div style="font-size:0.72rem;color:#ff6b6b;margin:2px 0;">❌ Missing: ' + missingItems.join(', ') + '</div>';
            }
            if (!canAfford) {
                html += '<div style="font-size:0.72rem;color:#ff6b6b;">❌ Need ' + cost + 'g (have ' + Math.floor(Player.gold) + 'g)</div>';
            }

            html += '<div style="margin-top:6px;text-align:right;">';
            if (canDo) {
                html += '<button class="btn-medieval" onclick="(function(){var r=Player.playerDestroyBridge(' + roadIdx + ',\'' + key + '\');UI.toast(r.message,r.success?\'success\':\'warning\');if(r.success)UI.closeModal();})()" style="font-size:0.8rem;padding:5px 14px;background:rgba(200,60,50,0.35);border-color:rgba(200,60,50,0.6);color:#f0d0a0;">💣 Begin Sabotage</button>';
            } else {
                html += '<button class="btn-medieval" disabled style="font-size:0.8rem;padding:5px 14px;opacity:0.4;cursor:not-allowed;">💣 Cannot Begin</button>';
            }
            html += '</div></div>';
        }
        html += '</div>';

        html += '<div style="margin-top:12px;padding:8px;background:rgba(200,60,50,0.1);border-radius:4px;border:1px solid rgba(200,60,50,0.3);">';
        html += '<div style="font-size:0.75rem;color:#ff8866;">⚠️ <strong>Warning:</strong> Bridge sabotage is a serious crime. If caught, you face a <strong>' + (CONFIG.BRIDGE_DESTROY_CAUGHT_FINE || 2000) + 'g fine</strong>, <strong>' + (CONFIG.BRIDGE_DESTROY_CAUGHT_JAIL_DAYS || 30) + ' days jail</strong>, and <strong>reputation loss in ALL kingdoms</strong>. You must stay in the area during sabotage.</div>';
        html += '</div>';

        openModal('💣 Destroy Bridge — ' + bridgeName, html);
    }

    function buyShipUI(type) {
        try {
            const result = Player.buyShip(type);
            if (result && result.success) {
                toast(result.message, 'success');
                openCharacterDialog(); // refresh
            } else {
                toast((result && result.message) || 'Cannot buy ship', 'warning');
            }
        } catch (e) {
            toast(e.message || 'Cannot buy ship', 'danger');
        }
    }

    function showShipAddons(shipId) {
        var ship = Player.ships ? Player.ships.find(function(s) { return s.id === shipId; }) : null;
        if (!ship) { toast('Ship not found', 'warning'); return; }
        var addons = CONFIG.SHIP_ADDONS || {};
        var html = '<div style="padding:12px;"><h3>🔧 Install Addon on ' + ship.name + '</h3>';
        html += '<div style="font-size:0.8rem;color:#b0b0b0;margin-bottom:8px;">Slots: ' + (ship.addons ? ship.addons.length : 0) + '/' + (ship.maxAddons || 0) + '</div>';
        for (var addonId in addons) {
            var addon = addons[addonId];
            var alreadyHas = ship.addons && ship.addons.indexOf(addonId) >= 0;
            var matList = [];
            var addonCost = 50;
            for (var mat in (addon.materials || {})) {
                var price = Engine.getResourcePrice ? Engine.getResourcePrice(Player.townId, mat) : 10;
                addonCost += (addon.materials[mat] || 0) * price;
                matList.push(mat + ':' + addon.materials[mat]);
            }
            html += '<div style="border:1px solid var(--border);padding:6px;margin-bottom:4px;border-radius:4px;">';
            html += '<div><strong>' + addon.name + '</strong> - ' + addon.description + '</div>';
            html += '<div style="font-size:0.75rem;color:#888;">Materials: ' + matList.join(', ') + ' | Cost: ' + addonCost + 'g</div>';
            if (alreadyHas) {
                html += '<div style="font-size:0.75rem;color:#55a868;">✅ Installed</div>';
            } else {
                html += '<button class="btn-trade buy" style="font-size:0.7rem;margin-top:2px;" onclick="UI.installShipAddon(\'' + shipId + '\',\'' + addonId + '\')">Install</button>';
            }
            html += '</div>';
        }
        html += '</div>';
        openModal('Ship Addons', html);
    }

    function installShipAddonUI(shipId, addonId) {
        try {
            var result = Player.installShipAddon(shipId, addonId);
            if (result && result.success) {
                toast(result.message, 'success');
                showShipAddons(shipId); // refresh
            } else {
                toast((result && result.message) || 'Cannot install addon', 'warning');
            }
        } catch (e) {
            toast(e.message || 'Cannot install addon', 'danger');
        }
    }

    function clickTown(townId) {
        let town;
        try { town = Engine.getTown(townId); } catch (e) { /* no-op */ }
        if (!town) {
            const towns = Engine.getTowns();
            town = towns ? towns.find(t => t.id === townId) : null;
        }
        if (town) {
            closeModal(); // close any modal that spawned this FIRST
            if (typeof Renderer !== 'undefined') {
                Renderer.panTo(town.x, town.y);
            }
            showTownDetail(town); // then open town detail
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  UTILITY
    // ═══════════════════════════════════════════════════════════

    function formatGold(n) {
        if (n >= 10000) return (n / 1000).toFixed(1) + 'k';
        return Math.floor(n).toLocaleString();
    }

    function capitalize(s) {
        return s.charAt(0).toUpperCase() + s.slice(1);
    }

    function formatStrategy(s) {
        if (!s) return '—';
        return s.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
    }

    function findResource(id) {
        for (const key in RESOURCE_TYPES) {
            if (RESOURCE_TYPES[key].id === id) return RESOURCE_TYPES[key];
        }
        return null;
    }

    function findBuildingType(id) {
        for (const key in BUILDING_TYPES) {
            if (BUILDING_TYPES[key].id === id) return BUILDING_TYPES[key];
        }
        return null;
    }

    // ═══════════════════════════════════════════════════════════
    //  PUBLIC API
    // ═══════════════════════════════════════════════════════════

    // ── KINGDOMS PAGE ──

    function showKingdomTowns(kingdomId) {
        var kingdom = Engine.findKingdom(kingdomId);
        if (!kingdom) { toast('Kingdom not found.', 'error'); return; }
        var allTowns = Engine.getTowns();
        var towns = allTowns.filter(function(t) { return t.kingdomId === kingdomId; });
        var roads = [];
        var seaRoutes = [];
        try { roads = Engine.getRoads(); } catch(e) {}
        try { seaRoutes = Engine.getSeaRoutes(); } catch(e) {}

        var html = '<div style="margin-bottom:10px;">';
        html += '<button class="btn-medieval" data-action="openKingdomsDialog" style="font-size:0.8rem;padding:4px 12px;">← Back to Kingdoms</button>';
        html += ' <span style="font-size:0.9rem;color:' + (kingdom.color || '#ccc') + ';font-weight:bold;margin-left:8px;">' + kingdom.name + ' — ' + towns.length + ' towns</span>';
        html += '</div>';

        html += '<div style="display:flex;flex-direction:column;gap:8px;max-height:60vh;overflow-y:auto;">';
        for (var ti = 0; ti < towns.length; ti++) {
            var town = towns[ti];
            var pop = town.population || 0;
            var prosp = Math.round(town.prosperity || 0);
            var cat = town.category || 'village';
            var catLabel = cat.charAt(0).toUpperCase() + cat.slice(1).replace('_', ' ');

            // Road connections
            var connNames = [];
            for (var ri = 0; ri < roads.length; ri++) {
                var rd = roads[ri];
                if (rd.fromTownId === town.id || rd.toTownId === town.id) {
                    var otherId = rd.fromTownId === town.id ? rd.toTownId : rd.fromTownId;
                    var other = Engine.findTown(otherId);
                    if (other) connNames.push(other.name);
                }
            }
            // Sea connections
            var seaNames = [];
            for (var si = 0; si < seaRoutes.length; si++) {
                var sr = seaRoutes[si];
                if (sr.fromTownId === town.id || sr.toTownId === town.id) {
                    var seaOtherId = sr.fromTownId === town.id ? sr.toTownId : sr.fromTownId;
                    var seaOther = Engine.findTown(seaOtherId);
                    if (seaOther) seaNames.push(seaOther.name);
                }
            }

            // Key buildings (unique types, max 6)
            var bldNames = [];
            var seenBld = {};
            for (var bi = 0; bi < (town.buildings || []).length; bi++) {
                var bt = Engine.findBuildingType(town.buildings[bi].type);
                var bName = bt ? bt.name : town.buildings[bi].type;
                if (!seenBld[bName]) { seenBld[bName] = true; bldNames.push(bName); }
                if (bldNames.length >= 6) break;
            }

            // Security and happiness
            var security = Math.round(town.security || 0);
            var happiness = Math.round(town.happiness || 50);

            // Is player here?
            var isHere = typeof Player !== 'undefined' && Player.townId === town.id;

            html += '<div style="border:1px solid var(--border);border-radius:6px;padding:10px;' + (isHere ? 'border-left:3px solid #55a868;' : '') + '">';
            html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
            html += '<strong style="font-size:0.95rem;">' + town.name + '</strong>';
            html += '<span style="font-size:0.8rem;color:var(--text-muted);">' + catLabel + '</span>';
            html += '</div>';
            html += '<div style="display:flex;flex-wrap:wrap;gap:10px;font-size:0.82rem;margin:4px 0;color:var(--text-muted);">';
            html += '<span>👥 ' + pop + '</span>';
            html += '<span>📊 ' + prosp + '%</span>';
            html += '<span>🛡️ ' + security + '</span>';
            html += '<span>😊 ' + happiness + '</span>';
            if (town.isPort) html += '<span>🚢 Port</span>';
            if (town.isIsland) html += '<span>🏝️ Island</span>';
            if (isHere) html += '<span style="color:#55a868;font-weight:bold;">📍 You are here</span>';
            html += '</div>';
            if (connNames.length > 0) html += '<div style="font-size:0.78rem;color:var(--text-muted);">🛤️ Roads: ' + connNames.join(', ') + '</div>';
            if (seaNames.length > 0) html += '<div style="font-size:0.78rem;color:var(--text-muted);">⚓ Sea: ' + seaNames.join(', ') + '</div>';
            if (bldNames.length > 0) html += '<div style="font-size:0.78rem;color:var(--text-muted);">🏗️ ' + bldNames.join(', ') + (Object.keys(seenBld).length < (town.buildings || []).length ? '…' : '') + '</div>';
            html += '</div>';
        }
        html += '</div>';

        openModal('🏘️ ' + kingdom.name + ' — Towns', html);
    }

    // ═══════════════════════════════════════════════════════════
    //  SUCCESSION ELECTION VOTING UI
    // ═══════════════════════════════════════════════════════════

    var _electionShown = {};

    function _checkPendingElection() {
        if (typeof Player === 'undefined' || typeof Engine === 'undefined') return;
        var playerKingdomId = Player.citizenshipKingdomId || Player.kingdomId;
        if (!playerKingdomId) return;
        try {
            var election = Engine.getPendingElection(playerKingdomId);
            if (!election) { _electionShown[playerKingdomId] = false; return; }
            if (_electionShown[playerKingdomId]) return; // already shown this election
            _electionShown[playerKingdomId] = true;
            // Small delay so toast renders first
            setTimeout(function() { showElectionVotingModal(playerKingdomId, election); }, 500);
        } catch (e) { /* engine not ready */ }
    }

    function showElectionVotingModal(kingdomId, election) {
        if (!election || !election.candidates) return;
        var kingdom = Engine.getKingdom ? Engine.getKingdom(kingdomId) : Engine.findKingdom(kingdomId);
        var kName = kingdom ? kingdom.name : 'the Kingdom';
        var daysLeft = Math.max(0, 30 - (Engine.getDay() - election.startDay));

        var html = '';
        html += '<div style="text-align:center;margin-bottom:12px;">';
        html += '<div style="font-size:1.1rem;color:#ffd700;margin-bottom:4px;">👑 Succession Election</div>';
        html += '<div style="font-size:0.85rem;color:#ccc;">' + election.deadKingName + ' has died with no heir.</div>';
        html += '<div style="font-size:0.8rem;color:#aaa;">The Royal Council of ' + kName + ' must elect a new ruler.</div>';
        html += '<div style="font-size:0.75rem;color:#888;margin-top:4px;">⏳ ' + daysLeft + ' days until auto-resolution</div>';
        html += '</div>';

        html += '<div style="display:grid;gap:8px;max-height:400px;overflow-y:auto;padding:4px;">';
        // Sort: player first, then by score descending
        var sorted = election.candidates.slice().sort(function(a, b) {
            if (a.isPlayer) return -1;
            if (b.isPlayer) return 1;
            return b.score - a.score;
        });
        for (var i = 0; i < sorted.length; i++) {
            var c = sorted[i];
            var borderColor = c.isPlayer ? 'rgba(100,200,255,0.6)' : 'rgba(180,160,120,0.4)';
            var bgColor = c.isPlayer ? 'rgba(100,200,255,0.08)' : 'rgba(40,35,25,0.6)';
            var youTag = c.isPlayer ? ' <span style="color:#4dc8ff;font-size:0.7rem;">(YOU)</span>' : '';
            html += '<div style="background:' + bgColor + ';border:1px solid ' + borderColor + ';border-radius:6px;padding:10px 12px;cursor:pointer;transition:background 0.15s;" ';
            html += 'onmouseover="this.style.background=\'rgba(255,215,0,0.12)\'" onmouseout="this.style.background=\'' + bgColor + '\'" ';
            html += 'onclick="UI._castElectionVote(\'' + kingdomId + '\',\'' + c.id + '\',\'' + c.name.replace(/'/g, "\\'") + '\')">';
            html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
            html += '<div>';
            html += '<div style="font-size:0.95rem;color:#e8d5a3;font-weight:bold;">' + c.name + youTag + '</div>';
            html += '<div style="font-size:0.75rem;color:#aaa;">' + (c.occupation.charAt(0).toUpperCase() + c.occupation.slice(1)) + ', Age ' + c.age + '</div>';
            html += '</div>';
            html += '<div style="text-align:right;">';
            html += '<div style="font-size:0.8rem;color:#ffd700;">💰 ' + Math.round(c.gold).toLocaleString() + 'g</div>';
            html += '</div>';
            html += '</div>';
            // Stats bar
            html += '<div style="display:flex;gap:12px;margin-top:6px;font-size:0.7rem;color:#999;">';
            html += '<span>🧠 Int: ' + c.intelligence + '</span>';
            html += '<span>⚔️ Ambition: ' + c.ambition + '</span>';
            html += '<span>👥 Charisma: ' + c.charisma + '</span>';
            html += '</div>';
            html += '</div>';
        }
        html += '</div>';

        html += '<div style="text-align:center;margin-top:10px;font-size:0.75rem;color:#888;">';
        html += 'Click a candidate to cast your vote. Your endorsement carries great weight as Royal Advisor.';
        html += '</div>';

        var footer = '<button class="btn-medieval" data-action="closeModal" style="font-size:0.8rem;padding:5px 18px;opacity:0.6;">Abstain (Let Others Decide)</button>';

        openModal('👑 Royal Election — ' + kName, html, footer);
    }

    function _castElectionVote(kingdomId, candidateId, candidateName) {
        var result = Engine.castElectionVote(kingdomId, candidateId);
        closeModal();
        if (result && result.success) {
            toast('👑 You cast your vote for ' + candidateName + '. The council deliberates...', 'success', 'critical');
        } else {
            toast('Election has already been resolved.', 'warning');
        }
        _electionShown[kingdomId] = false;
    }

    function openKingdomsDialog() {
        let kingdoms;
        try { kingdoms = Engine.getKingdoms(); } catch (e) { kingdoms = []; }
        if (!kingdoms || kingdoms.length === 0) {
            toast('No kingdoms to display.', 'warning');
            return;
        }

        // Kingdom cards
        let cardsHtml = '<div class="kingdom-cards">';
        for (const k of kingdoms) {
            const king = k.king ? Engine.findPerson(k.king) : null;
            const kingName = king ? king.firstName + ' ' + king.lastName : 'Unknown';
            const numTowns = k.territories ? k.territories.length : 0;
            const prosperityPct = Math.max(0, Math.min(100, k.prosperity || 0));
            const wealthLabel = k.gold > 10000 ? '💰 Wealthy' : k.gold > 5000 ? '💰 Moderate' : '💰 Poor';
            const isHome = typeof Player !== 'undefined' && Player.isPlayerCitizenOf ? Player.isPlayerCitizenOf(k.id) : (typeof Player !== 'undefined' && Player.citizenshipKingdomId ? k.id === Player.citizenshipKingdomId : false);
            const rep = (typeof Player !== 'undefined' && Player.reputation) ? (Player.reputation[k.id] || 0) : 0;
            const rankIdx = (typeof Player !== 'undefined' && Player.socialRank) ? (Player.socialRank[k.id] || 0) : 0;
            const rank = CONFIG.SOCIAL_RANKS[rankIdx] || CONFIG.SOCIAL_RANKS[0];

            // Foreign noble status for non-home kingdoms
            var foreignNobleStatus = '';
            if (!isHome && typeof Player !== 'undefined' && Player.getForeignNobleStatus) {
                var fns = Player.getForeignNobleStatus(k.id);
                if (fns === 'foreign_minor_noble') foreignNobleStatus = '<span style="color:#8ba;font-size:0.75rem;"> (Foreign Minor Noble)</span>';
                else if (fns === 'foreign_noble') foreignNobleStatus = '<span style="color:#8ba;font-size:0.75rem;"> (Foreign Noble)</span>';
                else if (fns === 'enemy_minor_noble') foreignNobleStatus = '<span style="color:#c44e52;font-size:0.75rem;"> (Enemy Minor Noble)</span>';
                else if (fns === 'enemy_noble') foreignNobleStatus = '<span style="color:#c44e52;font-size:0.75rem;"> (Enemy Noble)</span>';
            }

            // Laws
            let lawsHtml = '';
            if (k.laws) {
                if (k.laws.bannedGoods && k.laws.bannedGoods.length > 0) {
                    const banned = k.laws.bannedGoods.map(g => {
                        const res = Object.values(RESOURCE_TYPES).find(r => r.id === g);
                        return res ? res.icon + ' ' + res.name : g;
                    }).join(', ');
                    lawsHtml += `<div class="law-item" style="cursor:help;" title="Banned items are illegal to make or sell, but legal to buy or own in small amounts.">🚫 Banned: ${banned}</div>`;
                }
                lawsHtml += `<div class="law-item">💸 Tariff: ${Math.round((k.laws.tradeTariff || 0) * 100)}%</div>`;
                if (k.laws.conscription) lawsHtml += `<div class="law-item">⚔️ Conscription Active</div>`;
                if (k.laws.guildRestrictions) lawsHtml += `<div class="law-item">🔨 Guild Restrictions</div>`;
            }

            const warList = k.atWar && k.atWar.length > 0 ? k.atWar.map(wId => {
                const wk = kingdoms.find(kk => kk.id === wId);
                return wk ? wk.name : wId;
            }).join(', ') : '';

            // Goods taxes
            let goodsTaxHtml = '';
            if (k.laws && k.laws.goodsTaxes) {
                const taxEntries = Object.entries(k.laws.goodsTaxes);
                if (taxEntries.length > 0) {
                    const taxNames = taxEntries.map(([g, rate]) => {
                        const r = Object.values(RESOURCE_TYPES).find(rr => rr.id === g);
                        return `${r ? r.icon : ''} ${r ? r.name : g} (${Math.round(rate * 100)}%)`;
                    }).join(', ');
                    goodsTaxHtml = `<div class="law-item">💸 Goods Taxes: ${taxNames}</div>`;
                }
            }

            // Restricted goods
            let restrictedHtml = '';
            if (k.laws && k.laws.restrictedGoods && k.laws.restrictedGoods.length > 0) {
                const rNames = k.laws.restrictedGoods.map(g => {
                    const r = Object.values(RESOURCE_TYPES).find(rr => rr.id === g);
                    const hasLic = Player.hasLicense(k.id, g);
                    return `${r ? r.icon : ''} ${r ? r.name : g} ${hasLic ? '✅' : '🔒'}`;
                }).join(', ');
                restrictedHtml = `<div class="law-item" style="cursor:help;" title="Legal to buy. Illegal to sell or produce without a license. Purchase a license from the Kingdom menu.">🔒 Restricted: ${rNames}</div>`;
            }

            // Player licenses in this kingdom
            let playerLicHtml = '';
            const myLicenses = Player.licenses[k.id] || [];
            if (myLicenses.length > 0) {
                const licNames = myLicenses.map(g => {
                    var resId = typeof g === 'string' ? g : g.resourceId;
                    const r = Object.values(RESOURCE_TYPES).find(rr => rr.id === resId);
                    return r ? r.icon + ' ' + r.name : resId;
                }).join(', ');
                playerLicHtml = `<div class="kc-row" style="font-size:0.75rem;color:#55a868;">📜 Your Licenses: ${licNames}</div>`;
            }
            // Buy licenses button — show if kingdom has restricted goods with unlicensed items
            let licenseBtnHtml = '';
            if (k.laws && k.laws.restrictedGoods && k.laws.restrictedGoods.length > 0) {
                var _unlicensed = k.laws.restrictedGoods.filter(function(g) { return !Player.hasLicense(k.id, g); });
                if (_unlicensed.length > 0) {
                    licenseBtnHtml = '<div class="kc-row"><button class="btn-medieval" onclick="UI.openKingdomLicenses(\'' + k.id + '\')" style="font-size:0.75rem;padding:4px 12px;color:#e8dcc8;background:rgba(180,140,50,0.2);border-color:rgba(180,140,50,0.4);">📜 Buy Licenses (' + _unlicensed.length + ' available)</button></div>';
                }
            }

            // Guard strength indicator
            let guardIcons = '';
            const kTowns = Engine.getTowns().filter(t => t.kingdomId === k.id);
            const avgSecurity = kTowns.length > 0 ? kTowns.reduce((s, t) => s + (t.security || 0), 0) / kTowns.length : 0;
            const guardLevel = avgSecurity > 70 ? '🛡️🛡️🛡️' : avgSecurity > 40 ? '🛡️🛡️' : avgSecurity > 15 ? '🛡️' : '⚠️';

            // War and alliance status
            var warStatusHtml = '';
            if (k.atWar && Array.isArray(k.atWar) && k.atWar.length > 0) {
                warStatusHtml = '<div class="kc-row" style="color:var(--danger);font-weight:bold;">⚔️ At War with: ' + warList + '</div>';
            } else {
                warStatusHtml = '<div class="kc-row" style="color:#55a868;">☮️ At Peace</div>';
            }

            var allianceHtml = '';
            var allies = k.alliances || [];
            if (allies.length > 0) {
                var allyNames = allies.map(function(aId) {
                    var ak = kingdoms.find(function(kk) { return kk.id === aId; });
                    var aType = (k.allianceMeta && k.allianceMeta[aId]) ? k.allianceMeta[aId].type : '';
                    var typeLabel = aType === 'offensive' ? '⚔' : aType === 'defensive' ? '🛡' : '';
                    return (ak ? ak.name : aId) + (typeLabel ? ' ' + typeLabel : '');
                }).join(', ');
                allianceHtml = '<div class="kc-row" style="color:#5dade2;">🤝 Allies: ' + allyNames + '</div>';
            } else {
                allianceHtml = '<div class="kc-row" style="color:#888;">🤝 No Alliances</div>';
            }

            cardsHtml += `<div class="kingdom-card ${isHome ? 'kingdom-home' : ''}" style="border-left: 4px solid ${k.color};">
                <div class="kc-header" style="color:${k.color};">${k.name}</div>
                <div class="kc-row">👑 King: ${kingName}</div>
                <div class="kc-row">🏘️ Towns: ${numTowns}</div>
                <div class="kc-row">📊 Prosperity: <span class="mini-bar"><span class="mini-fill" style="width:${prosperityPct}%;background:${k.color};"></span></span></div>
                <div class="kc-row">⚔️ Military: ${k.militaryStrength || 0}</div>
                <div class="kc-row">${wealthLabel}</div>
                <div class="kc-row" style="font-size:0.85rem;font-weight:bold;color:var(--gold);">📜 Tax: ${Math.round((k.taxRate || 0.1) * 100)}%</div>
                <div class="kc-row">Guard Strength: ${guardLevel}</div>
                ${warStatusHtml}
                ${allianceHtml}
                ${goodsTaxHtml}
                ${restrictedHtml}
                ${lawsHtml ? `<div class="kc-laws">${lawsHtml}</div>` : ''}
                ${playerLicHtml}
                ${licenseBtnHtml}
                ${isHome ? '<div class="kc-home-badge">★ YOUR HOME</div>' : ''}
                <div class="kc-row" style="margin-top:4px;font-size:0.8rem;">
                    <span style="color:#aaa;">Status:</span> ${rank.icon} <span style="color:#d4af37;">${rank.name}</span>${foreignNobleStatus}
                </div>
                <div style="margin-top:2px;">
                    <div style="display:flex;justify-content:space-between;font-size:0.75rem;margin-bottom:2px;">
                        <span style="color:#aaa;">Reputation:</span>
                        <span style="color:${rep >= 70 ? '#55a868' : rep >= 40 ? '#ccb974' : '#c44e52'};">${Math.floor(rep)}/100</span>
                    </div>
                    <div style="background:rgba(0,0,0,0.4);border:1px solid #444;border-radius:3px;height:8px;">
                        <div style="height:100%;width:${Math.max(0, Math.min(100, rep))}%;background:${k.color || '#ccb974'};border-radius:2px;transition:width 0.3s;"></div>
                    </div>
                </div>
                <div class="kc-buttons" style="display:flex;gap:4px;flex-wrap:wrap;margin-top:6px;">
                    <button class="kc-btn" data-action="towns" data-kid="${k.id}" title="View Towns">🏘️ Towns</button>
                    <button class="kc-btn" data-action="laws" data-kid="${k.id}" title="View Laws">📜 Laws</button>
                    <button class="kc-btn" data-action="trade" data-kid="${k.id}" title="Trade Routes">🏛️ Trade</button>
                    ${isHome ? '<button class="kc-btn" data-action="orders" data-kid="' + k.id + '" title="Kingdom Orders">📋 Orders</button>' : ''}
                    <button class="kc-btn" data-action="commissions" data-kid="${k.id}" title="Royal Commissions">📦 Commissions</button>
                    ${isHome ? '<button class="kc-btn" data-action="petition" data-kid="' + k.id + '" title="Submit Petition">📝 Petition</button>' : ''}
                    <button class="kc-btn" data-action="donate" data-kid="${k.id}" title="Donate Gold">💰 Donate</button>
                </div>
            </div>`;
        }
        cardsHtml += '</div>';

        // Diplomacy matrix
        let matrixHtml = '<div class="diplo-matrix"><table class="diplo-table"><tr><th></th>';
        for (const k of kingdoms) {
            matrixHtml += `<th style="color:${k.color};">${k.name.slice(0, 4)}</th>`;
        }
        matrixHtml += '</tr>';
        for (const ki of kingdoms) {
            matrixHtml += `<tr><td style="color:${ki.color};">${ki.name.slice(0, 4)}</td>`;
            for (const kj of kingdoms) {
                if (ki.id === kj.id) {
                    matrixHtml += '<td>──</td>';
                } else {
                    const rel = ki.relations[kj.id] || 0;
                    const atWar = ki.atWar && ki.atWar.includes(kj.id);
                    let emoji, cls;
                    if (atWar) { emoji = '💀'; cls = 'diplo-war'; }
                    else if (rel > 60) { emoji = '😊'; cls = 'diplo-ally'; }
                    else if (rel < -30) { emoji = '😡'; cls = 'diplo-hostile'; }
                    else { emoji = '😐'; cls = 'diplo-neutral'; }
                    matrixHtml += `<td class="${cls}" title="${ki.name}→${kj.name}: ${rel}">${emoji}</td>`;
                }
            }
            matrixHtml += '</tr>';
        }
        matrixHtml += '</table></div>';

        // Your Status summary
        const citizenK = Player.citizenshipKingdomId ? kingdoms.find(k => k.id === Player.citizenshipKingdomId) : null;
        const citizenName = citizenK ? citizenK.name : 'Stateless';
        const citizenColor = citizenK ? citizenK.color : '#888';
        const rankIdx = Player.citizenshipKingdomId ? (Player.socialRank[Player.citizenshipKingdomId] || 0) : 0;
        const rank = CONFIG.SOCIAL_RANKS[rankIdx] || CONFIG.SOCIAL_RANKS[0];

        // Count kingdoms where player is citizen
        let citizenCountHtml = '';
        const citizenKingdomsList = [];
        if (Player.socialRank) {
            for (const kId in Player.socialRank) {
                if ((Player.socialRank[kId] || 0) >= 1) {
                    const ck = kingdoms.find(function(x) { return x.id === kId; });
                    citizenKingdomsList.push(ck ? ck.name : kId);
                }
            }
        }
        if (citizenKingdomsList.length > 1) {
            citizenCountHtml = `<div class="detail-row"><span class="label">All Citizenships</span>
                <span class="value">${citizenKingdomsList.join(', ')}</span></div>`;
        }

        let statusHtml = `<div class="your-status">
            <h3>Your Status</h3>
            <div class="detail-row"><span class="label">Primary Kingdom</span>
                <span class="value" style="color:${citizenColor};">${citizenName}</span></div>
            ${citizenCountHtml}
            <div class="detail-row"><span class="label">Rank</span>
                <span class="value">${rank.icon} ${rank.name} (${rankIdx + 1}/7)</span></div>`;

        // Jailed?
        if (Player.jailedUntilDay > 0 && Engine.getDay() < Player.jailedUntilDay) {
            statusHtml += `<div class="detail-row" style="color:var(--danger);"><span class="label">⛓️ Jailed</span>
                <span class="value">Until day ${Player.jailedUntilDay}</span></div>`;
        }
        if (Player.smugglingSkill > 0) {
            statusHtml += `<div class="detail-row"><span class="label">🗡️ Smuggling Skill</span>
                <span class="value">${Player.smugglingSkill}</span></div>`;
        }
        statusHtml += '</div>';

        const html = cardsHtml + matrixHtml + statusHtml;
        openModal('👑 Kingdoms of the Realm', html);

        // Attach kingdom card button handlers
        var kcBtns = document.querySelectorAll('.kc-btn');
        for (var bi = 0; bi < kcBtns.length; bi++) {
            kcBtns[bi].addEventListener('click', function(e) {
                var action = this.getAttribute('data-action');
                var kid = this.getAttribute('data-kid');
                if (action === 'towns') showKingdomTowns(kid);
                else if (action === 'laws') UI.openKingdomLawsPanel(kid);
                else if (action === 'trade') UI.showKingdomTradePanel(kid);
                else if (action === 'orders') UI.showKingdomOrdersPanel(kid);
                else if (action === 'commissions') UI.openRoyalCommissionsPanel(kid);
                else if (action === 'petition') UI.showPetitionsPanel();
                else if (action === 'donate') UI.openKingdomDonateDialog(kid);
            });
        }
    }

    // ── SOCIAL STATUS PAGE (in character dialog) ──

    function buildSocialStatusHtml() {
        const citizenKId = Player.citizenshipKingdomId;
        let kingdoms;
        try { kingdoms = Engine.getKingdoms(); } catch (e) { kingdoms = []; }
        const citizenK = citizenKId ? kingdoms.find(k => k.id === citizenKId) : null;
        const citizenName = citizenK ? citizenK.name : 'Stateless';
        const citizenColor = citizenK ? citizenK.color : '#888';
        const rankIdx = citizenKId ? (Player.socialRank[citizenKId] || 0) : 0;
        const rank = CONFIG.SOCIAL_RANKS[rankIdx] || CONFIG.SOCIAL_RANKS[0];

        let html = `<div class="detail-section">
            <h3>\uD83C\uDFDB\uFE0F Social Status</h3>
            <div class="detail-row"><span class="label">Primary Kingdom</span>
                <span class="value" style="color:${citizenColor};">${citizenName}</span></div>
            <div class="detail-row"><span class="label">Primary Rank</span>
                <span class="value">${rank.icon} ${rank.name}</span></div>
        </div>`;

        // All kingdoms where player holds rank
        const citizenKingdoms = [];
        if (Player.socialRank) {
            for (const kId in Player.socialRank) {
                if ((Player.socialRank[kId] || 0) >= 1) {
                    const k = kingdoms.find(function(x) { return x.id === kId; });
                    citizenKingdoms.push({ id: kId, name: k ? k.name : kId, color: k ? k.color : '#888', rankIdx: Player.socialRank[kId] });
                }
            }
        }
        if (citizenKingdoms.length > 0) {
            html += '<div class="detail-section"><h3>\uD83C\uDFE0 Citizenships</h3>';
            for (const ck of citizenKingdoms) {
                const r = CONFIG.SOCIAL_RANKS[ck.rankIdx] || CONFIG.SOCIAL_RANKS[0];
                html += `<div class="detail-row" style="margin-bottom:4px;">
                    <span class="label" style="color:${ck.color};">${ck.name}</span>
                    <span class="value">${r.icon} ${r.name}
                        <button class="btn-medieval" onclick="UI.showRankProgressionPanel('${ck.id}')" style="font-size:0.7rem;padding:2px 8px;margin-left:6px;">Details</button>
                        <button class="btn-medieval" onclick="UI.renounceKingdomUI('${ck.id}')" style="font-size:0.7rem;padding:2px 8px;margin-left:4px;background:rgba(200,60,50,0.35);border-color:rgba(200,60,50,0.6);color:#f0d0a0;">\u274C Renounce</button>
                    </span>
                </div>`;
            }
            html += '</div>';
        }

        // Rank ladder for primary kingdom
        html += '<div class="detail-section"><h3>\uD83D\uDCCA Rank Ladder</h3><div class="rank-ladder">';
        for (let i = 0; i < CONFIG.SOCIAL_RANKS.length; i++) {
            const r = CONFIG.SOCIAL_RANKS[i];
            const isCurrent = i === rankIdx;
            const isAchieved = i <= rankIdx;
            html += `<div class="rank-step ${isCurrent ? 'rank-current' : ''} ${isAchieved ? 'rank-achieved' : 'rank-locked'}">
                <span class="rank-icon">${r.icon}</span>
                <span class="rank-name">${r.name}</span>
                <span class="rank-perks">\uD83D\uDC65${r.maxWorkers > 999 ? '\u221E' : r.maxWorkers} \uD83C\uDFE0${r.maxBuildings > 999 ? '\u221E' : r.maxBuildings}</span>
                ${!isAchieved ? `<span class="rank-req">${r.goldReq.toLocaleString()}g, ${r.repReq}rep</span>` : ''}
            </div>`;
        }
        html += '</div></div>';

        // Next rank progress
        if (citizenKId && rankIdx < CONFIG.SOCIAL_RANKS.length - 1) {
            const nextRank = CONFIG.SOCIAL_RANKS[rankIdx + 1];
            const goldEarned = (Player.goldEarnedInKingdom && Player.goldEarnedInKingdom[citizenKId]) || 0;
            const rep = (Player.reputation && Player.reputation[citizenKId]) || 0;
            const goldPct = nextRank.goldReq > 0 ? Math.min(100, Math.floor((goldEarned / nextRank.goldReq) * 100)) : 100;
            const repPct = nextRank.repReq > 0 ? Math.min(100, Math.floor((rep / nextRank.repReq) * 100)) : 100;

            // Check detailed requirements
            let reqChecklist = '';
            let _canPetition = false;
            if (Player.canPetitionForPromotion) {
                const check = Player.canPetitionForPromotion(citizenKId);
                if (check.reasons && check.reasons.length > 0) {
                    reqChecklist = '<div style="margin-top:8px;font-size:0.8rem;">';
                    for (const r of check.reasons) {
                        reqChecklist += `<div style="color:#ff8866;">\u274C ${r}</div>`;
                    }
                    reqChecklist += '</div>';
                } else if (check.can) {
                    _canPetition = true;
                    reqChecklist = '<div style="margin-top:8px;font-size:0.8rem;color:#66ff88;">\u2705 All requirements met!</div>';
                }
            }

            var _petBtnStyle = _canPetition
                ? 'margin-top:8px;font-size:0.85rem;padding:6px 16px;background:linear-gradient(180deg,#5aad35,#3a7a24);border-color:#5aad35;color:#fff;animation:petitionGlow 1.5s ease-in-out infinite;'
                : 'margin-top:8px;font-size:0.85rem;padding:6px 16px;';

            html += `<div class="detail-section"><h3>Next: ${nextRank.icon} ${nextRank.name}</h3>
                <div class="progress-row"><span class="label">Gold Earned</span>
                    <div class="progress-bar"><div class="progress-fill" style="width:${goldPct}%"></div></div>
                    <span class="value">${Math.floor(goldEarned).toLocaleString()}/${nextRank.goldReq.toLocaleString()}</span></div>
                <div class="progress-row"><span class="label">Kingdom Reputation</span>
                    <div class="progress-bar"><div class="progress-fill" style="width:${repPct}%"></div></div>
                    <span class="value">${Math.floor(rep)}/${nextRank.repReq}</span></div>
                ${nextRank.fee ? `<div class="detail-row"><span class="label">Fee</span><span class="value">${nextRank.fee.toLocaleString()}g</span></div>` : ''}
                ${nextRank.extraReq ? `<div class="detail-row"><span class="label">Requirements</span><span class="value" style="font-size:0.8rem;">${nextRank.extraReq}</span></div>` : ''}
                ${reqChecklist}
                <button class="btn-medieval" onclick="UI.petitionPromotion()" style="${_petBtnStyle}">\uD83D\uDCDC Petition for Promotion</button>
            </div>`;
        }

        // Change citizenship button (if in foreign town where player is not citizen)
        let currentTown;
        try { currentTown = Engine.findTown(Player.townId); } catch (e) { /* no-op */ }
        if (currentTown && Player.isPlayerCitizenOf && !Player.isPlayerCitizenOf(currentTown.kingdomId)) {
            const foreignK = kingdoms.find(k => k.id === currentTown.kingdomId);
            const foreignName = foreignK ? foreignK.name : 'Unknown';
            html += `<div class="detail-section">
                <button class="btn-medieval" onclick="UI.changeCitizenship('${currentTown.kingdomId}')" style="font-size:0.85rem;padding:6px 16px;">\uD83C\uDFDB\uFE0F Petition for ${foreignName} Citizenship</button>
            </div>`;
        }

        return html;
    }

    function petitionPromotion() {
        try {
            // Determine next rank index
            var citizenKId = Player.citizenshipKingdomId;
            var currentIdx = (Player.socialRank && citizenKId) ? (Player.socialRank[citizenKId] || 0) : 0;
            var nextIdx = currentIdx + 1;

            // If entering nobility (Minor Noble, index 4), show confirmation warning first
            if (nextIdx === 4) {
                _showNobilityConfirmation(citizenKId);
                return;
            }

            _executePetition();
        } catch (e) {
            toast(e.message || 'Promotion failed', 'danger');
        }
    }

    function _showNobilityConfirmation(kingdomId) {
        var kingdom = null;
        try { kingdom = Engine.findKingdom(kingdomId); } catch(e) {}
        var kingdomName = kingdom ? kingdom.name : 'the kingdom';

        var html = '<div style="padding:15px;">' +
            '<div style="text-align:center;margin-bottom:15px;">' +
            '<div style="font-size:2.5em;">⚠️👑</div>' +
            '<h3 style="color:#ff8888;margin:5px 0;">Entering the Nobility</h3>' +
            '<div style="color:var(--text-secondary);font-style:italic;">This decision will permanently change your relationship with ' + kingdomName + '.</div>' +
            '</div>' +

            '<div style="padding:12px;background:rgba(200,100,100,0.1);border:1px solid rgba(200,100,100,0.3);border-radius:6px;margin-bottom:12px;">' +
            '<div style="color:#ff8888;font-weight:bold;margin-bottom:8px;">⚠️ You Will Be Bound to the Crown</div>' +
            '<div style="font-size:0.9em;color:#ddd;">' +
            '<p style="margin:6px 0;">By accepting the title of <b>Minor Noble</b>, you are swearing a binding oath of fealty to the King of ' + kingdomName + '. This is not merely a title — it is a <b>lifelong obligation</b> to the crown.</p>' +
            '</div></div>' +

            '<div style="padding:12px;background:rgba(200,100,100,0.08);border:1px solid rgba(200,100,100,0.25);border-radius:6px;margin-bottom:12px;">' +
            '<div style="color:#ffaa66;font-weight:bold;margin-bottom:8px;">📋 Your Responsibilities as a Noble</div>' +
            '<div style="font-size:0.85em;">' +
            '<div style="margin:5px 0;">👑 <b>Royal Commissions</b> — The king will assign you personal tasks. Refusal costs reputation and may lead to demotion.</div>' +
            '<div style="margin:5px 0;">⚔️ <b>Wartime Production</b> — During war, you must produce weapons and armor on the king\'s schedule. Failure risks demotion.</div>' +
            '<div style="margin:5px 0;">📊 <b>Reputation Maintenance</b> — Your kingdom reputation must stay above 60 or you will be demoted back to Guildmaster.</div>' +
            '<div style="margin:5px 0;">🏛️ <b>Public Figure</b> — Criminal actions now carry reputation penalties. You are always watched.</div>' +
            '<div style="margin:5px 0;">🌍 <b>Foreign Entanglements</b> — Your foreign status is tied to your kingdom\'s diplomacy. War means losing foreign privileges.</div>' +
            '<div style="margin:5px 0;">💀 <b>Shared Fate</b> — If ' + kingdomName + ' falls to a conqueror, nobles face imprisonment, exile, or execution.</div>' +
            '</div></div>' +

            '<div style="padding:12px;background:rgba(100,200,100,0.08);border:1px solid rgba(100,200,100,0.25);border-radius:6px;margin-bottom:12px;">' +
            '<div style="color:#66ff88;font-weight:bold;margin-bottom:8px;">✨ Noble Privileges</div>' +
            '<div style="font-size:0.85em;">' +
            '<div style="margin:4px 0;">🛡️ 4 personal guards paid by the kingdom</div>' +
            '<div style="margin:4px 0;">👑 Direct influence over the king\'s decisions</div>' +
            '<div style="margin:4px 0;">💍 Noble marriage opportunities</div>' +
            '<div style="margin:4px 0;">🌍 Automatic status in foreign kingdoms</div>' +
            '<div style="margin:4px 0;">📜 Propose laws and shape the kingdom\'s future</div>' +
            '<div style="margin:4px 0;">📉 10% trade tax discount</div>' +
            '</div></div>' +

            '<p style="text-align:center;color:#ffaa66;font-style:italic;margin:10px 0;">Once you enter the nobility, there is no going back to being a simple merchant. Are you certain?</p>' +
            '</div>';

        openModal('⚠️ Confirm: Enter the Nobility of ' + kingdomName, html,
            '<button class="btn-medieval" onclick="UI.closeModal(); UI._executePetition();" style="background:linear-gradient(180deg,#5aad35,#3a7a24);border-color:#5aad35;margin-right:8px;">👑 Swear Fealty & Accept</button>' +
            '<button class="btn-medieval" onclick="UI.closeModal();">Cancel</button>'
        );
    }

    function _executePetition() {
        try {
            const result = Player.petitionForPromotion();
            if (result && result.success) {
                // Don't reopen character dialog — showRankCeremony() in player.js
                // already opened the ceremony modal. Let it display.
                toast(result.message, 'success');
            } else {
                toast((result && result.message) || 'Cannot promote', 'warning');
            }
        } catch (e) {
            toast(e.message || 'Promotion failed', 'danger');
        }
    }

    function changeCitizenship(kingdomId) {
        try {
            const result = Player.petitionCitizenship(kingdomId);
            if (result && result.success) {
                toast(result.message, 'success');
                openCharacterDialog();
            } else {
                toast((result && result.message) || 'Cannot change citizenship', 'warning');
            }
        } catch (e) {
            toast(e.message || 'Citizenship change failed', 'danger');
        }
    }

    // ── GIFT GIVING ──

    function openGiftDialog(personId) {
        const person = Engine.findPerson(personId);
        if (!person) { toast('Person not found.', 'warning'); return; }

        const rel = Player.getRelationship(personId);
        const relLabel = Player.getRelationshipLabel(rel.level);

        // Gift preferences
        var knownPrefs = Player.getKnownGiftPreferences ? Player.getKnownGiftPreferences(personId) : {};
        var prefHtml = '';
        if (knownPrefs.favorite || knownPrefs.hated) {
            prefHtml += '<div style="padding:6px;margin:4px 0;border:1px solid rgba(255,215,0,0.3);border-radius:6px;background:rgba(255,215,0,0.05);font-size:0.8rem;">';
            prefHtml += '<div style="font-weight:bold;margin-bottom:2px;">🔍 Known Preferences</div>';
            if (knownPrefs.favorite) {
                var favRes = Object.values(RESOURCE_TYPES).find(function(r) { return r.id === knownPrefs.favorite; });
                prefHtml += '<div style="color:#2ecc40;">💖 Loves: ' + (favRes ? favRes.icon + ' ' + favRes.name : knownPrefs.favorite) + ' (+10 per item!)</div>';
            }
            if (knownPrefs.hated) {
                var hateRes = Object.values(RESOURCE_TYPES).find(function(r) { return r.id === knownPrefs.hated; });
                prefHtml += '<div style="color:#e74c3c;">😠 Hates: ' + (hateRes ? hateRes.icon + ' ' + hateRes.name : knownPrefs.hated) + ' (-5 per item!)</div>';
            }
            prefHtml += '</div>';
        }

        let itemsHtml = '';
        for (const [resId, qty] of Object.entries(Player.inventory || {})) {
            if (qty <= 0) continue;
            const res = Object.values(RESOURCE_TYPES).find(r => r.id === resId);
            if (!res) continue;
            var badge = '';
            if (knownPrefs.favorite === resId) badge = ' <span style="color:#2ecc40;font-size:0.75rem;">💖 Loves!</span>';
            else if (knownPrefs.hated === resId) badge = ' <span style="color:#e74c3c;font-size:0.75rem;">😠 Hates!</span>';
            itemsHtml += `<div class="trade-item">
                <div class="res-info">${res.icon} ${res.name} (${qty})${badge}</div>
                <div class="trade-controls">
                    <button class="btn-trade buy" onclick="UI.executeGift('${personId}','${resId}',1)">Gift 1</button>
                </div>
            </div>`;
        }
        if (!itemsHtml) itemsHtml = '<div class="text-dim text-center">No items to give</div>';

        const html = `<div class="detail-section">
            <h3>🎁 Gift to ${person.firstName} ${person.lastName}</h3>
            <div class="detail-row"><span class="label">Relationship</span>
                <span class="value">${relLabel.icon} ${relLabel.name} (${Math.floor(rel.level)})</span></div>
            <div class="detail-row"><span class="label">Type</span>
                <span class="value">${rel.type}</span></div>
            ${prefHtml}
        </div>
        <div class="detail-section">${itemsHtml}</div>`;

        openModal(`🎁 Gift — ${person.firstName}`, html);
    }

    function executeGift(personId, resourceId, qty) {
        try {
            const result = Player.giveGift(personId, resourceId, qty);
            if (result && result.success) {
                toast(result.message, 'success');
                openGiftDialog(personId);
            } else {
                toast((result && result.message) || 'Cannot give gift', 'warning');
            }
        } catch (e) {
            toast(e.message || 'Gift failed', 'danger');
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  XP BAR UPDATE
    // ═══════════════════════════════════════════════════════════
    function updateXPBar() {
        if (typeof Player === 'undefined') return;
        const xpFill = document.getElementById('xpBarFill');
        const xpLabel = document.getElementById('xpBarLabel');
        const xpDetail = document.getElementById('xpBarDetail');
        if (!xpFill || !xpLabel) return;

        const totalXp = Player.totalXp || 0;
        const level = Player.level || 1;
        const currentLevelXp = Player.getCurrentLevelXP ? Player.getCurrentLevelXP() : 0;
        const nextLevelXp = Player.getNextLevelXP ? Player.getNextLevelXP() : 50;
        const title = Player.getMerchantTitle ? Player.getMerchantTitle() : 'Novice';
        const sp = Player.skillPoints || 0;

        const xpInLevel = totalXp - currentLevelXp;
        const xpNeeded = nextLevelXp - currentLevelXp;
        const maxLevel = 15;
        const pct = level >= maxLevel ? 100 : Math.min(100, Math.floor(xpInLevel / Math.max(1, xpNeeded) * 100));

        xpFill.style.width = pct + '%';
        xpLabel.textContent = `Lv${level} ${title}`;
        if (xpDetail) {
            var xpBankAmt = (typeof Player.xpBank !== 'undefined') ? Player.xpBank : 0;
            var bankStr = xpBankAmt > 0 ? ` • 🏦${xpBankAmt}/1000` : '';
            xpDetail.textContent = level >= maxLevel
                ? `${formatGold(totalXp)} XP • ${sp} SP${bankStr}`
                : `${formatGold(totalXp)}/${formatGold(nextLevelXp)} XP • ${sp} SP${bankStr}`;
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  RANK PROGRESSION TRACKER UPDATE
    // ═══════════════════════════════════════════════════════════
    function updateRankProgress() {
        var container = document.getElementById('rankProgressContent');
        if (!container) return;
        if (typeof Player === 'undefined' || !Player.getRankProgressBars) { container.innerHTML = ''; return; }
        var data = Player.getRankProgressBars();
        if (!data || !data.bars || data.bars.length === 0) {
            container.innerHTML = '';
            var group = document.getElementById('rankProgressGroup');
            if (group) group.style.display = 'none';
            return;
        }
        var group = document.getElementById('rankProgressGroup');
        if (group) group.style.display = '';

        var html = '<div style="font-size:10px;color:#d4af37;margin-bottom:3px;display:flex;justify-content:space-between;align-items:center;cursor:help;" title="To see privileges of the next rank, or to proceed once you meet all requirements, go to the Character menu.">';
        html += '<span>Progress to ' + (data.nextRank.icon || '📈') + ' ' + data.nextRank.name + ' Promotion</span>';
        if (data.allMet) html += '<span style="color:#5a5;font-size:9px;">✅ Ready!</span>';
        html += '</div>';
        for (var i = 0; i < data.bars.length; i++) {
            var b = data.bars[i];
            var barColor = b.met ? '#55a868' : (b.pct >= 60 ? '#ccb974' : '#7a6a4a');
            var shortLabel = b.label;
            // Tooltip descriptions for each requirement
            var tooltipMap = {
                '🪙 Gold Earned': 'Total gold earned through trading in this kingdom. Buy low and sell high to accumulate earnings.',
                '⭐ Reputation': 'Your standing with this kingdom. Increases by trading, completing petitions, and socializing with locals.',
                '💰 Fee': 'One-time promotion fee paid to the kingdom. Make sure you have enough gold on hand.',
                '📅 Residency': 'Days you have lived in this kingdom. Simply stay and go about your business.',
                '📊 Trade Days': 'Days since your first trade. Keep trading regularly to build your merchant reputation.',
                '🏗️ Buildings': 'Buildings you own in this kingdom. Construct or purchase buildings in towns.',
                '🔄 Trades': 'Total buy/sell transactions completed. Each purchase or sale counts as one trade.',
                '🏭 Prod. Buildings': 'Processing or finished-goods buildings you own. Build sawmills, smithies, bakeries, etc.',
                '👷 Workers': 'Employees working in this kingdom. Hire workers at your buildings to increase this count.',
                '🏘️ Towns': 'Number of different towns where you own buildings. Expand your business to new towns.',
                '🏘️ Towns w/ Property': 'Towns where you own buildings or land. Spread your holdings across the kingdom.',
                '🐪 Caravan Goods': 'Total goods transported by your caravans. Send caravans between towns to move goods.',
                '📜 Petitions': 'Successful petitions to the king. Visit the kingdom court to submit petitions.',
                '👑 Noble Endorsements': 'Nobles with 60+ relationship. Build friendships with Minor Nobles and above.',
                '👷 Total Workers': 'All employees across the kingdom. Hire more workers at your various buildings.',
                '🛤️ Infrastructure': 'Roads, bridges, or sea routes you have built. Invest in kingdom infrastructure.',
                '👑 King Relationship': 'Your personal relationship with the king. Attend court and complete royal commissions.'
            };
            var tooltip = tooltipMap[b.label] || '';
            var discountNote = b.discounted ? ' 💍' : '';
            var curStr = b.waived ? 'Waived' : (b.current >= 10000 ? (b.current / 1000).toFixed(0) + 'k' : String(b.current));
            var reqStr = b.waived ? '✓' : (b.required >= 10000 ? (b.required / 1000).toFixed(0) + 'k' : String(b.required));
            var displayValue = b.waived ? 'Waived ✓' : (curStr + '/' + reqStr + discountNote + (b.met ? ' ✓' : ''));
            var tipText = b.waived ? 'Waived by marriage to a noble spouse.' : (b.discounted ? tooltip + ' (Reduced by marriage or skill)' : tooltip);
            html += '<div style="margin-bottom:2px;cursor:help;" title="' + tipText + '">';
            html += '<div style="display:flex;justify-content:space-between;font-size:9px;color:' + (b.met ? '#5a5' : '#999') + ';line-height:1.2;">';
            html += '<span>' + shortLabel + '</span>';
            html += '<span>' + displayValue + '</span>';
            html += '</div>';
            html += '<div style="height:4px;background:#1a1a1a;border-radius:2px;overflow:hidden;">';
            html += '<div style="height:100%;width:' + b.pct + '%;background:' + barColor + ';border-radius:2px;transition:width 0.5s;"></div>';
            html += '</div></div>';
        }
        container.innerHTML = html;
    }

    // ═══════════════════════════════════════════════════════════
    //  HUNGER BAR UPDATE
    // ═══════════════════════════════════════════════════════════
    function updateHungerBar() {
        if (typeof Player === 'undefined') return;
        const hungerFill = document.getElementById('hungerFill');
        const hungerValue = document.getElementById('hungerValue');
        if (!hungerFill || !hungerValue) return;

        const hunger = Player.hunger != null ? Player.hunger : 80;
        hungerFill.style.width = Math.max(0, Math.min(100, hunger)) + '%';
        hungerValue.textContent = '🍖 ' + Math.floor(hunger);

        if (hunger >= 60) {
            hungerFill.style.background = '#55a868';
        } else if (hunger >= 30) {
            hungerFill.style.background = '#ccb974';
        } else {
            hungerFill.style.background = '#c44e52';
        }

        // Update food supply indicator
        var foodInfo = document.getElementById('foodSupplyInfo');
        var btnEat = document.getElementById('btnEatUntilFull');
        if (foodInfo && Player.getFoodSupply) {
            var supply = Player.getFoodSupply();
            foodInfo.textContent = '🍞 ' + supply.total + ' food (~' + supply.daysEstimate + 'd)';
            if (supply.daysEstimate <= 3) foodInfo.style.color = '#c44e52';
            else if (supply.daysEstimate <= 7) foodInfo.style.color = '#ccb974';
            else foodInfo.style.color = '#aaa';
        }
        if (btnEat) {
            btnEat.disabled = hunger >= 100 || !(Player.getFoodSupply && Player.getFoodSupply().total > 0);
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  ENERGY & THIRST BAR UPDATE
    // ═══════════════════════════════════════════════════════════
    function updateFatigueBar() {
        if (typeof Player === 'undefined') return;

        // Energy bar (replaces old fatigue)
        var fatigueFill = document.getElementById('fatigueFill');
        var fatigueValue = document.getElementById('fatigueValue');
        if (fatigueFill && fatigueValue) {
            var energy = Player.energy != null ? Player.energy : 100;
            var maxEnergy = Player.maxEnergy || 100;
            var energyPct = Math.max(0, Math.min(100, (energy / maxEnergy) * 100));
            fatigueFill.style.width = energyPct + '%';

            var icon = '⚡';
            if (energyPct <= 15) icon = '😵';
            else if (energyPct <= 30) icon = '😴';
            else if (energyPct <= 50) icon = '😐';
            fatigueValue.textContent = icon + ' ' + Math.floor(energy) + '/' + maxEnergy;

            if (energyPct > 60) fatigueFill.style.background = '#55a868';
            else if (energyPct > 40) fatigueFill.style.background = '#ccb974';
            else if (energyPct > 20) fatigueFill.style.background = '#e8a040';
            else fatigueFill.style.background = '#c44e52';
        }

        // Thirst bar
        var thirstFill = document.getElementById('thirstFill');
        var thirstValue = document.getElementById('thirstValue');
        if (thirstFill && thirstValue) {
            var thirst = Player.thirst != null ? Player.thirst : 80;
            var thirstPct = Math.max(0, Math.min(100, thirst));
            thirstFill.style.width = thirstPct + '%';

            var tIcon = '💧';
            if (thirstPct <= 15) tIcon = '🏜️';
            else if (thirstPct <= 30) tIcon = '😰';
            else if (thirstPct <= 50) tIcon = '🫗';
            thirstValue.textContent = tIcon + ' ' + Math.floor(thirst);

            if (thirstPct > 60) thirstFill.style.background = '#4488cc';
            else if (thirstPct > 40) thirstFill.style.background = '#7799aa';
            else if (thirstPct > 20) thirstFill.style.background = '#cc8844';
            else thirstFill.style.background = '#c44e52';
        }

        // Update drink supply indicator
        var drinkInfo = document.getElementById('drinkSupplyInfo');
        var btnDrink = document.getElementById('btnDrinkUntilFull');
        if (drinkInfo && typeof Player !== 'undefined' && Player.getDrinkSupply) {
            var supply = Player.getDrinkSupply();
            drinkInfo.textContent = '🫗 ' + supply.total + ' drinks (~' + supply.daysEstimate + 'd)';
            if (supply.daysEstimate <= 3) drinkInfo.style.color = '#c44e52';
            else if (supply.daysEstimate <= 7) drinkInfo.style.color = '#ccb974';
            else drinkInfo.style.color = '#aaa';
        }
        if (btnDrink) {
            var thirstVal = typeof Player !== 'undefined' && Player.thirst != null ? Player.thirst : 80;
            btnDrink.disabled = thirstVal >= 100 || !(typeof Player !== 'undefined' && Player.getDrinkSupply && Player.getDrinkSupply().total > 0);
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  HEALTH BAR UPDATE
    // ═══════════════════════════════════════════════════════════
    function updateHealthBar() {
        if (typeof Player === 'undefined') return;
        var healthFill = document.getElementById('healthFill');
        var healthValue = document.getElementById('healthValue');
        if (!healthFill || !healthValue) return;

        var health = Player.health != null ? Player.health : 100;
        var maxHealth = Player.maxHealth || 100;
        var healthPct = Math.max(0, Math.min(100, (health / maxHealth) * 100));
        healthFill.style.width = healthPct + '%';

        var hIcon = '❤️';
        if (healthPct <= 15) hIcon = '💀';
        else if (healthPct <= 30) hIcon = '🩹';
        else if (healthPct <= 50) hIcon = '🤕';
        healthValue.textContent = hIcon + ' ' + Math.floor(health) + '/' + maxHealth;

        if (healthPct > 60) healthFill.style.background = '#55a868';
        else if (healthPct > 40) healthFill.style.background = '#ccb974';
        else if (healthPct > 20) healthFill.style.background = '#e8a040';
        else healthFill.style.background = '#c44e52';
    }

    function updateConditionsIndicator() {
        if (typeof Player === 'undefined') return;
        var injuries = Player.injuries || [];
        var illnesses = Player.illnesses || [];
        var healthGroup = document.getElementById('healthBarGroup');
        if (!healthGroup) return;

        var el2 = document.getElementById('conditionsIndicator');
        if (injuries.length === 0 && illnesses.length === 0) {
            if (el2) el2.style.display = 'none';
            return;
        }

        if (!el2) {
            el2 = document.createElement('div');
            el2.id = 'conditionsIndicator';
            el2.style.cssText = 'padding:2px 6px;font-size:0.72rem;line-height:1.4;cursor:pointer;';
            el2.title = 'Click for health details';
            el2.onclick = function() { openHealthDetailPanel(); };
            healthGroup.appendChild(el2);
        }
        el2.style.display = '';

        var html2 = '';
        for (var i = 0; i < injuries.length; i++) {
            var inj = injuries[i];
            var sevColor = inj.severity === 'severe' ? '#e74c3c' : inj.severity === 'moderate' ? '#e67e22' : '#8e8';
            var injName = inj.name || 'Injury';
            html2 += '<span onclick="UI.openHealthDetailPanel()" style="cursor:pointer;color:' + sevColor + ';margin-right:8px;">🩹 ' + injName + ' <span style="font-size:0.65rem;opacity:0.8;">(' + inj.severity + ')</span></span>';
        }
        for (var j = 0; j < illnesses.length; j++) {
            var ill = illnesses[j];
            var sevColor2 = ill.severity === 'severe' ? '#e74c3c' : ill.severity === 'moderate' ? '#e67e22' : '#8e8';
            var illName = ill.name || (ill.type ? ill.type.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); }) : 'Illness');
            html2 += '<span onclick="UI.openHealthDetailPanel()" style="cursor:pointer;color:' + sevColor2 + ';margin-right:8px;">🤒 ' + illName + ' <span style="font-size:0.65rem;opacity:0.8;">(' + ill.severity + ')</span></span>';
        }
        el2.innerHTML = html2;
    }

    function openHealthDetailPanel() {
        if (typeof Player === 'undefined') return;
        var injuries = Player.injuries || [];
        var illnesses = Player.illnesses || [];
        var injTypes = Player.getInjuryTypes ? Player.getInjuryTypes() : [];
        var illTypes = Player.getIllnessTypes ? Player.getIllnessTypes() : [];
        var day = 0;
        try { day = Engine.getDay(); } catch(e) {}

        var html = '<div style="max-height:500px;overflow-y:auto;">';

        if (injuries.length === 0 && illnesses.length === 0) {
            html += '<p style="color:#8e8;text-align:center;padding:20px;">✅ You are in good health — no injuries or illnesses.</p>';
            var curHp = Player.health != null ? Player.health : 100;
            var maxHp2 = Player.maxHealth || 100;
            if (curHp < maxHp2) {
                html += '<p style="color:#ccc;text-align:center;font-size:0.85rem;">❤️ Health: ' + Math.floor(curHp) + '/' + maxHp2 + ' — Recovers +1/day when energy, hunger, and thirst are all above 80%.</p>';
            }
            html += '</div>';
            openModal('🏥 Health Status', html, '<button class="btn-medieval" data-action="closeModal">Close</button>');
            return;
        }

        // Injuries
        for (var i = 0; i < injuries.length; i++) {
            var inj = injuries[i];
            var typeDef = null;
            for (var ti = 0; ti < injTypes.length; ti++) {
                if (injTypes[ti].id === inj.type) { typeDef = injTypes[ti]; break; }
            }
            var sevColor = inj.severity === 'severe' ? '#e74c3c' : inj.severity === 'moderate' ? '#e67e22' : '#2ecc71';
            var injName = inj.name || (typeDef ? typeDef.name : 'Unknown Injury');
            var daysHad = day - (inj.dayOccurred || 0);

            html += '<div style="border:1px solid ' + sevColor + '44;border-radius:8px;padding:10px;margin-bottom:10px;background:rgba(200,50,50,0.06);">';
            html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
            html += '<span style="font-size:1.05rem;font-weight:bold;color:#f0d0a0;">🩹 ' + injName + '</span>';
            html += '<span style="font-weight:bold;color:' + sevColor + ';text-transform:uppercase;font-size:0.85rem;">' + (inj.severity || 'unknown') + '</span>';
            html += '</div>';

            // Status
            html += '<div style="font-size:0.82rem;color:#bbb;margin:6px 0;">';
            html += inj.treated ? '✅ Being treated' : '⚠️ <span style="color:#e67e22;">Untreated</span>';
            html += ' · Day ' + daysHad + ' of injury';
            if (inj.treated && inj.healDay) {
                var daysLeft = Math.max(0, inj.healDay - day);
                html += ' · ~' + daysLeft + ' days to recover';
            }
            html += '</div>';

            // Debuffs
            if (typeDef && typeDef.debuffDesc) {
                html += '<div style="font-size:0.8rem;padding:6px;background:rgba(0,0,0,0.2);border-radius:4px;margin:4px 0;">';
                html += '<strong style="color:#e67e22;">⚡ Active Debuffs:</strong> <span style="color:#ddd;">' + typeDef.debuffDesc + '</span>';
                html += '</div>';
            }

            // Risks
            var drainPerDay = inj.severity === 'severe' ? 8 : inj.severity === 'moderate' ? 3 : 1;
            html += '<div style="font-size:0.8rem;padding:6px;background:rgba(0,0,0,0.2);border-radius:4px;margin:4px 0;">';
            html += '<strong style="color:#c44e52;">⚠️ Risks:</strong> <span style="color:#ddd;">';
            html += '❤️ Drains <strong style="color:#e74c3c;">' + drainPerDay + ' health/day</strong>. ';
            if (typeDef && typeDef.deathRisk) {
                html += 'Daily death risk: ' + (typeDef.deathRisk * 100).toFixed(1) + '%. ';
            }
            html += 'Health at 0 = death. ';
            if (inj.severity === 'minor') {
                html += 'Will heal on its own in ' + (typeDef ? (typeDef.healDays * 2) : '10-30') + ' days untreated.';
            } else if (inj.severity === 'moderate') {
                html += 'May worsen to <span style="color:#e74c3c;">severe</span> if untreated for 10+ days. Natural recovery: ' + (typeDef ? (typeDef.healDays * 4) : '30-90') + ' days.';
            } else if (inj.severity === 'severe') {
                html += '<span style="color:#e74c3c;">Can be fatal if untreated for 30+ days.</span> Seek treatment immediately.';
            }
            html += '</span></div>';

            // Treatment options
            html += '<div style="font-size:0.8rem;padding:6px;background:rgba(50,100,50,0.15);border-radius:4px;margin:4px 0;">';
            html += '<strong style="color:#2ecc71;">💊 Treatment Options:</strong><br>';
            html += '<span style="color:#ddd;">';
            html += '🏥 <strong>Hospital</strong> — Treats all severities. Fastest recovery. Requires hospital in town.<br>';
            if (inj.severity !== 'severe') {
                html += '🩺 <strong>Clinic</strong> — Treats minor/moderate. Cheaper than hospital. Requires clinic in town.<br>';
            } else {
                html += '🩺 <strong>Clinic</strong> — <span style="color:#e67e22;">Can treat severe, but takes 2x longer with lower success rate.</span><br>';
            }
            html += '🧑‍⚕️ <strong>Self-treat</strong> — Requires ';
            if (inj.severity === 'minor') html += 'First Aid skill';
            else if (inj.severity === 'moderate') html += 'Field Medic skill';
            else html += 'Doctor skill';
            if (typeDef && typeDef.product) {
                var prodName = typeDef.product.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
                html += ' + ' + prodName + ' (' + (typeDef.productCost || '?') + 'g)';
            }
            html += '</span></div>';
            html += '</div>';
        }

        // Illnesses
        for (var k = 0; k < illnesses.length; k++) {
            var ill = illnesses[k];
            var illTypeDef = null;
            for (var ti2 = 0; ti2 < illTypes.length; ti2++) {
                if (illTypes[ti2].id === ill.type) { illTypeDef = illTypes[ti2]; break; }
            }
            var sevColor2 = ill.severity === 'severe' ? '#e74c3c' : ill.severity === 'moderate' ? '#e67e22' : '#2ecc71';
            var illName = ill.name || (illTypeDef ? illTypeDef.name : (ill.type ? ill.type.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); }) : 'Unknown Illness'));
            var daysIll = day - (ill.dayOccurred || 0);

            html += '<div style="border:1px solid ' + sevColor2 + '44;border-radius:8px;padding:10px;margin-bottom:10px;background:rgba(200,150,50,0.06);">';
            html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
            html += '<span style="font-size:1.05rem;font-weight:bold;color:#f0d0a0;">🤒 ' + illName + '</span>';
            html += '<span style="font-weight:bold;color:' + sevColor2 + ';text-transform:uppercase;font-size:0.85rem;">' + (ill.severity || 'unknown') + '</span>';
            html += '</div>';

            // Status
            html += '<div style="font-size:0.82rem;color:#bbb;margin:6px 0;">';
            html += ill.treated ? '✅ Being treated' : '⚠️ <span style="color:#e67e22;">Untreated</span>';
            html += ' · Day ' + daysIll + ' of illness';
            if (ill.treated && ill.healDay) {
                var daysLeft2 = Math.max(0, ill.healDay - day);
                html += ' · ~' + daysLeft2 + ' days to recover';
            }
            html += '</div>';

            // Debuffs
            if (illTypeDef && illTypeDef.debuffDesc) {
                html += '<div style="font-size:0.8rem;padding:6px;background:rgba(0,0,0,0.2);border-radius:4px;margin:4px 0;">';
                html += '<strong style="color:#e67e22;">⚡ Active Debuffs:</strong> <span style="color:#ddd;">' + illTypeDef.debuffDesc + '</span>';
                html += '</div>';
            }

            // Risks
            var drainPerDay2 = ill.severity === 'severe' ? 8 : ill.severity === 'moderate' ? 3 : 1;
            html += '<div style="font-size:0.8rem;padding:6px;background:rgba(0,0,0,0.2);border-radius:4px;margin:4px 0;">';
            html += '<strong style="color:#c44e52;">⚠️ Risks:</strong> <span style="color:#ddd;">';
            html += '❤️ Drains <strong style="color:#e74c3c;">' + drainPerDay2 + ' health/day</strong>. ';
            if (illTypeDef && illTypeDef.deathRisk) {
                html += 'Daily death risk: ' + (illTypeDef.deathRisk * 100).toFixed(1) + '%. ';
            }
            html += 'Health at 0 = death. ';
            if (ill.severity === 'minor') {
                html += 'May worsen to <span style="color:#e67e22;">moderate</span> after 10 days untreated.';
            } else if (ill.severity === 'moderate') {
                html += 'May worsen to <span style="color:#e74c3c;">severe</span> after 25 days untreated.';
            } else if (ill.severity === 'severe') {
                html += '<span style="color:#e74c3c;">Can be fatal. Seek treatment immediately.</span>';
            }
            html += '</span></div>';

            // Treatment
            html += '<div style="font-size:0.8rem;padding:6px;background:rgba(50,100,50,0.15);border-radius:4px;margin:4px 0;">';
            html += '<strong style="color:#2ecc71;">💊 Treatment Options:</strong><br>';
            html += '<span style="color:#ddd;">';
            html += '🏥 <strong>Hospital</strong> — Treats all severities. Fastest recovery.<br>';
            if (ill.severity !== 'severe') {
                html += '🩺 <strong>Clinic</strong> — Treats minor/moderate. Cheaper than hospital.<br>';
            } else {
                html += '🩺 <strong>Clinic</strong> — <span style="color:#e67e22;">Can treat severe, but takes 2x longer with lower success rate.</span><br>';
            }
            html += '🧑‍⚕️ <strong>Self-treat</strong> — Requires ';
            if (ill.severity === 'minor') html += 'First Aid skill';
            else if (ill.severity === 'moderate') html += 'Field Medic skill';
            else html += 'Doctor skill';
            if (illTypeDef && illTypeDef.product) {
                var prodName2 = illTypeDef.product.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
                html += ' + ' + prodName2 + ' (' + (illTypeDef.productCost || '?') + 'g)';
            }
            html += '</span></div>';
            html += '</div>';
        }

        html += '</div>';

        var footer = '<button class="btn-medieval" onclick="UI.openHealthDialog()" style="margin-right:8px;">🏥 Go to Treatment</button>';
        footer += '<button class="btn-medieval" data-action="closeModal">Close</button>';
        openModal('🏥 Health Status — Conditions Detail', html, footer);
    }

    // ═══════════════════════════════════════════════════════════
    //  GUILDS PANEL
    // ═══════════════════════════════════════════════════════════
    function openGuildsPanel() {
        if (typeof Player === 'undefined') return;
        if (Player.traveling) { toast('Cannot visit guilds while traveling.', 'warning'); return; }

        var guilds = CONFIG.GUILDS;
        if (!guilds) { toast('Guilds not available.', 'warning'); return; }

        var day = 0;
        try { day = Engine.getDay(); } catch(e) {}

        var html = '<div style="max-height:550px;overflow-y:auto;">';
        html += '<p style="color:#ccc;margin:0 0 10px;">Join guilds to craft at any guild-member building in your town. One membership per building category.</p>';

        for (var gId in guilds) {
            var g = guilds[gId];
            var membership = Player.guildMemberships[gId];
            var isMember = membership && membership.expiresDay > day;
            var monthlyPrice = Player.getGuildPrice(gId, 'monthly');
            var yearlyPrice = Player.getGuildPrice(gId, 'yearly');
            var isMerchants = (gId === 'merchants');

            html += '<div style="border:1px solid ' + (isMember ? '#4a7' : '#555') + ';border-radius:6px;padding:10px;margin-bottom:8px;background:' + (isMember ? 'rgba(68,170,119,0.1)' : 'rgba(40,40,40,0.5)') + ';">';
            html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
            html += '<span style="font-size:1.2em;">' + g.icon + ' <strong>' + escapeHtml(g.name) + '</strong></span>';

            if (isMember) {
                var _arStatus = membership.autoRenew ? ' <span style="color:#ffd700;font-size:0.8em;">🔄 Auto-renew ON</span>' : '';
                html += '<span style="color:#4a7;font-size:0.9em;">✅ Member until Day ' + membership.expiresDay + _arStatus + '</span>';
            } else {
                html += '<span style="color:#888;font-size:0.9em;">Not a member</span>';
            }
            html += '</div>';

            // Merchants Guild: special benefit description
            if (isMerchants) {
                if (!isMember) {
                    html += '<div style="background:rgba(255,215,0,0.08);border:1px solid #5a4a20;border-radius:4px;padding:8px;margin:6px 0;">';
                    html += '<div style="color:#d4a74a;font-size:0.9em;font-weight:bold;margin-bottom:4px;">📊 Exclusive Benefit: Daily Market Intelligence</div>';
                    html += '<div style="color:#bbb;font-size:0.82em;line-height:1.4;">Members gain access to the guild\'s <strong>Daily Market Report</strong> — a curated list of 10 trade tips compiled by guild agents across all towns. Tips include the best prices for goods, profitable trade routes, cheapest labor markets, building costs, resource shortages, and more. A new report is generated each day. Reading the report costs a small fee of ' + (CONFIG.MERCHANTS_GUILD_REPORT_FEE || 25) + 'g.</div>';
                    html += '</div>';
                } else {
                    // Member: show report button
                    html += '<div style="margin:6px 0;text-align:center;">';
                    html += '<button class="btn-medieval" style="background:linear-gradient(135deg,#3a2a10,#5a4a20);border-color:#d4a74a;color:#FFD700;padding:6px 16px;" onclick="UI.openMerchantGuildReport()">📊 Read Today\'s Market Report (' + (CONFIG.MERCHANTS_GUILD_REPORT_FEE || 25) + 'g)</button>';
                    html += '</div>';
                }
            }

            // Building types this guild gives access to
            var guildBuildingNames = [];
            var BT_G = typeof BUILDING_TYPES !== 'undefined' ? BUILDING_TYPES : (CONFIG.BUILDING_TYPES || {});
            for (var btk in BT_G) {
                var bt = BT_G[btk];
                if (g.categories.indexOf(bt.category) !== -1) {
                    guildBuildingNames.push(bt.name);
                }
            }
            if (!isMerchants) {
                html += '<div style="color:#aaa;font-size:0.85em;margin:4px 0;">Gives Access to Buildings: <span style="color:#ddd;">' + (guildBuildingNames.length > 0 ? guildBuildingNames.join(', ') : 'None') + '</span></div>';
            } else {
                html += '<div style="color:#aaa;font-size:0.85em;margin:4px 0;">Gives Access to: <span style="color:#ddd;">Market Stalls, Transport Guild Halls, & Daily Market Intelligence Reports</span></div>';
            }

            // Local availability indicator — only count buildings whose owner is in the guild
            var localTown = null;
            try { localTown = Engine.findTown(Player.townId); } catch(e2) {}
            var localGuildBuildings = 0;
            if (localTown && localTown.buildings) {
                for (var lbi = 0; lbi < localTown.buildings.length; lbi++) {
                    var lb = localTown.buildings[lbi];
                    if (!lb.inGuild) continue;
                    var lbt = null;
                    for (var lbk in BT_G) { if (BT_G[lbk].id === lb.type) { lbt = BT_G[lbk]; break; } }
                    if (lbt && g.categories.indexOf(lbt.category) !== -1) localGuildBuildings++;
                }
            }
            if (localGuildBuildings > 0) {
                html += '<div style="color:#4a7;font-size:0.85em;margin:2px 0;">✅ ' + localGuildBuildings + ' guild building' + (localGuildBuildings > 1 ? 's' : '') + ' in this town</div>';
            } else if (!isMerchants) {
                html += '<div style="color:#c55;font-size:0.85em;margin:2px 0;">❌ No guild buildings of this type here</div>';
            }

            // Join/Extend buttons with auto-renew next to active type
            html += '<div style="margin-top:6px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;">';
            var _arLabel = '';
            if (isMember) {
                var _arChecked = membership.autoRenew ? 'checked' : '';
                _arLabel = '<label style="font-size:0.8em;color:#ccc;cursor:pointer;display:inline-flex;align-items:center;gap:3px;margin-left:2px;">' +
                    '<input type="checkbox" ' + _arChecked + ' onchange="(function(cb){var r=Player.setGuildAutoRenew(\'' + gId + '\',cb.checked);UI.toast(r.message,r.success?\'success\':\'warning\');UI.openGuildsPanel();})(this)">' +
                    '🔄 Auto</label>';
            }
            html += '<button class="btn-medieval" onclick="UI.guildJoin(\'' + gId + '\', \'monthly\')">' + (isMember ? '🔄 Extend' : '📜 Join') + ' Monthly (' + monthlyPrice + 'g)</button>';
            if (isMember && membership.type === 'monthly') html += _arLabel;
            html += '<button class="btn-medieval" onclick="UI.guildJoin(\'' + gId + '\', \'yearly\')">' + (isMember ? '🔄 Extend' : '📜 Join') + ' Yearly (' + yearlyPrice + 'g)</button>';
            if (isMember && membership.type !== 'monthly') html += _arLabel;
            html += '</div>';

            // If member, show craftable items at current town
            if (isMember) {
                var items = Player.getGuildCraftableItems();
                var guildItems = [];
                for (var i = 0; i < items.length; i++) {
                    if (items[i].guildName === g.name) guildItems.push(items[i]);
                }
                if (guildItems.length > 0) {
                    html += '<div style="margin-top:8px;border-top:1px solid #444;padding-top:6px;">';
                    html += '<div style="color:#aaa;font-size:0.85em;margin-bottom:4px;">Available to craft in this town:</div>';
                    for (var j = 0; j < guildItems.length; j++) {
                        var item = guildItems[j];
                        var matsText = '';
                        var consumeKeys = Object.keys(item.consumes || {});
                        if (consumeKeys.length > 0) {
                            var matParts = [];
                            for (var k = 0; k < consumeKeys.length; k++) {
                                matParts.push(item.consumes[consumeKeys[k]] + ' ' + consumeKeys[k]);
                            }
                            matsText = matParts.join(', ');
                        } else {
                            matsText = 'none';
                        }
                        html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:3px 0;border-bottom:1px solid #333;">';
                        // Quality chance label for tiered products
                        var _gqLabel = '';
                        var _gqRes = findResource(item.productId);
                        if (_gqRes && (_gqRes.tier === 'good' || _gqRes.tier === 'excellent') && _gqRes.baseItem && Player.qualityCraftChance) {
                            var _gqChance = Math.round(Player.qualityCraftChance(_gqRes.tier, _gqRes.baseItem, 0) * 100);
                            _gqLabel = ' <span style="color:#a855f7;font-size:0.8em;">(' + _gqChance + '% chance)</span>';
                        }
                        html += '<span><strong>' + escapeHtml(item.productName) + '</strong>' + _gqLabel + ' <span style="color:#888;font-size:0.85em;">at ' + escapeHtml(item.buildingName) + ' (needs: ' + matsText + ')</span></span>';
                        html += '<button class="btn-medieval" style="font-size:0.85em;" onclick="UI.guildCraftPrompt(\'' + escapeHtml(item.buildingId) + '\', \'' + escapeHtml(item.productId) + '\', \'' + escapeHtml(item.productName) + '\')">🔨 Craft</button>';
                        html += '</div>';
                    }
                    html += '</div>';
                } else if (!isMerchants) {
                    html += '<div style="margin-top:6px;color:#777;font-size:0.85em;">No guild buildings of this type in your current town.</div>';
                }
            }

            html += '</div>';
        }

        html += '</div>';
        openModal('🏛️ Guilds', html);
    }

    function guildJoin(guildId, type) {
        if (typeof Player === 'undefined') return;
        var result = Player.joinGuild(guildId, type);
        if (result.success) {
            toast(result.message, 'success');
        } else {
            toast(result.message, 'warning');
        }
        openGuildsPanel(); // refresh
    }

    function openMerchantGuildReport() {
        if (typeof Player === 'undefined') return;
        var result = Player.readMerchantGuildReport();
        if (!result.success) {
            toast(result.message, 'warning');
            return;
        }

        var tips = result.tips || [];
        var day = 0;
        try { day = Engine.getDay(); } catch(e) {}
        var year = Math.floor((day - 1) / (CONFIG.DAYS_PER_SEASON || 90)) + 1;

        var html = '<div style="max-height:500px;overflow-y:auto;padding:4px;">';
        html += '<div style="text-align:center;border-bottom:2px solid #5a4a20;padding-bottom:8px;margin-bottom:12px;">';
        html += '<div style="font-size:1.1rem;color:#d4a74a;font-variant:small-caps;letter-spacing:2px;">Merchants\' Guild Intelligence Bureau</div>';
        html += '<div style="font-size:0.8rem;color:#888;margin-top:4px;">Daily Market Report — Day ' + day + ', Year ' + year + '</div>';
        html += '<div style="font-size:0.75rem;color:#666;margin-top:2px;">Report fee: ' + (result.fee || 10) + 'g deducted</div>';
        html += '</div>';

        if (tips.length === 0) {
            html += '<p style="color:#999;font-style:italic;text-align:center;">Our agents found no actionable intelligence today. Check back tomorrow.</p>';
        } else {
            for (var i = 0; i < tips.length; i++) {
                var tip = tips[i];
                html += '<div style="display:flex;gap:8px;align-items:flex-start;padding:6px 8px;margin-bottom:6px;background:rgba(60,50,30,0.2);border-left:3px solid #5a4a20;border-radius:0 4px 4px 0;">';
                html += '<span style="font-size:1.1rem;flex-shrink:0;">' + (tip.icon || '📋') + '</span>';
                html += '<div style="font-size:0.85rem;color:#d4c8a8;line-height:1.4;">' + (i + 1) + '. ' + tip.text + '</div>';
                html += '</div>';
            }
        }

        html += '<div style="text-align:center;margin-top:12px;border-top:1px solid #333;padding-top:8px;">';
        html += '<div style="font-size:0.7rem;color:#666;font-style:italic;">This report is valid for today only. A new report will be available tomorrow.</div>';
        html += '</div>';
        html += '</div>';

        openModal('📊 Daily Market Report', html, '<button class="btn-medieval" onclick="UI.openGuildsPanel()">← Back to Guilds</button> <button class="btn-medieval" data-action="closeModal">Close</button>');
    }

    function guildCraftPrompt(buildingId, productId, productName) {
        var html = '<div style="text-align:center;">';
        html += '<p>How many <strong>' + productName + '</strong> to craft?</p>';
        html += '<input type="number" id="guildCraftQty" value="1" min="1" max="100" style="width:80px;text-align:center;padding:4px;background:#222;color:#eee;border:1px solid #555;border-radius:4px;">';
        html += '<div style="margin-top:10px;">';
        html += '<button class="btn-medieval" onclick="UI.guildCraftExecute(\'' + escapeHtml(buildingId) + '\', \'' + escapeHtml(productId) + '\')">🔨 Craft</button>';
        html += ' <button class="btn-medieval" onclick="UI.openGuildsPanel()">Cancel</button>';
        html += '</div></div>';
        openModal('🔨 Craft ' + productName, html);
    }

    function guildCraftExecute(buildingId, productId) {
        if (typeof Player === 'undefined') return;
        var qtyEl = document.getElementById('guildCraftQty');
        var qty = qtyEl ? parseInt(qtyEl.value, 10) : 1;
        if (isNaN(qty) || qty < 1) qty = 1;

        var result = Player.craftAtGuildBuilding(buildingId, productId, qty);
        if (result.success) {
            toast(result.message, 'success');
        } else {
            toast(result.message, 'warning');
        }
        openGuildsPanel(); // refresh
    }

    // ═══════════════════════════════════════════════════════════
    //  REAL ESTATE MARKET ANALYSIS REPORT
    // ═══════════════════════════════════════════════════════════
    function openRealEstateReport(selectedTownId) {
        if (typeof Player === 'undefined' || typeof Engine === 'undefined') return;

        var hasLocal = Player.hasSkill && Player.hasSkill('local_market_analysis');
        var hasKingdom = Player.hasSkill && Player.hasSkill('kingdom_market_analysis');
        var hasGlobal = Player.hasSkill && Player.hasSkill('global_market_analysis');

        if (!hasLocal && !hasKingdom && !hasGlobal) {
            openModal('📊 Real Estate Report',
                '<p style="color:#cc8800;">You need the <b>Local Market Analysis</b> skill to view real estate reports.</p>',
                '<button class="btn-medieval" data-action="closeModal">Close</button>');
            return;
        }

        // Determine available towns
        var allTowns = Engine.getTowns();
        var playerTown = (typeof Player !== 'undefined' && Player.townId) ? Engine.findTown(Player.townId) : null;
        var playerKingdomId = typeof Player !== 'undefined' ? Player.kingdomId : null;
        var availableTowns = [];

        if (hasGlobal) {
            availableTowns = allTowns;
        } else if (hasKingdom) {
            for (var i = 0; i < allTowns.length; i++) {
                if (allTowns[i].kingdomId === playerKingdomId) availableTowns.push(allTowns[i]);
            }
        } else {
            if (playerTown) availableTowns = [playerTown];
        }

        if (availableTowns.length === 0) {
            openModal('📊 Real Estate Report',
                '<p style="color:#aaa;">No towns available for analysis.</p>',
                '<button class="btn-medieval" data-action="closeModal">Close</button>');
            return;
        }

        var targetTownId = selectedTownId || (playerTown ? playerTown.id : availableTowns[0].id);
        var report = Engine.getRealEstateReport(targetTownId);
        if (!report) {
            openModal('📊 Real Estate Report',
                '<p style="color:#cc8800;">No market data available for this town.</p>',
                '<button class="btn-medieval" data-action="closeModal">Close</button>');
            return;
        }

        var html = '<div style="max-height:520px;overflow-y:auto;">';

        // Town selector (if more than one town available)
        if (availableTowns.length > 1) {
            html += '<div style="margin-bottom:10px;">';
            html += '<label style="font-size:0.8rem;color:#ccc;">Select Town: </label>';
            html += '<select id="reReportTownSelect" onchange="UI.openRealEstateReport(this.value)" style="font-size:0.8rem;padding:3px 6px;background:#2a2520;color:#e8dcc8;border:1px solid #555;border-radius:4px;">';
            for (var ti = 0; ti < availableTowns.length; ti++) {
                var t = availableTowns[ti];
                var sel = (t.id === targetTownId) ? ' selected' : '';
                html += '<option value="' + t.id + '"' + sel + '>' + (t.name || t.id) + '</option>';
            }
            html += '</select></div>';
        }

        // Header
        html += '<h3 style="color:#ffd700;margin:0 0 6px 0;">📊 ' + report.townName + ' Real Estate Report</h3>';
        html += '<div style="font-size:0.75rem;color:#999;margin-bottom:10px;">Day ' + report.day + ' | ' + (report.category || 'Unknown') + '</div>';

        // Building costs table
        html += '<h4 style="color:#cba135;margin:10px 0 4px 0;">🏗️ Building Costs</h4>';
        html += '<table style="width:100%;border-collapse:collapse;font-size:0.78rem;">';
        html += '<tr style="border-bottom:1px solid rgba(255,215,0,0.3);">';
        html += '<th style="text-align:left;padding:4px 6px;">Building</th>';
        html += '<th style="text-align:right;padding:4px 6px;">Base Cost</th>';
        html += '<th style="text-align:right;padding:4px 6px;">Material Cost</th>';
        html += '<th style="text-align:right;padding:4px 6px;">Total</th></tr>';
        for (var bi = 0; bi < report.buildings.length; bi++) {
            var b = report.buildings[bi];
            html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.05);">';
            html += '<td style="padding:3px 6px;">' + b.name + '</td>';
            html += '<td style="text-align:right;padding:3px 6px;color:#ccc;">' + b.baseCost + 'g</td>';
            html += '<td style="text-align:right;padding:3px 6px;color:#ccc;">' + b.materialCost + 'g</td>';
            html += '<td style="text-align:right;padding:3px 6px;color:#ffd700;">' + b.totalCost + 'g</td></tr>';
        }
        html += '</table>';

        // Material price trends table
        html += '<h4 style="color:#cba135;margin:14px 0 4px 0;">📈 Material Price Trends</h4>';
        html += '<table style="width:100%;border-collapse:collapse;font-size:0.78rem;">';
        html += '<tr style="border-bottom:1px solid rgba(255,215,0,0.3);">';
        html += '<th style="text-align:left;padding:4px 6px;">Material</th>';
        html += '<th style="text-align:right;padding:4px 6px;">Current</th>';
        html += '<th style="text-align:right;padding:4px 6px;">90d Ago</th>';
        html += '<th style="text-align:right;padding:4px 6px;">360d Ago</th>';
        html += '<th style="text-align:right;padding:4px 6px;">90d Proj</th>';
        html += '<th style="text-align:right;padding:4px 6px;">360d Proj</th></tr>';

        for (var mi = 0; mi < report.materials.length; mi++) {
            var m = report.materials[mi];
            html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.05);">';
            html += '<td style="padding:3px 6px;">' + m.name + '</td>';
            html += '<td style="text-align:right;padding:3px 6px;">' + (Math.round(m.current * 100) / 100) + 'g</td>';

            // 90 days ago with color coding
            if (m.price90ago !== null) {
                var color90 = m.price90ago > m.current ? '#55a868' : (m.price90ago < m.current ? '#cc4444' : '#ccc');
                html += '<td style="text-align:right;padding:3px 6px;color:' + color90 + ';">' + (Math.round(m.price90ago * 100) / 100) + 'g</td>';
            } else {
                html += '<td style="text-align:right;padding:3px 6px;color:#666;">N/A</td>';
            }

            // 4 years (360 days) ago with color coding
            if (m.price360ago !== null) {
                var color360 = m.price360ago > m.current ? '#55a868' : (m.price360ago < m.current ? '#cc4444' : '#ccc');
                html += '<td style="text-align:right;padding:3px 6px;color:' + color360 + ';">' + (Math.round(m.price360ago * 100) / 100) + 'g</td>';
            } else {
                html += '<td style="text-align:right;padding:3px 6px;color:#666;">N/A</td>';
            }

            // 90-day projection with color coding
            if (m.projected90 !== null) {
                var pColor90 = m.projected90 < m.current ? '#55a868' : (m.projected90 > m.current ? '#cc4444' : '#ccc');
                html += '<td style="text-align:right;padding:3px 6px;color:' + pColor90 + ';">' + m.projected90 + 'g</td>';
            } else {
                html += '<td style="text-align:right;padding:3px 6px;color:#666;">N/A</td>';
            }

            // 4-year (360-day) projection with color coding
            if (m.projected360 !== null) {
                var pColor360 = m.projected360 < m.current ? '#55a868' : (m.projected360 > m.current ? '#cc4444' : '#ccc');
                html += '<td style="text-align:right;padding:3px 6px;color:' + pColor360 + ';">' + m.projected360 + 'g</td>';
            } else {
                html += '<td style="text-align:right;padding:3px 6px;color:#666;">N/A</td>';
            }
            html += '</tr>';
        }
        html += '</table>';

        // Legend
        html += '<div style="margin-top:8px;font-size:0.7rem;color:#888;">';
        html += '<span style="color:#55a868;">■</span> Price drop (favorable) &nbsp;';
        html += '<span style="color:#cc4444;">■</span> Price increase (unfavorable)';
        html += '</div>';

        html += '</div>';

        openModal('📊 Real Estate Report', html,
            '<button class="btn-medieval" data-action="closeModal">Close</button>');
    }

    // ═══════════════════════════════════════════════════════════
    //  SHIPS & VESSELS DIALOG
    // ═══════════════════════════════════════════════════════════
    function openShipsDialog() {
        if (typeof Player === 'undefined') return;
        if (Player.traveling) { toast('Cannot manage ships while traveling.', 'warning'); return; }

        var townId = Player.state.townId;
        var town = Engine.findTown(townId);
        if (!town || !town.isPort) { toast('You must be at a seaport to manage ships.', 'warning'); return; }

        var html = '<div style="max-height:500px;overflow-y:auto;">';

        // ── Section 1: Your Ships at this Port ──
        var shipsHere = Player.getShipsAtPort ? Player.getShipsAtPort(townId) : [];
        var maxShips = CONFIG.MAX_SHIPS_PER_PORT || 5;
        html += '<h3>⚓ Your Ships at ' + town.name + ' (' + shipsHere.length + '/' + maxShips + ' docked)</h3>';

        if (shipsHere.length === 0) {
            html += '<p style="color:#aaa;">No ships docked here. Build or sail one to this port.</p>';
        } else {
            for (var si = 0; si < shipsHere.length; si++) {
                var ship = shipsHere[si];
                var sType = CONFIG.SHIP_TYPES[ship.type] || {};
                var condition = ship.condition !== undefined ? ship.condition : 100;
                var condColor = condition >= 60 ? '#55a868' : condition >= 30 ? '#e67e22' : '#e74c3c';
                var condPct = Math.max(0, Math.min(100, condition));
                var dockFee = CONFIG.DOCKING_FEE_BASE[sType.sizeCategory || 'small'] || 10;

                // Status
                var status = '🟢 Idle';
                if (ship.assignedCaravan) status = '🔵 Assigned to caravan';
                if (ship.unpaidDocking) status = '⚠️ Unpaid docking';

                html += '<div style="border:1px solid #555;padding:8px;margin:4px 0;border-radius:4px;background:rgba(0,0,0,0.2);">';
                html += '<div><strong>' + (sType.icon || '⛵') + ' ' + (ship.name || sType.name || 'Ship') + '</strong> <span style="color:#aaa;font-size:0.8rem;">(' + (sType.name || ship.type) + ')</span></div>';
                html += '<div style="font-size:0.8rem;margin-top:2px;">📦 Cap: ' + (sType.capacity || 0) + ' | ⚡ Spd: ' + (sType.speed || 1).toFixed(1) + 'x | 🛡️ Def: ' + (sType.defense || 0) + ' | 👥 Min Crew: ' + (sType.minCrew || 1) + '</div>';

                // Condition bar
                html += '<div style="margin-top:4px;font-size:0.78rem;">🔧 Condition: <span style="color:' + condColor + ';">' + condPct + '%</span>';
                html += ' <div style="display:inline-block;width:80px;height:8px;background:rgba(255,255,255,0.1);border-radius:4px;vertical-align:middle;">';
                html += '<div style="width:' + condPct + '%;height:100%;background:' + condColor + ';border-radius:4px;"></div></div></div>';

                html += '<div style="font-size:0.78rem;color:#aaa;">' + status + ' | Docking: ' + dockFee + 'g/month</div>';

                // Buttons
                html += '<div style="margin-top:4px;">';
                html += '<button class="btn-medieval" onclick="Player.repairShip(\'' + ship.id + '\'); UI.openShipsDialog();" style="font-size:0.75rem;padding:3px 8px;margin:2px;"' + (condition >= 100 ? ' disabled' : '') + '>🔧 Repair</button>';
                if ((sType.maxAddons || 0) > 0) {
                    html += '<button class="btn-medieval" onclick="UI.showShipAddons(\'' + ship.id + '\')" style="font-size:0.75rem;padding:3px 8px;margin:2px;">📦 Addons';
                    if (ship.addons) html += ' (' + ship.addons.length + '/' + sType.maxAddons + ')';
                    html += '</button>';
                }
                html += '</div></div>';
            }
        }

        // ── Section 2: Build a Ship ──
        html += '<h3 style="margin-top:12px;">🏗️ Build a Ship</h3>';
        var atLimit = shipsHere.length >= maxShips;
        if (atLimit) {
            html += '<div style="font-size:0.8rem;color:#e67e22;margin-bottom:6px;">⚠️ Port is full (' + maxShips + '/' + maxShips + '). Sail a ship away to build more here.</div>';
        }

        for (var typeId in CONFIG.SHIP_TYPES) {
            var st = CONFIG.SHIP_TYPES[typeId];
            var totalCost = Player.getShipPrice ? Player.getShipPrice(typeId, townId) : 0;
            var canAfford = Player.gold >= totalCost;

            // Check materials
            var allMatsAvailable = true;
            var matParts = [];
            for (var matId in (st.materials || {})) {
                var needed = st.materials[matId];
                var playerHas = (Player.inventory && Player.inventory[matId]) || 0;
                var marketPrice = Engine.getResourcePrice ? Engine.getResourcePrice(townId, matId) : 0;
                var marketQty = Engine.getResourceSupply ? Engine.getResourceSupply(townId, matId) : 0;
                var needToBuy = Math.max(0, needed - playerHas);
                var hasEnough = playerHas >= needed;
                var marketHasEnough = needToBuy <= marketQty;
                if (!hasEnough && !marketHasEnough) allMatsAvailable = false;

                var matColor, indicator;
                if (hasEnough) {
                    matColor = '#55a868';
                    indicator = ' ✓ owned';
                } else if (marketHasEnough) {
                    matColor = '#d4a843';
                    indicator = ' 🛒 buy ' + needToBuy + ' @ ' + (marketPrice || 0).toFixed(1) + 'g ea';
                } else {
                    matColor = '#c44e52';
                    indicator = ' ✗ need ' + needToBuy + ', market has ' + marketQty;
                }
                matParts.push('<span style="color:' + matColor + ';">' + matId + ': ' + playerHas + '/' + needed + indicator + '</span>');
            }

            var canBuild = canAfford && allMatsAvailable && !atLimit;
            html += '<div style="border:1px solid #444;padding:6px;margin:3px 0;border-radius:4px;opacity:' + (canBuild ? '1' : '0.6') + ';">';
            html += '<div>' + (st.icon || '⛵') + ' <strong>' + st.name + '</strong> — <span style="color:#ffd700;">' + totalCost.toFixed(2) + 'g</span></div>';
            html += '<div style="font-size:0.75rem;color:#aaa;">' + (st.description || '') + '</div>';
            html += '<div style="font-size:0.8rem;margin-top:2px;">📦 Cap:' + st.capacity + ' ⚡ Spd:' + st.speed + ' 🛡️ Def:' + st.defense + ' 👥 Crew:' + st.minCrew + '</div>';

            if (matParts.length > 0) {
                html += '<div style="font-size:0.7rem;margin-top:2px;">📦 ' + matParts.join(', ') + '</div>';
            }

            html += '<button class="btn-medieval" onclick="UI.buyShip(\'' + typeId + '\'); UI.openShipsDialog();" style="font-size:0.75rem;padding:3px 8px;margin-top:3px;"' + (canBuild ? '' : ' disabled') + '>🏗️ Build</button>';
            if (atLimit) html += ' <span style="color:#c44e52;font-size:0.75rem;">Port full!</span>';
            if (!allMatsAvailable) html += ' <span style="color:#c44e52;font-size:0.75rem;">Missing materials!</span>';
            html += '</div>';
        }

        // ── Section 3: Ship Rentals Info ──
        html += '<h3 style="margin-top:12px;">📋 Ship Rentals</h3>';
        html += '<div style="font-size:0.8rem;color:#aaa;margin-bottom:6px;">Rent a ship per day for sea caravans without owning one.</div>';
        for (var rTypeId in CONFIG.SHIP_TYPES) {
            var rt = CONFIG.SHIP_TYPES[rTypeId];
            var rentalCost = Player.getShipRentalCost ? Player.getShipRentalCost(rTypeId, townId) : 0;
            html += '<div style="font-size:0.78rem;padding:2px 0;">' + (rt.icon || '⛵') + ' ' + rt.name + ' — <span style="color:#ffd700;">' + rentalCost.toFixed(1) + 'g/day</span> rental</div>';
        }
        html += '<div style="font-size:0.7rem;color:#888;margin-top:4px;">Select rental when creating a sea caravan.</div>';

        // ── Section 4: Ships at Other Ports (collapsible) ──
        var allShips = Player.state.ships || [];
        var otherShips = [];
        for (var oi = 0; oi < allShips.length; oi++) {
            if (allShips[oi].townId !== townId) otherShips.push(allShips[oi]);
        }
        if (otherShips.length > 0) {
            html += '<h3 style="margin-top:12px;cursor:pointer;" onclick="var el=document.getElementById(\'otherShipsSection\');el.style.display=el.style.display===\'none\'?\'block\':\'none\';">📍 Ships at Other Ports ▾</h3>';
            html += '<div id="otherShipsSection" style="display:none;">';
            var grouped = {};
            for (var gi = 0; gi < otherShips.length; gi++) {
                var gTownId = otherShips[gi].townId || 'unknown';
                if (!grouped[gTownId]) grouped[gTownId] = [];
                grouped[gTownId].push(otherShips[gi]);
            }
            for (var gKey in grouped) {
                var gTown = Engine.findTown(gKey);
                var gTownName = gTown ? gTown.name : gKey;
                var gNames = [];
                for (var gni = 0; gni < grouped[gKey].length; gni++) {
                    var gs = grouped[gKey][gni];
                    var gst = CONFIG.SHIP_TYPES[gs.type] || {};
                    gNames.push((gst.icon || '⛵') + ' ' + (gs.name || gst.name || 'Ship'));
                }
                html += '<div style="font-size:0.8rem;padding:2px 0;"><strong>' + gTownName + ':</strong> ' + gNames.join(', ') + '</div>';
            }
            html += '</div>';
        }

        html += '</div>';
        openModal('⛵ Ships & Vessels', html);
    }

    // ═══════════════════════════════════════════════════════════
    //  HOUSING DIALOG
    // ═══════════════════════════════════════════════════════════
    function openHousingDialog() {
        if (typeof Player === 'undefined') return;
        if (Player.traveling) { toast('Cannot manage housing while traveling.', 'warning'); return; }

        var html = '<div style="max-height:500px;overflow-y:auto;">';

        // Current houses
        var houses = Player.houses || [];
        html += '<h3>🏠 Your Properties (' + houses.length + ')</h3>';
        if (houses.length === 0) {
            html += '<p style="color:#aaa;">No properties owned. Buy land and build a home!</p>';
        } else {
            for (var i = 0; i < houses.length; i++) {
                var h = houses[i];
                var ht = CONFIG.HOUSING_TYPES.find(function(t) { return t.id === h.type; });
                if (!ht) continue;
                var town = Engine.findTown(h.townId);
                var isPrimary = h.id === Player.primaryHouseId;
                html += '<div style="border:1px solid ' + (isPrimary ? '#ffd700' : '#555') + ';padding:8px;margin:4px 0;border-radius:4px;background:rgba(0,0,0,0.2);">';
                html += '<div><strong>' + ht.icon + ' ' + ht.name + '</strong> in ' + (town ? town.name : '?') + (isPrimary ? ' ⭐ Primary' : '') + '</div>';
                html += '<div style="font-size:0.8rem;color:#aaa;">' + ht.description + '</div>';
                html += '<div style="font-size:0.8rem;">Storage: ' + ht.storage + ' | Comfort: ' + ht.comfort + ' | Security: ' + Math.round(ht.security * 100) + '%</div>';
                // Show installed addons
                if (h.addons && h.addons.length > 0 && CONFIG.HOUSE_ADDONS) {
                    var _addonNames = [];
                    for (var _ai = 0; _ai < h.addons.length; _ai++) {
                        var _aDef = CONFIG.HOUSE_ADDONS[h.addons[_ai]];
                        if (_aDef) _addonNames.push(_aDef.icon + ' ' + _aDef.name);
                    }
                    html += '<div style="font-size:0.78rem;color:#5ac85a;">Addons: ' + _addonNames.join(', ') + '</div>';
                }
                // Home storage contents + transfer UI
                var _hsUsed = Player.getHomeStorageUsed ? Player.getHomeStorageUsed(h) : 0;
                var _hsCap = Player.getHomeStorageCapacity ? Player.getHomeStorageCapacity(h) : (ht.storage || 0);
                var _hsPct = _hsCap > 0 ? Math.round(_hsUsed / _hsCap * 100) : 0;
                var _hsColor = _hsPct >= 90 ? '#e74c3c' : _hsPct >= 60 ? '#e67e22' : '#55a868';
                html += '<div style="font-size:0.78rem;margin-top:2px;">📦 Stored: <span style="color:' + _hsColor + ';">' + Math.round(_hsUsed) + '/' + _hsCap + '</span>';
                if (h.homeStorage) {
                    var _hItems = [];
                    for (var _hk in h.homeStorage) {
                        if (h.homeStorage[_hk] > 0) {
                            var _hr = typeof findResource === 'function' ? findResource(_hk) : null;
                            if (!_hr && typeof Player.findResource === 'function') _hr = Player.findResource(_hk);
                            _hItems.push((_hr ? (_hr.icon || '') + ' ' + _hr.name : _hk) + ': ' + h.homeStorage[_hk]);
                        }
                    }
                    if (_hItems.length > 0) html += ' — ' + _hItems.join(', ');
                }
                html += '</div>';
                // Horses stabled at home
                var _maxHomeHorses = (Player.hasSkill && Player.hasSkill('horse_mastery')) ? 4 : 2;
                var _homeHorses = h.horses || [];
                html += '<div style="font-size:0.78rem;">🐴 Horses: ' + _homeHorses.length + '/' + _maxHomeHorses;
                if (_homeHorses.length > 0) {
                    html += ' — ';
                    for (var _hhi = 0; _hhi < _homeHorses.length; _hhi++) {
                        var _hh = _homeHorses[_hhi];
                        html += (_hh.name || 'Horse') + ' ';
                        if (h.townId === Player.townId) html += '<button class="btn-medieval" onclick="UI.unstableHorseUI(\'' + h.id + '\',' + _hhi + ')" style="font-size:0.65rem;padding:1px 5px;">Take</button> ';
                    }
                }
                html += '</div>';
                // Transfer buttons (only when in same town)
                if (h.townId === Player.townId) {
                    html += '<button class="btn-medieval" onclick="UI.openHomeStorageUI(\'' + h.id + '\')" style="font-size:0.75rem;padding:3px 8px;margin:2px;">📦 Transfer Goods</button>';
                    if (Player.horses && Player.horses.length > 0 && _homeHorses.length < _maxHomeHorses) {
                        html += '<button class="btn-medieval" onclick="UI.stableHorseUI(\'' + h.id + '\')" style="font-size:0.75rem;padding:3px 8px;margin:2px;">🐴 Stable Horse</button>';
                    }
                    var _availAddons = Player.getAvailableAddons ? Player.getAvailableAddons(h.id) : [];
                    if (_availAddons.length > 0) {
                        html += '<button class="btn-medieval" onclick="UI.openHouseAddonsUI(\'' + h.id + '\')" style="font-size:0.75rem;padding:3px 8px;margin:2px;">🔧 Addons (' + _availAddons.length + ')</button>';
                    }
                }
                if (h.isRental) {
                    html += '<div style="color:#5ac85a;font-size:0.8rem;">💰 Rented — ' + (h.monthlyRent || 0) + 'g/month (total earned: ' + (h.rentAccumulated || 0) + 'g)</div>';
                    if (h.tenantId) {
                        var _tenant = Engine.findPerson(h.tenantId);
                        var _tName = _tenant ? ((_tenant.firstName || '') + ' ' + (_tenant.lastName || '')) : 'Unknown';
                        html += '<div style="font-size:0.78rem;color:#aaa;">👤 Tenant: ' + _tName + (h.tenantType === 'em' ? ' (Elite Merchant)' : '') + '</div>';
                        if (h.evictionDay) {
                            html += '<div style="font-size:0.78rem;color:#c44e52;">⚠️ Eviction pending — leaves by day ' + h.evictionDay + '</div>';
                        }
                    } else {
                        html += '<div style="font-size:0.78rem;color:#888;">🔍 Waiting for tenant...</div>';
                    }
                }
                if (h.monthlyMaintenance) {
                    html += '<div style="font-size:0.78rem;color:#c4a35a;">🏢 Apartment — monthly maintenance: ' + h.monthlyMaintenance + 'g</div>';
                }
                html += '<div style="margin-top:4px;">';
                if (!isPrimary) html += '<button class="btn-medieval" onclick="UI.setPrimaryHouseUI(\'' + h.id + '\')" style="font-size:0.75rem;padding:3px 8px;margin:2px;">⭐ Set Primary</button>';
                // Tents: only Leave option (stop renting), no rent-out/upgrade/sell
                if (ht.fromTentCamp) {
                    html += '<button class="btn-medieval" onclick="UI.leaveTentUI(\'' + h.id + '\')" style="font-size:0.75rem;padding:3px 8px;margin:2px;color:#c44e52;">🚪 Leave Tent</button>';
                } else {
                    // Rent out (not for apartments owned from a building — those are units, not full houses)
                    if (!ht.fromApartmentBuilding) {
                        html += '<button class="btn-medieval" onclick="UI.rentOutHouseUI(\'' + h.id + '\')" style="font-size:0.75rem;padding:3px 8px;margin:2px;">' + (h.isRental ? '🏠 Stop Renting' : '💰 Rent Out') + '</button>';
                        if (h.tenantId && !h.evictionDay) html += '<button class="btn-medieval" onclick="UI.evictTenantUI(\'' + h.id + '\')" style="font-size:0.75rem;padding:3px 8px;margin:2px;color:#c44e52;">🚪 Evict</button>';
                    }
                    // Upgrade only for land-based houses (not apartments, not tents, not portable)
                    if (!ht.fromApartmentBuilding && !ht.portable) {
                        html += '<button class="btn-medieval" onclick="UI.upgradeHouseUI(\'' + h.id + '\')" style="font-size:0.75rem;padding:3px 8px;margin:2px;">🏗️ Upgrade</button>';
                    }
                    // Sell — opens listing UI with price recommendation
                    html += '<button class="btn-medieval" onclick="UI.sellHouseUI(\'' + h.id + '\')" style="font-size:0.75rem;padding:3px 8px;margin:2px;color:#c44e52;">🏚️ Sell</button>';
                }
                html += '</div></div>';
            }
        }

        // Available to buy (if player is in a town)
        if (!Player.traveling && Player.townId) {
            var town = Engine.findTown(Player.townId);
            if (town) {
                html += '<h3 style="margin-top:12px;">🏗️ Buy Housing in ' + town.name + '</h3>';
                var ownedLand = Player.getOwnedLand(Player.townId);
                var usedLand = Player.getUsedLandSlots ? Player.getUsedLandSlots(Player.townId) : 0;
                var _rankIdx = Player.getPlayerRankIndex ? Player.getPlayerRankIndex() : 0;
                var _rankCfg = CONFIG.SOCIAL_RANKS[_rankIdx];
                var _rankMaxLand = (_rankCfg && _rankCfg.maxLand !== undefined) ? _rankCfg.maxLand : '∞';
                var _totalLandOwned = 0;
                if (Player.state && Player.state.landOwned) { for (var _lk in Player.state.landOwned) _totalLandOwned += (Player.state.landOwned[_lk] || 0); }
                var _hdSub = Player.getActiveSubsidy ? Player.getActiveSubsidy(Player.townId) : null;
                var _hdCost = Player.getLandCost ? Player.getLandCost(Player.townId) : '?';
                var _hdBtnTxt = 'Buy Land (' + _hdCost + 'g)';
                if (_hdSub) _hdBtnTxt = 'Buy Land (' + _hdCost + 'g) ⭐ Subsidy!';
                html += '<div style="font-size:0.85rem;margin-bottom:8px;">Land plots: ' + usedLand + '/' + ownedLand + ' used (global: ' + _totalLandOwned + '/' + _rankMaxLand + ' for ' + (_rankCfg ? _rankCfg.name : 'your rank') + ') | <button class="btn-medieval" onclick="UI.buyLandUI()" style="font-size:0.75rem;padding:2px 8px;">' + _hdBtnTxt + '</button></div>';
                // Show subsidized (locked) plots
                var _subLand = (Player.state && Player.state.subsidizedLand && Player.state.subsidizedLand[Player.townId]) || [];
                if (_subLand.length > 0) {
                    html += '<div style="font-size:0.78rem;color:#55a868;margin-bottom:6px;">🔒 Subsidized plots: ';
                    var _slNames = [];
                    for (var _sli = 0; _sli < _subLand.length; _sli++) {
                        var _slBt = Engine.findBuildingType(_subLand[_sli].buildingType);
                        _slNames.push(_slBt ? _slBt.name : _subLand[_sli].buildingType);
                    }
                    html += _slNames.join(', ') + '</div>';
                }

                for (var j = 0; j < CONFIG.HOUSING_TYPES.length; j++) {
                    var htype = CONFIG.HOUSING_TYPES[j];
                    if (htype.id === 'bedroll' || htype.id === 'inn_room') continue;
                    if (htype.notBuildable || htype.fromApartmentBuilding) continue;
                    if (htype.requiresPort && !town.isPort) continue;
                    if (htype.portable && htype.requiresHorse && (!Player.horses || Player.horses.length === 0)) continue;
                    var catOrder = ['village', 'town', 'city', 'capital_city'];
                    if (htype.minTownCategory && catOrder.indexOf(town.category || 'village') < catOrder.indexOf(htype.minTownCategory)) continue;
                    var costInfo = Player.getHousingCost(htype.id, Player.townId);
                    var totalCost = costInfo.total || 0;
                    var canAfford = Player.gold >= totalCost;
                    var matsAvailable = costInfo.available !== false;
                    var needsLand = htype.id !== 'apartment' && !htype.portable && usedLand >= ownedLand;
                    var canBuild = canAfford && matsAvailable && !needsLand;
                    // Rank check
                    if (htype.minRank) {
                        var bestRank = 0;
                        var sr = Player.state.socialRank || {};
                        for (var rk in sr) { if ((sr[rk] || 0) > bestRank) bestRank = sr[rk]; }
                        if (bestRank < htype.minRank) canBuild = false;
                    }
                    html += '<div style="border:1px solid #444;padding:6px;margin:3px 0;border-radius:4px;opacity:' + (canBuild ? '1' : '0.6') + ';">';
                    html += '<div>' + htype.icon + ' <strong>' + htype.name + '</strong> — <span style="color:#ffd700;">' + totalCost.toFixed(2) + 'g</span>';
                    if (costInfo.laborCost) html += ' <span class="text-dim" style="font-size:0.75rem;">(materials: ' + costInfo.materialCost.toFixed(2) + 'g + labor: ' + costInfo.laborCost.toFixed(2) + 'g)</span>';
                    html += '</div>';
                    html += '<div style="font-size:0.75rem;color:#aaa;">' + htype.description + '</div>';
                    // Material list — shows owned + market availability
                    if (htype.materials) {
                        html += '<div style="font-size:0.7rem;margin-top:2px;">';
                        var matParts = [];
                        for (var mid in costInfo.breakdown) {
                            var mb = costInfo.breakdown[mid];
                            var hasEnough = mb.playerHas >= mb.needed;
                            var matColor, indicator;
                            if (hasEnough) {
                                matColor = '#55a868';
                                indicator = ' ✓ owned';
                            } else if (mb.needToBuy <= mb.marketHas) {
                                matColor = '#d4a843';
                                indicator = ' 🛒 buy ' + mb.needToBuy + ' @ ' + mb.unitPrice.toFixed(1) + 'g ea';
                            } else {
                                matColor = '#c44e52';
                                indicator = ' ✗ need ' + mb.needToBuy + ', market has ' + mb.marketHas;
                            }
                            matParts.push('<span style="color:' + matColor + ';">' + mid + ': ' + mb.needed + ' (' + mb.playerHas + ' owned' + indicator + ')</span>');
                        }
                        html += '📦 ' + matParts.join(', ') + '</div>';
                    }
                    html += '<button class="btn-medieval" onclick="UI.buyHouseUI(\'' + htype.id + '\')" style="font-size:0.75rem;padding:3px 8px;margin-top:3px;"' + (canBuild ? '' : ' disabled') + '>🏗️ Build</button>';
                    if (needsLand) html += ' <span style="color:#c44e52;font-size:0.75rem;">Need land!</span>';
                    if (!matsAvailable) html += ' <span style="color:#c44e52;font-size:0.75rem;">Missing materials!</span>';
                    if (htype.minRank) {
                        var reqName = CONFIG.SOCIAL_RANKS && CONFIG.SOCIAL_RANKS[htype.minRank] ? CONFIG.SOCIAL_RANKS[htype.minRank].name : 'Rank ' + htype.minRank;
                        html += ' <span style="font-size:0.7rem;color:#aaa;">Requires: ' + reqName + '</span>';
                    }
                    html += '</div>';
                }
            }
        }

        html += '</div>';
        openModal('🏠 Housing & Property', html);
    }

    // ── HOUSE ADDONS UI ──
    function openHouseAddonsUI(houseId) {
        var houses = Player.state.houses || Player.houses || [];
        var house = houses.find(function(h) { return h.id === houseId; });
        if (!house) { toast('House not found.', 'error'); return; }
        var ht = CONFIG.HOUSING_TYPES.find(function(t) { return t.id === house.type; });
        var available = Player.getAvailableAddons ? Player.getAvailableAddons(houseId) : [];
        var installed = house.addons || [];

        var html = '<div style="max-height:450px;overflow-y:auto;">';
        html += '<div style="font-size:0.85rem;margin-bottom:8px;">' + (ht ? ht.icon : '🏠') + ' <strong>' + (ht ? ht.name : 'House') + '</strong></div>';

        // Installed addons
        if (installed.length > 0) {
            html += '<h4 style="margin:8px 0 4px;color:#5ac85a;">Installed Addons</h4>';
            for (var ii = 0; ii < installed.length; ii++) {
                var iDef = CONFIG.HOUSE_ADDONS ? CONFIG.HOUSE_ADDONS[installed[ii]] : null;
                if (!iDef) continue;
                html += '<div style="border:1px solid #3a5a3a;padding:4px 6px;margin:3px 0;border-radius:3px;background:rgba(90,200,90,0.08);">';
                html += '<strong>' + iDef.icon + ' ' + iDef.name + '</strong> ✅';
                html += '<div style="font-size:0.78rem;color:#aaa;">' + iDef.description + '</div>';
                html += '</div>';
            }
        }

        // Available addons
        if (available.length > 0) {
            html += '<h4 style="margin:12px 0 4px;">Available Addons</h4>';
            for (var ai = 0; ai < available.length; ai++) {
                var addon = available[ai];
                html += '<div style="border:1px solid #555;padding:6px;margin:4px 0;border-radius:4px;background:rgba(0,0,0,0.2);">';
                html += '<div><strong>' + addon.icon + ' ' + addon.name + '</strong></div>';
                html += '<div style="font-size:0.78rem;color:#aaa;">' + addon.desc + '</div>';
                html += '<div style="font-size:0.78rem;margin-top:2px;">';
                html += '💰 ' + addon.goldCost + 'g';
                if (addon.materials) {
                    var matParts = [];
                    for (var mk in addon.materials) {
                        var mRes = Object.values(RESOURCE_TYPES).find(function(r) { return r.id === mk; });
                        matParts.push((mRes ? mRes.icon + ' ' : '') + addon.materials[mk] + ' ' + (mRes ? mRes.name : mk));
                    }
                    html += ' | ' + matParts.join(', ');
                }
                html += '</div>';
                html += '<button class="btn-medieval" onclick="UI.doInstallAddon(\'' + houseId + '\',\'' + addon.id + '\')" style="font-size:0.75rem;padding:3px 10px;margin-top:4px;color:#e8dcc8;">🔧 Install</button>';
                html += '</div>';
            }
        } else if (installed.length === 0) {
            html += '<div style="font-size:0.8rem;color:#888;">No addons available for this house type.</div>';
        } else {
            html += '<div style="font-size:0.8rem;color:#888;margin-top:8px;">All available addons installed! ✅</div>';
        }

        html += '</div>';
        openModal('🔧 House Addons', html,
            '<button class="btn-medieval" onclick="UI.openHousingDialog()">Back to Housing</button>');
    }

    function doInstallAddon(houseId, addonId) {
        var result = Player.installAddon(houseId, addonId);
        if (result.success) {
            toast(result.message, 'success');
        } else {
            toast(result.message, 'warning');
        }
        openHouseAddonsUI(houseId); // refresh
    }

    // ── HOME STORAGE TRANSFER UI ──
    function openHomeStorageUI(houseId) {
        var houses = Player.state.houses || Player.houses || [];
        var house = houses.find(function(h) { return h.id === houseId; });
        if (!house) { toast('House not found.', 'error'); return; }
        var ht = CONFIG.HOUSING_TYPES.find(function(t) { return t.id === house.type; });
        var cap = Player.getHomeStorageCapacity ? Player.getHomeStorageCapacity(house) : (ht ? ht.storage : 0);
        var used = Player.getHomeStorageUsed ? Player.getHomeStorageUsed(house) : 0;

        var html = '<div style="max-height:400px;overflow-y:auto;">';
        html += '<div style="font-size:0.85rem;margin-bottom:8px;">📦 Storage: <strong>' + Math.round(used) + '/' + cap + '</strong></div>';

        // Items stored in home — withdraw buttons
        html += '<h4 style="margin:8px 0 4px;">Stored at Home</h4>';
        var hasStored = false;
        if (house.homeStorage) {
            for (var sk in house.homeStorage) {
                if (house.homeStorage[sk] <= 0) continue;
                hasStored = true;
                var sr = findResource(sk);
                var sName = sr ? (sr.icon || '') + ' ' + sr.name : sk;
                var sQty = house.homeStorage[sk];
                html += '<div style="display:flex;align-items:center;gap:6px;margin:2px 0;font-size:0.8rem;">';
                html += '<span style="min-width:140px;">' + sName + ': ' + sQty + '</span>';
                html += '<button class="btn-trade buy" style="font-size:0.65rem;padding:1px 6px;" onclick="UI._homeWithdraw(\'' + houseId + '\',\'' + sk + '\',1)">Take 1</button>';
                if (sQty >= 5) html += '<button class="btn-trade buy" style="font-size:0.65rem;padding:1px 6px;" onclick="UI._homeWithdraw(\'' + houseId + '\',\'' + sk + '\',5)">5</button>';
                html += '<button class="btn-trade buy" style="font-size:0.65rem;padding:1px 6px;" onclick="UI._homeWithdraw(\'' + houseId + '\',\'' + sk + '\',' + sQty + ')">All</button>';
                html += '</div>';
            }
        }
        if (!hasStored) html += '<div style="color:#888;font-size:0.8rem;">Empty</div>';

        // Player inventory — deposit buttons
        html += '<h4 style="margin:12px 0 4px;">Your Inventory</h4>';
        var hasInv = false;
        var inv = Player.inventory || {};
        for (var ik in inv) {
            if (inv[ik] <= 0) continue;
            var ir = findResource(ik);
            if (!ir) continue;
            if (ir.category === 'livestock' || ik === 'horses') continue;
            hasInv = true;
            var iName = (ir.icon || '') + ' ' + ir.name;
            var iQty = inv[ik];
            html += '<div style="display:flex;align-items:center;gap:6px;margin:2px 0;font-size:0.8rem;">';
            html += '<span style="min-width:140px;">' + iName + ': ' + iQty + '</span>';
            html += '<button class="btn-trade sell" style="font-size:0.65rem;padding:1px 6px;" onclick="UI._homeDeposit(\'' + houseId + '\',\'' + ik + '\',1)">Store 1</button>';
            if (iQty >= 5) html += '<button class="btn-trade sell" style="font-size:0.65rem;padding:1px 6px;" onclick="UI._homeDeposit(\'' + houseId + '\',\'' + ik + '\',5)">5</button>';
            html += '<button class="btn-trade sell" style="font-size:0.65rem;padding:1px 6px;" onclick="UI._homeDeposit(\'' + houseId + '\',\'' + ik + '\',' + iQty + ')">All</button>';
            html += '</div>';
        }
        if (!hasInv) html += '<div style="color:#888;font-size:0.8rem;">Nothing to store</div>';

        html += '</div>';
        openModal('📦 ' + (ht ? ht.name : 'Home') + ' Storage', html,
            '<button class="btn-medieval" onclick="UI.openHousingDialog()">Back</button>');
    }

